-- ===========================================================================
-- MATHFLIP — MỞ RỘNG NỘI DUNG HỌC KỲ I: CHƯƠNG III, IV, V
-- (Toán 7, Kết nối tri thức với cuộc sống) · BẢN NHÁP, giáo viên duyệt
--
-- TỆP NÀY ĐƯỢC SINH TỰ ĐỘNG bằng lệnh (trong thư mục dfle-engine):
--     node cli/emit-hoc-ky-1.js > ../dfle-web/supabase/37-mo-rong-hoc-ky-1.sql
--
--   Chương III: 11 đơn vị · 14 mã lỗi · 88 câu · 42 gợi ý · 14 vi bài học
--   Chương IV: 13 đơn vị · 18 mã lỗi · 104 câu · 54 gợi ý · 18 vi bài học
--   Chương V: 9 đơn vị · 18 mã lỗi · 72 câu · 54 gợi ý · 18 vi bài học
--   Ngân hàng hoạt động Chương II–V: 39 hoạt động (bản nháp)
--
-- Chạy trong Supabase → SQL Editor, sau các tệp 01 … 35. Đã chạy bản cũ của tệp này thì chạy lại bản mới:
-- các mục được tách (M1B, M2B) sẽ được thêm, câu hỏi chuyển sang mục mới, link video được gắn.
-- Chạy lại nhiều lần vẫn an toàn (on conflict … do update / do nothing).
-- ===========================================================================

do $$
begin
  if to_regclass('public.knowledge_units') is null then
    raise exception E'\n\n>>> DỪNG LẠI: Phải chạy 01-schema.sql TRƯỚC tệp này. <<<\n';
  end if;
  if to_regclass('public.error_hints') is null then
    raise exception E'\n\n>>> DỪNG LẠI: Phải chạy 05-goi-y-theo-tang.sql TRƯỚC tệp này. <<<\n';
  end if;
  if to_regclass('public.micro_lessons') is null then
    raise exception E'\n\n>>> DỪNG LẠI: Phải chạy 08-vi-bai-hoc.sql TRƯỚC tệp này. <<<\n';
  end if;
  if to_regclass('public.mm_activities') is null then
    raise exception E'\n\n>>> DỪNG LẠI: Phải chạy 35-mathmind.sql TRƯỚC tệp này. <<<\n';
  end if;
end $$;

-- ------------------------------------------------ 0. CỘT HÌNH VẼ / BIỂU ĐỒ CHO CÂU HỎI
-- jsonb: {"loai":"quat"|"doan-thang"|"hinh", ...}. Học sinh được đọc (không chứa đáp án).
alter table public.questions add column if not exists hinh jsonb;
alter table public.contents add column if not exists nguon text;
grant select (hinh) on public.questions to authenticated;
create or replace view public.questions_public
with (security_invoker = true) as
  select question_id, ku_id, level, stem, expected_time_sec, hinh from public.questions;

