-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-KB-01', 'C3-B8-M1', 'Cho rằng hai góc có tổng 180° là hai góc kề bù dù không có cạnh chung; hoặc hai góc kề nhau là kề bù. Ví dụ: Hai góc 70° và 110° ở hai chỗ khác nhau được gọi là kề bù', 'VBH-KB-01'),
  ('E-KB-02', 'C3-B8-M1', 'Tính góc kề bù bằng 90° trừ góc đã biết (nhầm với hai góc phụ nhau). Ví dụ: Góc xOy = 60°, tính góc kề bù là 30°', 'VBH-KB-02'),
  ('E-DDI-01', 'C3-B8-M1B', 'Nhận diện hai góc đối đỉnh sai: coi hai góc bằng nhau chung đỉnh là đối đỉnh, hoặc coi hai góc kề bù là đối đỉnh. Ví dụ: Góc xOy và góc yOx'' (kề bù) được gọi là đối đỉnh', 'VBH-DDI-01'),
  ('E-PG-01', 'C3-B8-M2', 'Cho rằng tia nằm giữa hai cạnh của góc là tia phân giác, không cần hai góc tạo thành bằng nhau. Ví dụ: Oz nằm giữa Ox, Oy với góc xOz = 30°, góc zOy = 50° vẫn được gọi là phân giác', 'VBH-PG-01'),
  ('E-PG-02', 'C3-B8-M2', 'Tính góc với tia phân giác sai: nhân đôi thay vì chia đôi hoặc ngược lại. Ví dụ: Góc xOy = 70°, Oz là phân giác nên góc xOz = 140°', 'VBH-PG-02'),
  ('E-SLT-01', 'C3-B9-M1', 'Nhầm cặp góc so le trong với cặp góc đồng vị hoặc cặp góc trong cùng phía. Ví dụ: Gọi hai góc nằm cùng phía cát tuyến, trong dải hai đường thẳng là so le trong', 'VBH-SLT-01'),
  ('E-SLT-02', 'C3-B9-M1', 'Cho rằng cặp góc so le trong (đồng vị) luôn bằng nhau, kể cả khi hai đường thẳng không song song. Ví dụ: Hai đường thẳng cắt nhau ở xa nhưng vẫn kết luận hai góc so le trong bằng nhau', 'VBH-SLT-02'),
  ('E-DHSS-01', 'C3-B9-M2', 'Dùng cặp góc đối đỉnh hoặc kề bù để kết luận hai đường thẳng song song. Ví dụ: Vì hai góc đối đỉnh bằng nhau nên a // b', 'VBH-DHSS-01'),
  ('E-DHSS-02', 'C3-B9-M2', 'Cho rằng hai đường thẳng cùng vuông góc với đường thẳng thứ ba thì vuông góc với nhau (hoặc cắt nhau). Ví dụ: a ⊥ c, b ⊥ c nên a ⊥ b', 'VBH-DHSS-02'),
  ('E-EUC-01', 'C3-B10-M1', 'Cho rằng qua một điểm ngoài đường thẳng có thể vẽ nhiều đường thẳng song song (hoặc không vẽ được). Ví dụ: Qua M ngoài a, vẽ hai đường thẳng khác nhau cùng song song với a', 'VBH-EUC-01'),
  ('E-TCSS-01', 'C3-B10-M2', 'Cho rằng hai góc trong cùng phía bằng nhau (thay vì bù nhau) khi có hai đường thẳng song song. Ví dụ: a // b, góc trong cùng phía 70° thì góc kia cũng 70°', 'VBH-TCSS-01'),
  ('E-TCSS-02', 'C3-B10-M2', 'Không vận dụng được: c ⊥ a và a // b thì c ⊥ b; hai đường cùng song song với đường thứ ba thì song song với nhau. Ví dụ: a // b, c ⊥ a nhưng em nói "chưa biết góc giữa c và b"', 'VBH-TCSS-02'),
  ('E-DL-01', 'C3-B11-M1', 'Nhầm giả thiết với kết luận của định lí. Ví dụ: Định lí "Hai góc đối đỉnh thì bằng nhau": viết giả thiết là "hai góc bằng nhau"', 'VBH-DL-01'),
  ('E-DL-02', 'C3-B11-M1B', 'Coi việc đo trên hình hoặc thử vài ví dụ là chứng minh; cho rằng đảo một định lí thì luôn đúng. Ví dụ: Đo thấy hai góc bằng nhau nên "đã chứng minh"; từ "đối đỉnh thì bằng nhau" suy ra "bằng nhau thì đối đỉnh"', 'VBH-DL-02')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

