  ('C3-B8-M1-Q06', 'C3-B8-M1', 3, 'Góc xOy và góc yOz kề bù, góc xOy = 3 · góc yOz. Số đo góc yOz là:', 'A', 90, null),
  ('C3-B8-M1-Q07', 'C3-B8-M1B', 4, 'Hai đường thẳng cắt nhau tạo thành bốn góc. Nếu một góc bằng 90° thì ba góc còn lại:', 'A', 120, null),
  ('C3-B8-M1-Q08', 'C3-B8-M1B', 4, 'Ba đường thẳng cùng đi qua O tạo thành sáu góc (không có góc bẹt). Có bao nhiêu cặp góc đối đỉnh (mỗi góc nhỏ hơn 180°)?', 'A', 120, '{"loai":"hinh","moTa":"Ba đường thẳng phân biệt xx'', yy'', zz'' cùng đi qua O."}'::jsonb),
  ('C3-B8-M2-Q01', 'C3-B8-M2', 1, 'Góc xOy = 80°, Oz là tia phân giác của góc xOy. Góc xOz bằng:', 'A', 45, null),
  ('C3-B8-M2-Q02', 'C3-B8-M2', 1, 'Tia Oz là tia phân giác của góc xOy khi:', 'A', 45, null),
  ('C3-B8-M2-Q03', 'C3-B8-M2', 2, 'Ot là tia phân giác của góc mOn, góc mOt = 35°. Góc mOn bằng:', 'A', 60, null),
  ('C3-B8-M2-Q04', 'C3-B8-M2', 2, 'Tia Oz nằm giữa hai tia Ox, Oy; góc xOz = 30°, góc xOy = 70°. Oz có phải tia phân giác của góc xOy không?', 'A', 60, null),
  ('C3-B8-M2-Q05', 'C3-B8-M2', 3, 'Góc xOy = 120°, Oz là phân giác của góc xOy, Ot là phân giác của góc xOz. Góc tOy bằng:', 'A', 90, null),
  ('C3-B8-M2-Q06', 'C3-B8-M2', 3, 'Góc xOy = 50°, Ox'' là tia đối của tia Ox, Om là phân giác của góc x''Oy. Góc x''Om bằng:', 'A', 90, '{"loai":"hinh","moTa":"Góc xOy = 50°; Ox'' là tia đối của Ox; Om là tia phân giác của góc x''Oy."}'::jsonb),
  ('C3-B8-M2-Q07', 'C3-B8-M2', 4, 'Hai góc kề bù xOy và yOx''. Om là phân giác góc xOy, On là phân giác góc yOx''. Góc mOn bằng:', 'A', 120, '{"loai":"hinh","moTa":"Hai góc kề bù xOy và yOx''; Om, On lần lượt là tia phân giác của góc xOy và góc yOx''."}'::jsonb),
  ('C3-B8-M2-Q08', 'C3-B8-M2', 4, 'Hai đường thẳng xx'', yy'' cắt nhau tại O. Ot là phân giác của góc xOy. Tia đối Ot'' của tia Ot là phân giác của góc nào?', 'A', 120, '{"loai":"hinh","moTa":"Hai đường thẳng xx'', yy'' cắt nhau tại O; Ot là phân giác của góc xOy; Ot'' là tia đối của Ot."}'::jsonb),
  ('C3-B9-M1-Q01', 'C3-B9-M1', 1, 'Theo hình, cặp góc nào là cặp góc so le trong?', 'A', 45, '{"loai":"hinh","moTa":"Đường thẳng c cắt hai đường thẳng a và b lần lượt tại A và B. Tại A có bốn góc A1, A2, A3, A4; tại B có bốn góc B1, B2, B3, B4, đánh số theo cùng chiều kim đồng hồ bắt đầu từ góc phía trên bên phải; A3 và B1 nằm trong dải giữa a và b, khác phía đối với c."}'::jsonb),
  ('C3-B9-M1-Q02', 'C3-B9-M1', 1, 'Theo hình, cặp góc nào là cặp góc đồng vị?', 'A', 45, '{"loai":"hinh","moTa":"Đường thẳng c cắt hai đường thẳng a và b lần lượt tại A và B. Tại A có bốn góc A1, A2, A3, A4; tại B có bốn góc B1, B2, B3, B4, đánh số theo cùng chiều kim đồng hồ bắt đầu từ góc phía trên bên phải; A3 và B1 nằm trong dải giữa a và b, khác phía đối với c."}'::jsonb),
  ('C3-B9-M1-Q03', 'C3-B9-M1', 2, 'Hai góc so le trong là hai góc:', 'A', 60, null),
  ('C3-B9-M1-Q04', 'C3-B9-M1', 2, 'Đường thẳng c cắt hai đường thẳng a, b (a, b cắt nhau ở điểm khác). Hai góc so le trong:', 'A', 60, null),
  ('C3-B9-M1-Q05', 'C3-B9-M1', 3, 'Theo hình, biết A3 = B1 = 60°. Khi đó góc A2 và góc B2 lần lượt là:', 'A', 90, '{"loai":"hinh","moTa":"Đường thẳng c cắt hai đường thẳng a và b lần lượt tại A và B. Tại A có bốn góc A1, A2, A3, A4; tại B có bốn góc B1, B2, B3, B4, đánh số theo cùng chiều kim đồng hồ bắt đầu từ góc phía trên bên phải; A3 và B1 nằm trong dải giữa a và b, khác phía đối với c."}'::jsonb),
  ('C3-B9-M1-Q06', 'C3-B9-M1', 3, 'Một bạn nói: "Hai góc đồng vị luôn bằng nhau với mọi cách vẽ". Nhận xét nào ĐÚNG?', 'A', 90, null),
  ('C3-B9-M1-Q07', 'C3-B9-M1', 4, 'Đường thẳng c cắt a, b tại A, B. Ở mỗi giao điểm có 4 góc. Có tất cả bao nhiêu cặp góc so le trong và bao nhiêu cặp góc đồng vị?', 'A', 120, null),
  ('C3-B9-M1-Q08', 'C3-B9-M1', 4, 'Theo hình, biết A4 = B2. Có thể suy ra cặp góc nào bằng nhau?', 'A', 120, '{"loai":"hinh","moTa":"Đường thẳng c cắt hai đường thẳng a và b lần lượt tại A và B. Tại A có bốn góc A1, A2, A3, A4; tại B có bốn góc B1, B2, B3, B4, đánh số theo cùng chiều kim đồng hồ bắt đầu từ góc phía trên bên phải; A3 và B1 nằm trong dải giữa a và b, khác phía đối với c."}'::jsonb),
  ('C3-B9-M2-Q01', 'C3-B9-M2', 1, 'Đường thẳng c cắt a, b và trong các góc tạo thành có một cặp góc so le trong bằng nhau. Khi đó:', 'A', 45, null),
  ('C3-B9-M2-Q02', 'C3-B9-M2', 1, 'Hai đường thẳng phân biệt a, b cùng vuông góc với đường thẳng c. Khi đó:', 'A', 45, null),
  ('C3-B9-M2-Q03', 'C3-B9-M2', 2, 'Để chứng minh a // b, bạn An viết: "Vì góc A1 và góc A3 đối đỉnh nên bằng nhau, do đó a // b". Nhận xét nào ĐÚNG?', 'A', 60, '{"loai":"hinh","moTa":"Đường thẳng c cắt hai đường thẳng a và b lần lượt tại A và B. Tại A có bốn góc A1, A2, A3, A4; tại B có bốn góc B1, B2, B3, B4, đánh số theo cùng chiều kim đồng hồ bắt đầu từ góc phía trên bên phải; A3 và B1 nằm trong dải giữa a và b, khác phía đối với c."}'::jsonb),
  ('C3-B9-M2-Q04', 'C3-B9-M2', 2, 'Theo hình, biết A1 = 70°, B1 = 70°. Kết luận nào ĐÚNG?', 'A', 60, '{"loai":"hinh","moTa":"Đường thẳng c cắt hai đường thẳng a và b lần lượt tại A và B. Tại A có bốn góc A1, A2, A3, A4; tại B có bốn góc B1, B2, B3, B4, đánh số theo cùng chiều kim đồng hồ bắt đầu từ góc phía trên bên phải; A3 và B1 nằm trong dải giữa a và b, khác phía đối với c."}'::jsonb),
  ('C3-B9-M2-Q05', 'C3-B9-M2', 3, 'Hình thang ABCD có góc A = góc D = 90° (AB và CD là hai đáy). Vì sao AB // CD?', 'A', 90, '{"loai":"hinh","moTa":"Tứ giác ABCD có AD vuông góc với AB tại A và vuông góc với CD tại D."}'::jsonb),
  ('C3-B9-M2-Q06', 'C3-B9-M2', 3, 'Theo hình, biết A3 = 65°, B2 = 115°. Hai đường thẳng a và b:', 'A', 90, '{"loai":"hinh","moTa":"Đường thẳng c cắt hai đường thẳng a và b lần lượt tại A và B. Tại A có bốn góc A1, A2, A3, A4; tại B có bốn góc B1, B2, B3, B4, đánh số theo cùng chiều kim đồng hồ bắt đầu từ góc phía trên bên phải; A3 và B1 nằm trong dải giữa a và b, khác phía đối với c."}'::jsonb),
  ('C3-B9-M2-Q07', 'C3-B9-M2B', 4, 'Dùng ê ke vẽ đường thẳng b đi qua A và song song với a như SGK (trượt ê ke dọc thước). Cách vẽ này dựa trên:', 'A', 120, null),
  ('C3-B9-M2-Q08', 'C3-B9-M2B', 4, 'Cho góc xAy = 50°, trên tia Ay lấy điểm B. Vẽ tia Bz sao cho góc ABz = 50° và hai tia Bz, Ax nằm ở hai phía của đường thẳng AB. Khi đó:', 'A', 120, '{"loai":"hinh","moTa":"Góc xAy = 50°; B thuộc Ay; tia Bz sao cho góc ABz = 50°, Bz và Ax nằm ở hai phía của đường thẳng AB."}'::jsonb),
  ('C3-B10-M1-Q01', 'C3-B10-M1', 1, 'Qua điểm M nằm ngoài đường thẳng a, có bao nhiêu đường thẳng song song với a?', 'A', 45, null),
  ('C3-B10-M1-Q02', 'C3-B10-M1', 1, 'Phát biểu nào là tiên đề Euclid?', 'A', 45, null),
  ('C3-B10-M1-Q03', 'C3-B10-M1', 2, 'Qua M ngoài a, bạn Lan vẽ được hai đường thẳng b và c cùng song song với a. Kết luận nào ĐÚNG?', 'A', 60, null),
  ('C3-B10-M1-Q04', 'C3-B10-M1', 2, 'Cho a // b. Đường thẳng c cắt a. Khi đó:', 'A', 60, null),
  ('C3-B10-M1-Q05', 'C3-B10-M1', 3, 'Phát biểu nào ĐÚNG?', 'A', 90, null),
  ('C3-B10-M1-Q06', 'C3-B10-M1', 3, 'Cho điểm M không thuộc a. Đường thẳng b đi qua M và b // a; đường thẳng c đi qua M và c // a. Ta suy ra b ≡ c theo:', 'A', 90, null),
  ('C3-B10-M1-Q07', 'C3-B10-M1', 4, 'Chứng minh: nếu a // b và c cắt a tại M thì c cắt b. Lập luận ĐÚNG là:', 'A', 120, null),
  ('C3-B10-M1-Q08', 'C3-B10-M1', 4, 'Cho ba đường thẳng phân biệt a, b, c; a // c và b // c. Bạn nói "a và b có thể cắt nhau tại một điểm M". Nhận xét nào ĐÚNG?', 'A', 120, null),
  ('C3-B10-M2-Q01', 'C3-B10-M2', 1, 'Cho a // b, đường thẳng c cắt a, b. Hai góc so le trong:', 'A', 45, null),
  ('C3-B10-M2-Q02', 'C3-B10-M2', 1, 'Cho a // b, c ⊥ a. Khi đó:', 'A', 45, null),
  ('C3-B10-M2-Q03', 'C3-B10-M2', 2, 'Theo hình, a // b, góc A3 = 70°. Số đo góc B1 và B2 là:', 'A', 60, '{"loai":"hinh","moTa":"Đường thẳng c cắt hai đường thẳng a và b lần lượt tại A và B. Tại A có bốn góc A1, A2, A3, A4; tại B có bốn góc B1, B2, B3, B4, đánh số theo cùng chiều kim đồng hồ bắt đầu từ góc phía trên bên phải; A3 và B1 nằm trong dải giữa a và b, khác phía đối với c."}'::jsonb),
  ('C3-B10-M2-Q04', 'C3-B10-M2', 2, 'Cho a // b, c cắt a, b. Hai góc trong cùng phía có tổng bằng:', 'A', 60, null),
  ('C3-B10-M2-Q05', 'C3-B10-M2', 3, 'Cho a // b // c (a // c và b // c). Đường thẳng d ⊥ a. Khẳng định nào ĐÚNG?', 'A', 90, null),
  ('C3-B10-M2-Q06', 'C3-B10-M2', 3, 'Cho Ax // By, hai tia Ax và By nằm ở hai phía của đường thẳng AB, góc xAB = 50°. Góc ABy bằng:', 'A', 90, '{"loai":"hinh","moTa":"Hai tia Ax và By song song, nằm ở hai phía của đường thẳng AB; góc xAB = 50°."}'::jsonb),
  ('C3-B10-M2-Q07', 'C3-B10-M2', 4, 'Cho Ax // By (cùng phía đối với AB), góc xAB = 120°. Góc ABy bằng:', 'A', 120, '{"loai":"hinh","moTa":"Hai tia Ax và By song song, cùng phía đối với đường thẳng AB; góc xAB = 120°."}'::jsonb),
  ('C3-B10-M2-Q08', 'C3-B10-M2', 4, 'Cho Ax // By, hai tia cùng hướng; điểm C nằm giữa hai đường thẳng chứa chúng; góc xAC = 40°, góc yBC = 30°. Góc ACB bằng:', 'A', 120, '{"loai":"hinh","moTa":"Hai tia Ax, By song song cùng hướng; C nằm giữa hai đường thẳng chứa chúng; góc xAC = 40°, góc yBC = 30°. Gợi ý: kẻ qua C đường thẳng song song với Ax."}'::jsonb),
  ('C3-B11-M1-Q01', 'C3-B11-M1', 1, 'Định lí "Hai góc đối đỉnh thì bằng nhau" có giả thiết là:', 'A', 45, null),
  ('C3-B11-M1-Q02', 'C3-B11-M1', 1, 'Trong định lí dạng "Nếu … thì …", kết luận là phần:', 'A', 45, null),
  ('C3-B11-M1-Q03', 'C3-B11-M1', 2, 'Định lí: "Nếu một đường thẳng vuông góc với một trong hai đường thẳng song song thì nó vuông góc với đường thẳng còn lại". Giả thiết và kết luận viết bằng kí hiệu là:', 'A', 60, null),
  ('C3-B11-M1-Q04', 'C3-B11-M1B', 2, 'Bạn Minh đo trên hình thấy hai góc đối đỉnh đều 40° và nói "em đã chứng minh xong định lí hai góc đối đỉnh bằng nhau". Nhận xét nào ĐÚNG?', 'A', 60, null),
  ('C3-B11-M1-Q05', 'C3-B11-M1', 3, 'Từ định lí "Hai góc đối đỉnh thì bằng nhau", bạn Hoa suy ra "Hai góc bằng nhau thì đối đỉnh". Nhận xét nào ĐÚNG?', 'A', 90, null),
  ('C3-B11-M1-Q06', 'C3-B11-M1B', 3, 'Chứng minh hai góc đối đỉnh O1 và O3 bằng nhau. Bước lập luận ĐÚNG là:', 'A', 90, '{"loai":"hinh","moTa":"Hai đường thẳng cắt nhau tại O tạo bốn góc O1, O2, O3, O4 theo thứ tự quanh O."}'::jsonb),
  ('C3-B11-M1-Q07', 'C3-B11-M1', 4, 'Định lí: "Góc tạo bởi hai tia phân giác của hai góc kề bù là góc vuông". Giả thiết ĐÚNG là:', 'A', 120, null),
  ('C3-B11-M1-Q08', 'C3-B11-M1B', 4, 'Khẳng định "Nếu a // b và b // c thì a // c" (a, b, c phân biệt). Cách khẳng định đúng đắn nhất là:', 'A', 120, null),
  ('C3-B8-M1-Q09', 'C3-B8-M1', 1, 'Hai góc kề bù có tổng số đo bằng:', 'A', 45, null),
  ('C3-B8-M1-Q10', 'C3-B8-M1', 3, 'Góc xOy và góc yOz kề bù, góc xOy lớn hơn góc yOz là 40°. Số đo góc xOy là:', 'A', 90, null),
  ('C3-B8-M1-Q11', 'C3-B8-M1', 4, 'Hai góc xOy và yOx'' kề bù. Om, On lần lượt là tia phân giác của góc xOy và góc yOx''. Số đo góc mOn là:', 'A', 120, '{"loai":"hinh","moTa":"Ox và Ox'' là hai tia đối nhau; tia Oy nằm trên nửa mặt phẳng bờ xx''; Om là phân giác góc xOy, On là phân giác góc yOx''."}'::jsonb),
  ('C3-B8-M1-Q12', 'C3-B8-M1', 4, 'Một thanh chắn barie quay quanh điểm O nằm trên mép đường thẳng, tạo với mép đường một góc 35°. Góc tạo bởi thanh chắn với phần mép đường phía bên kia điểm O là:', 'A', 120, null),
  ('C3-B8-M1B-Q01', 'C3-B8-M1B', 1, 'Hai góc đối đỉnh thì:', 'A', 45, null),
  ('C3-B8-M1B-Q02', 'C3-B8-M1B', 2, 'Hai đường thẳng xx'' và yy'' cắt nhau tại O, góc xOy = 70°. Số đo góc x''Oy'' là:', 'A', 60, '{"loai":"hinh","moTa":"Hai đường thẳng xx'' và yy'' cắt nhau tại O; góc xOy = 70°."}'::jsonb),
  ('C3-B8-M1B-Q03', 'C3-B8-M1B', 2, 'Khẳng định nào ĐÚNG?', 'A', 60, null),
  ('C3-B8-M1B-Q04', 'C3-B8-M1B', 3, 'Hai đường thẳng cắt nhau tại O tạo thành bốn góc, tổng của ba trong bốn góc đó là 290°. Số đo bốn góc là:', 'A', 90, null),
  ('C3-B9-M2-Q09', 'C3-B9-M2', 4, 'Đường thẳng c cắt hai đường thẳng a và b. Một cặp góc so le trong có số đo là 2x + 10° và 3x − 20°. Để a // b thì x bằng:', 'A', 120, null),
  ('C3-B9-M2-Q10', 'C3-B9-M2', 4, 'Cho góc xOy = 70°. Trên tia Ox lấy điểm A, vẽ tia At nằm cùng phía với tia Oy đối với đường thẳng Ox sao cho góc OAt = 110°. Vì sao At // Oy?', 'A', 120, '{"loai":"hinh","moTa":"Góc xOy = 70°; A thuộc tia Ox; tia At cùng phía với Oy đối với Ox, góc OAt = 110°."}'::jsonb),
  ('C3-B9-M2B-Q01', 'C3-B9-M2B', 1, 'Cách vẽ nào sau đây cho ta hai đường thẳng song song?', 'A', 45, null),
  ('C3-B9-M2B-Q02', 'C3-B9-M2B', 1, 'Khi trượt ê ke dọc theo thước để vẽ đường thẳng b song song với a (dùng góc 60° của ê ke), hai góc cùng bằng 60° tạo ra là một cặp góc:', 'A', 45, null),
  ('C3-B9-M2B-Q03', 'C3-B9-M2B', 2, 'Cho đường thẳng a và điểm A không thuộc a. Bạn Mai vẽ: (1) đường thẳng c đi qua A và vuông góc với a; (2) đường thẳng b đi qua A và vuông góc với c. Vì sao b // a?', 'A', 60, null),
  ('C3-B9-M2B-Q04', 'C3-B9-M2B', 2, 'Bạn Nam vẽ đường thẳng c cắt a tại M. Tại điểm N trên c (N không thuộc a), Nam vẽ đường thẳng b sao cho góc tạo bởi b và c bằng góc tạo bởi a và c ở vị trí đồng vị. Khi đó:', 'A', 60, null),
  ('C3-B9-M2B-Q05', 'C3-B9-M2B', 3, 'Cho tam giác ABC. Vẽ qua A đường thẳng d sao cho d tạo với AB một góc bằng góc ABC, và phần đường thẳng d tạo góc đó nằm khác phía với điểm C đối với đường thẳng AB. Khi đó:', 'A', 90, '{"loai":"hinh","moTa":"Tam giác ABC; đường thẳng d đi qua A, góc giữa d và AB bằng góc ABC, ở phía không chứa C."}'::jsonb),
  ('C3-B9-M2B-Q06', 'C3-B9-M2B', 3, 'Vẽ đường thẳng qua A song song với a bằng thước đo góc: đã vẽ đường thẳng c đi qua A, cắt a tại B và góc ABx = 40° (Bx là một tia của a). Bước tiếp theo là vẽ tia Ay sao cho:', 'A', 90, '{"loai":"hinh","moTa":"Đường thẳng a; điểm A ngoài a; đường thẳng c qua A cắt a tại B; góc ABx = 40°."}'::jsonb),
  ('C3-B11-M1-Q09', 'C3-B11-M1', 2, 'Định lí: "Hai đường thẳng phân biệt cùng song song với một đường thẳng thứ ba thì song song với nhau". Kết luận của định lí là:', 'A', 60, null),
  ('C3-B11-M1-Q10', 'C3-B11-M1', 3, 'Phát biểu định lí "Hai góc cùng kề bù với một góc thì bằng nhau" dưới dạng "Nếu … thì …":', 'A', 90, null),
  ('C3-B11-M1-Q11', 'C3-B11-M1', 4, 'Định lí: "Nếu một đường thẳng cắt hai đường thẳng song song thì hai góc so le trong bằng nhau". Với hình vẽ, GT – KL viết bằng kí hiệu là:', 'A', 120, '{"loai":"hinh","moTa":"Đường thẳng c cắt hai đường thẳng a và b lần lượt tại A và B. Tại A có bốn góc A1, A2, A3, A4; tại B có bốn góc B1, B2, B3, B4, đánh số theo cùng chiều kim đồng hồ bắt đầu từ góc phía trên bên phải; A3 và B1 nằm trong dải giữa a và b, khác phía đối với c."}'::jsonb),
  ('C3-B11-M1B-Q01', 'C3-B11-M1B', 1, 'Chứng minh một định lí là:', 'A', 45, null),
  ('C3-B11-M1B-Q02', 'C3-B11-M1B', 1, 'Khi chứng minh định lí, mỗi bước lập luận phải có:', 'A', 45, null),
  ('C3-B11-M1B-Q03', 'C3-B11-M1B', 2, 'Chứng minh: "Nếu a ⊥ c và b ⊥ c (a, b phân biệt) thì a // b". Lập luận nào ĐÚNG?', 'A', 60, null),
  ('C3-B11-M1B-Q04', 'C3-B11-M1B', 3, 'Bạn Hùng chứng minh "Hai góc đối đỉnh thì bằng nhau" như sau: "Góc O1 và góc O3 đối đỉnh nên O1 = O3". Lỗi của bạn Hùng là:', 'A', 90, null),
  ('C3-B11-M1B-Q05', 'C3-B11-M1B', 4, 'Chứng minh: "Góc tạo bởi hai tia phân giác của hai góc kề bù là góc vuông" (Om, On là phân giác của góc xOy và góc yOx''). Lập luận ĐÚNG là:', 'A', 120, '{"loai":"hinh","moTa":"Ox, Ox'' là hai tia đối nhau; Oy nằm trên một nửa mặt phẳng bờ xx''; Om, On là phân giác của góc xOy và góc yOx''."}'::jsonb),
  ('C3-LTC-Q01', 'C3-LTC', 1, 'Góc xOy = 140°. Góc kề bù với nó và tia phân giác của góc kề bù đó tạo với tia chung một góc bằng:', 'A', 45, null),
  ('C3-LTC-Q02', 'C3-LTC', 1, 'Cho a ⊥ c, b ⊥ c (a, b phân biệt) và d cắt a. Khẳng định nào ĐÚNG?', 'A', 45, null),
  ('C3-LTC-Q03', 'C3-LTC', 2, 'Hai đường thẳng xx'', yy'' cắt nhau tại O, góc xOy = 4 · góc x''Oy. Số đo góc xOy'' là:', 'A', 60, null),
  ('C3-LTC-Q04', 'C3-LTC', 2, 'Hình thang ABCD (AB // CD), góc A = 70°. Góc D (cùng kề cạnh AD) bằng:', 'A', 60, '{"loai":"hinh","moTa":"Hình thang ABCD có AB // CD; góc DAB = 70°; góc ADC là góc trong cùng phía với góc DAB."}'::jsonb),
  ('C3-LTC-Q05', 'C3-LTC', 3, 'Cho a // b, c cắt a tại A, cắt b tại B. Tia phân giác của góc so le trong A3 và tia phân giác của góc B1 (A3 = B1) có quan hệ:', 'A', 90, '{"loai":"hinh","moTa":"Đường thẳng c cắt hai đường thẳng a và b lần lượt tại A và B. Tại A có bốn góc A1, A2, A3, A4; tại B có bốn góc B1, B2, B3, B4, đánh số theo cùng chiều kim đồng hồ bắt đầu từ góc phía trên bên phải; A3 và B1 nằm trong dải giữa a và b, khác phía đối với c."}'::jsonb),
  ('C3-LTC-Q06', 'C3-LTC', 3, 'Định lí "Nếu hai đường thẳng phân biệt cùng vuông góc với đường thẳng thứ ba thì chúng song song". Kết luận là:', 'A', 90, null),
  ('C3-LTC-Q07', 'C3-LTC', 4, 'Cho tam giác ABC. Qua A kẻ đường thẳng xy // BC. Dùng tính chất song song, ta chứng minh được:', 'A', 120, '{"loai":"hinh","moTa":"Tam giác ABC; qua A kẻ đường thẳng xy song song với BC, tia Ax cùng phía với B."}'::jsonb),
  ('C3-LTC-Q08', 'C3-LTC', 4, 'Cho Ax // By, Ax và By ở hai phía AB; góc xAB = 2 · góc ABy − 50°. Số đo góc xAB là:', 'A', 120, null)
on conflict (question_id) do update set ku_id = excluded.ku_id, level = excluded.level, stem = excluded.stem,
