insert into error_hints (error_code, tier, hint_text) values
  ('E-KB-01', 1, 'Hai góc này có chung một cạnh không? Hai cạnh còn lại có tạo thành một đường thẳng không?'),
  ('E-KB-01', 2, 'Hai góc kề bù: có một cạnh chung và hai cạnh còn lại là hai tia đối nhau. Hai góc có tổng 180° nhưng không kề nhau thì chỉ là hai góc bù nhau.'),
  ('E-KB-01', 3, 'Ví dụ: góc xOy và góc yOx'' (Ox, Ox'' đối nhau) là kề bù. Em vẽ lại và kiểm tra cạnh chung.'),
  ('E-KB-02', 1, 'Hai góc kề bù có tổng bao nhiêu độ: 90° hay 180°?'),
  ('E-KB-02', 2, 'Hai góc kề bù có tổng 180°. Tổng 90° là hai góc phụ nhau.'),
  ('E-KB-02', 3, 'Ví dụ: góc xOy = 60° thì góc kề bù = 180° − 60° = 120°. Em dùng 180°.'),
  ('E-DDI-01', 1, 'Mỗi cạnh của góc này có phải là tia đối của một cạnh của góc kia không?'),
  ('E-DDI-01', 2, 'Hai góc đối đỉnh: mỗi cạnh của góc này là tia đối của một cạnh của góc kia. Hai góc kề bù (chung một cạnh) không phải đối đỉnh.'),
  ('E-DDI-01', 3, 'Ví dụ: xx'' cắt yy'' tại O: góc xOy đối đỉnh với góc x''Oy''. Em tìm góc "đối diện qua O".'),
  ('E-PG-01', 1, 'Hai góc do tia này tạo với hai cạnh có bằng nhau không?'),
  ('E-PG-01', 2, 'Tia phân giác phải nằm giữa hai cạnh VÀ tạo với hai cạnh hai góc bằng nhau.'),
  ('E-PG-01', 3, 'Ví dụ: góc xOz = 30°, góc xOy = 70° thì góc zOy = 40° ≠ 30°, nên Oz không phải phân giác.'),
  ('E-PG-02', 1, 'Tia phân giác chia góc thành mấy phần bằng nhau?'),
  ('E-PG-02', 2, 'Mỗi góc tạo bởi tia phân giác bằng một nửa góc ban đầu; ngược lại, góc ban đầu gấp đôi.'),
  ('E-PG-02', 3, 'Ví dụ: góc xOy = 80° thì góc xOz = 40°; nếu góc mOt = 35° thì góc mOn = 70°.'),
  ('E-SLT-01', 1, 'Hai góc nằm trong hay ngoài dải giữa a và b? Cùng phía hay khác phía cát tuyến?'),
  ('E-SLT-01', 2, 'So le trong: cả hai ở trong dải, khác phía cát tuyến. Đồng vị: cùng vị trí tại hai giao điểm. Trong cùng phía: cả hai ở trong dải, cùng phía cát tuyến.'),
  ('E-SLT-01', 3, 'Em tô dải giữa a và b, rồi xác định từng góc nằm bên trái hay phải cát tuyến.'),
  ('E-SLT-02', 1, 'Hai đường thẳng a và b có song song không?'),
  ('E-SLT-02', 2, 'Cặp góc so le trong (đồng vị) chỉ bằng nhau khi hai đường thẳng song song (hoặc khi đề cho một cặp bằng nhau).'),
  ('E-SLT-02', 3, 'Ví dụ: a và b cắt nhau thì các góc so le trong không bằng nhau. Em kiểm tra giả thiết trước khi dùng.'),
  ('E-DHSS-01', 1, 'Hai góc em dùng nằm ở cùng một giao điểm hay ở hai giao điểm khác nhau?'),
  ('E-DHSS-01', 2, 'Dấu hiệu song song cần cặp góc so le trong hoặc đồng vị (ở hai giao điểm) bằng nhau. Góc đối đỉnh, kề bù ở cùng một giao điểm không nói gì về song song.'),
  ('E-DHSS-01', 3, 'Em tìm một góc ở A và một góc ở B tạo thành cặp so le trong hoặc đồng vị.'),
  ('E-DHSS-02', 1, 'Hai đường thẳng cùng vuông góc với c thì chúng cắt nhau hay song song?'),
  ('E-DHSS-02', 2, 'Hai đường thẳng phân biệt cùng vuông góc với đường thẳng thứ ba thì song song với nhau.'),
  ('E-DHSS-02', 3, 'Ví dụ: các thanh dọc của thang cùng vuông góc với thanh ngang nên song song.'),
  ('E-EUC-01', 1, 'Qua một điểm ngoài đường thẳng, em vẽ được mấy đường song song?'),
  ('E-EUC-01', 2, 'Tiên đề Euclid: qua một điểm ở ngoài một đường thẳng chỉ có một đường thẳng song song với đường thẳng đó.'),
  ('E-EUC-01', 3, 'Nếu "vẽ được hai đường" thì hai đường đó phải trùng nhau. Đường cắt một trong hai đường song song thì cắt đường kia.'),
  ('E-TCSS-01', 1, 'Hai góc trong cùng phía bằng nhau hay có tổng 180°?'),
  ('E-TCSS-01', 2, 'Khi a // b: so le trong bằng nhau, đồng vị bằng nhau, còn hai góc trong cùng phía bù nhau (tổng 180°).'),
  ('E-TCSS-01', 3, 'Ví dụ: hình thang AB // CD, góc A = 70° thì góc D = 110°.'),
  ('E-TCSS-02', 1, 'Nếu c vuông góc với a và a // b thì c tạo với b góc bao nhiêu?'),
  ('E-TCSS-02', 2, 'c ⊥ a và a // b thì c ⊥ b (vì cặp góc đồng vị bằng nhau, cùng 90°). Hai đường cùng song song với đường thứ ba thì song song với nhau.'),
  ('E-TCSS-02', 3, 'Muốn tính góc có "điểm gãy" giữa hai đường song song, kẻ thêm một đường song song đi qua điểm đó.'),
  ('E-DL-01', 1, 'Phần nào là điều đã biết, phần nào là điều phải suy ra?'),
  ('E-DL-01', 2, 'Định lí "Nếu … thì …": giả thiết nằm sau "Nếu", kết luận nằm sau "thì".'),
  ('E-DL-01', 3, 'Ví dụ: "Hai góc đối đỉnh thì bằng nhau": GT là hai góc đối đỉnh, KL là hai góc bằng nhau.'),
  ('E-DL-02', 1, 'Đo trên một hình có đảm bảo đúng với mọi hình không?'),
  ('E-DL-02', 2, 'Chứng minh định lí là lập luận từ giả thiết và các điều đã biết để suy ra kết luận, đúng cho mọi trường hợp. Đo, thử ví dụ chỉ là kiểm tra. Mệnh đề đảo chưa chắc đúng.'),
  ('E-DL-02', 3, 'Ví dụ: "Bằng nhau thì đối đỉnh" là sai vì có hai góc 30° ở hai chỗ khác nhau.')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-KB-01', 'Có bạn thấy hai góc cộng lại 180° là gọi ngay "kề bù". Nhưng kề bù còn cần hai góc nằm cạnh nhau theo một cách đặc biệt.', 'Hai góc kề bù: có một cạnh chung và hai cạnh còn lại là hai tia đối nhau. Hai góc kề bù có tổng 180°. Hai góc có tổng 180° nhưng không kề nhau chỉ gọi là bù nhau.', '[{"de":"Góc A = 70° và góc B = 110° nằm ở hai hình khác nhau. Chúng có kề bù không?","giai":"Cách nghĩ sai: tổng 180° nên kề bù. Cách đúng: không có cạnh chung nên chỉ là hai góc bù nhau, không kề bù."},{"de":"Ox và Ox'' là hai tia đối nhau, Oy là tia khác. Góc xOy và góc yOx'' là gì?","giai":"Có cạnh chung Oy, hai cạnh còn lại đối nhau nên kề bù."}]'::jsonb, '[{"de":"Hai góc kề nhau có tổng 150° có kề bù không?","dapAn":"Không","giaiThich":"Kề bù phải có tổng 180°."},{"de":"Hai góc kề bù có chung mấy cạnh?","dapAn":"Một cạnh","giaiThich":"Hai cạnh còn lại đối nhau."}]'::jsonb),
  ('VBH-KB-02', 'Nhiều bạn nhầm "kề bù" với "phụ nhau" nên lấy 90° trừ đi.', 'Hai góc kề bù có tổng 180°: góc kề bù = 180° − góc đã biết. Hai góc phụ nhau có tổng 90°.', '[{"de":"Góc xOy = 60°. Tính góc kề bù với nó.","giai":"Cách nghĩ sai: 90° − 60° = 30°. Cách đúng: 180° − 60° = 120°."},{"de":"Hai góc kề bù, góc này gấp 3 góc kia. Tính góc nhỏ.","giai":"4 phần = 180° nên góc nhỏ = 45°."}]'::jsonb, '[{"de":"Góc kề bù với góc 35°?","dapAn":"145°","giaiThich":"180° − 35°."},{"de":"Góc phụ với góc 35°?","dapAn":"55°","giaiThich":"90° − 35°."}]'::jsonb),
  ('VBH-DDI-01', 'Khi hai đường thẳng cắt nhau có bốn góc. Nhiều bạn nhầm cặp kề bù thành cặp đối đỉnh.', 'Hai góc đối đỉnh: mỗi cạnh của góc này là tia đối của một cạnh của góc kia. Hai góc đối đỉnh thì bằng nhau. Góc đối đỉnh nằm "đối diện qua O", không có cạnh chung.', '[{"de":"xx'' cắt yy'' tại O. Góc nào đối đỉnh với góc xOy?","giai":"Cách nghĩ sai: góc yOx'' (có chung cạnh Oy, đó là kề bù). Cách đúng: góc x''Oy''."},{"de":"Góc xOy = 50°. Góc x''Oy'' và góc x''Oy bằng bao nhiêu?","giai":"x''Oy'' = 50° (đối đỉnh); x''Oy = 130° (kề bù)."}]'::jsonb, '[{"de":"Hai góc đối đỉnh có cạnh chung không?","dapAn":"Không","giaiThich":"Các cạnh là tia đối của nhau."},{"de":"Hai góc bằng nhau chung đỉnh có chắc là đối đỉnh không?","dapAn":"Không chắc","giaiThich":"Còn phải có các cạnh là tia đối nhau."}]'::jsonb),
  ('VBH-PG-01', 'Tia nằm giữa hai cạnh chưa chắc là tia phân giác. Điều quan trọng là nó chia góc thành hai phần bằng nhau.', 'Tia Oz là tia phân giác của góc xOy khi Oz nằm giữa Ox, Oy và góc xOz = góc zOy.', '[{"de":"Oz nằm giữa Ox, Oy; góc xOz = 30°, góc xOy = 70°. Oz có phải phân giác?","giai":"Cách nghĩ sai: có, vì nằm giữa. Cách đúng: góc zOy = 40° ≠ 30° nên không phải."},{"de":"Góc xOy = 90°, Oz nằm giữa và góc xOz = 45°. Oz có phải phân giác?","giai":"Có, vì góc zOy = 45° = góc xOz."}]'::jsonb, '[{"de":"Hai điều kiện của tia phân giác?","dapAn":"Nằm giữa hai cạnh và tạo hai góc bằng nhau","giaiThich":"Phải đủ cả hai."},{"de":"Mỗi góc có mấy tia phân giác?","dapAn":"Một (với góc khác góc bẹt)","giaiThich":"Chỉ một tia chia đôi."}]'::jsonb),
  ('VBH-PG-02', 'Khi tính góc có tia phân giác, chỉ cần nhớ "một nửa" và "gấp đôi" là đủ.', 'Nếu Oz là phân giác của góc xOy thì góc xOz = góc zOy = góc xOy : 2, và góc xOy = 2 · góc xOz.', '[{"de":"Góc xOy = 80°, Oz là phân giác. Tính góc xOz.","giai":"Cách nghĩ sai: 160°. Cách đúng: 80° : 2 = 40°."},{"de":"Ot là phân giác góc mOn, góc mOt = 35°. Tính góc mOn.","giai":"2 · 35° = 70°."}]'::jsonb, '[{"de":"Góc 130° có phân giác. Mỗi góc nhỏ?","dapAn":"65°","giaiThich":"130° : 2."},{"de":"Hai tia phân giác của hai góc kề bù tạo góc bao nhiêu?","dapAn":"90°","giaiThich":"180° : 2."}]'::jsonb),
  ('VBH-SLT-01', 'Khi một đường thẳng cắt hai đường thẳng, có tám góc và nhiều tên gọi. Một mẹo hình chữ giúp em nhớ nhanh.', 'So le trong: hai góc trong dải giữa hai đường thẳng, khác phía cát tuyến (hình chữ Z). Đồng vị: cùng vị trí ở hai giao điểm (hình chữ F). Trong cùng phía: hai góc trong dải, cùng phía cát tuyến (hình chữ C).', '[{"de":"Theo hình, A3 và B4 (cùng nằm trong dải, cùng bên trái c) là cặp gì?","giai":"Cách nghĩ sai: so le trong. Cách đúng: cùng phía cát tuyến nên là trong cùng phía; so le trong của A3 là B1."},{"de":"A1 và B1 là cặp gì?","giai":"Cùng vị trí (góc trên bên phải) ở hai giao điểm: đồng vị."}]'::jsonb, '[{"de":"Có mấy cặp góc so le trong?","dapAn":"2 cặp","giaiThich":"A3–B1 và A2–B4."},{"de":"Có mấy cặp góc đồng vị?","dapAn":"4 cặp","giaiThich":"A1–B1, A2–B2, A3–B3, A4–B4."}]'::jsonb),
  ('VBH-SLT-02', 'Gọi tên cặp so le trong thì luôn được, nhưng hai góc đó chỉ bằng nhau trong trường hợp đặc biệt.', 'Cặp góc so le trong (đồng vị) bằng nhau khi và chỉ khi hai đường thẳng song song. Nếu hai đường cắt nhau thì các cặp đó không bằng nhau. Nếu có một cặp so le trong bằng nhau thì mọi cặp so le trong, đồng vị đều bằng nhau.', '[{"de":"a và b cắt nhau ở xa. Hai góc so le trong có bằng nhau không?","giai":"Cách nghĩ sai: luôn bằng nhau. Cách đúng: không bằng nhau, vì a, b không song song."},{"de":"Biết A3 = B1 = 60°. Tính A2, B2.","giai":"A2 = 180° − 60° = 120°, B2 = 180° − 60° = 120°; cặp đồng vị A2 = B2."}]'::jsonb, '[{"de":"Muốn dùng \"so le trong bằng nhau\" cần biết điều gì trước?","dapAn":"Hai đường thẳng song song (hoặc đề cho một cặp bằng nhau)","giaiThich":"Đó là tính chất của hai đường song song."},{"de":"Có A1 = B1. Có suy ra A3 = B3 không?","dapAn":"Có","giaiThich":"Một cặp đồng vị bằng nhau thì các cặp còn lại bằng nhau."}]'::jsonb),
  ('VBH-DHSS-01', 'Dấu hiệu song song cần một cặp góc ở hai giao điểm khác nhau. Góc đối đỉnh hay kề bù cùng một giao điểm thì không dùng được.', 'Nếu đường thẳng c cắt a, b và có một cặp góc so le trong bằng nhau (hoặc một cặp góc đồng vị bằng nhau) thì a // b.', '[{"de":"Bạn viết: \"A1 và A3 đối đỉnh nên bằng nhau, do đó a // b\". Đúng không?","giai":"Cách nghĩ sai: đúng. Cách đúng: A1, A3 cùng ở giao điểm A, luôn bằng nhau dù a, b thế nào; phải so một góc ở A với một góc ở B."},{"de":"A1 = 70°, B1 = 70°. Kết luận?","giai":"Cặp đồng vị bằng nhau nên a // b."}]'::jsonb, '[{"de":"A3 = 65°, B2 = 115°. a và b có song song không?","dapAn":"Có","giaiThich":"B1 = 65° = A3 (so le trong)."},{"de":"Cách vẽ song song bằng ê ke trượt trên thước dựa vào dấu hiệu nào?","dapAn":"Hai góc đồng vị bằng nhau","giaiThich":"Cùng bằng góc của ê ke."}]'::jsonb),
  ('VBH-DHSS-02', 'Hai đường thẳng cùng vuông góc với một đường thì chúng không cắt nhau mà song song. Hãy nghĩ đến các thanh dọc của cái thang.', 'Hai đường thẳng phân biệt cùng vuông góc với đường thẳng thứ ba thì song song với nhau.', '[{"de":"a ⊥ c, b ⊥ c. Quan hệ của a và b?","giai":"Cách nghĩ sai: a ⊥ b. Cách đúng: cặp đồng vị cùng 90° nên a // b."},{"de":"Hình thang có góc A = góc D = 90°. Vì sao AB // CD?","giai":"AB và CD cùng vuông góc với AD."}]'::jsonb, '[{"de":"Hai cạnh đối của hình chữ nhật cùng vuông góc với cạnh thứ ba. Chúng có quan hệ gì?","dapAn":"Song song","giaiThich":"Cùng vuông góc với một đường."},{"de":"a ⊥ c, b ⊥ c và a, b trùng nhau được không?","dapAn":"Có thể trùng; nếu phân biệt thì song song","giaiThich":"Định lí nói \"hai đường phân biệt\"."}]'::jsonb),
  ('VBH-EUC-01', 'Trên giấy, vẽ hai đường "song song" qua cùng một điểm dễ tưởng là được, nhưng thực ra chúng trùng nhau.', 'Tiên đề Euclid: qua một điểm ở ngoài một đường thẳng, chỉ có một đường thẳng song song với đường thẳng đó. Hệ quả: đường thẳng cắt một trong hai đường song song thì cắt đường còn lại; hai đường cùng song song với đường thứ ba thì song song với nhau.', '[{"de":"Qua M ngoài a, Lan vẽ được b // a và c // a. Kết luận?","giai":"Cách nghĩ sai: vẽ được hai đường là bình thường. Cách đúng: theo tiên đề Euclid, b và c trùng nhau."},{"de":"a // b, c cắt a. c có cắt b không?","giai":"Có. Nếu không, c // b và qua giao điểm có hai đường a, c cùng song song với b, vô lí."}]'::jsonb, '[{"de":"Qua điểm M ngoài a có mấy đường song song với a?","dapAn":"Một","giaiThich":"Tiên đề Euclid."},{"de":"a // c, b // c (a, b phân biệt). Quan hệ của a và b?","dapAn":"a // b","giaiThich":"Hệ quả của tiên đề Euclid."}]'::jsonb),
  ('VBH-TCSS-01', 'Khi hai đường thẳng song song, so le trong và đồng vị bằng nhau, nhưng trong cùng phía thì khác.', 'Nếu a // b thì: hai góc so le trong bằng nhau; hai góc đồng vị bằng nhau; hai góc trong cùng phía bù nhau (tổng 180°).', '[{"de":"Hình thang AB // CD, góc A = 70°. Tính góc D.","giai":"Cách nghĩ sai: góc D = 70°. Cách đúng: góc A và góc D trong cùng phía nên góc D = 180° − 70° = 110°."},{"de":"Ax // By cùng phía AB, góc xAB = 120°. Tính góc ABy.","giai":"Trong cùng phía: 180° − 120° = 60°."}]'::jsonb, '[{"de":"a // b, A3 = 70°. Tính B1 và B4.","dapAn":"B1 = 70°, B4 = 110°","giaiThich":"So le trong bằng nhau; trong cùng phía bù nhau."},{"de":"Tổng hai góc trong cùng phía khi a // b?","dapAn":"180°","giaiThich":"Bù nhau."}]'::jsonb),
  ('VBH-TCSS-02', 'Quan hệ vuông góc và song song có thể "bắc cầu". Nắm điều này giúp giải nhanh nhiều bài.', 'Nếu c ⊥ a và a // b thì c ⊥ b. Nếu a // c và b // c thì a // b. Với góc có đỉnh nằm giữa hai đường song song, kẻ thêm qua đỉnh một đường song song rồi dùng so le trong.', '[{"de":"a // b, c ⊥ a. Quan hệ của c và b?","giai":"Cách nghĩ sai: chưa biết. Cách đúng: c ⊥ b, vì cặp góc đồng vị bằng nhau, cùng 90°."},{"de":"Ax // By cùng hướng, C ở giữa, góc xAC = 40°, góc yBC = 30°. Tính góc ACB.","giai":"Kẻ Cz // Ax (cũng // By): góc ACz = 40°, góc zCB = 30°, nên góc ACB = 70°."}]'::jsonb, '[{"de":"d ⊥ a, a // b // c. d có vuông góc với c không?","dapAn":"Có","giaiThich":"Bắc cầu qua các đường song song."},{"de":"Muốn tính góc có đỉnh giữa hai đường song song, em kẻ thêm gì?","dapAn":"Một đường song song đi qua đỉnh góc","giaiThich":"Để tách góc thành hai góc so le trong."}]'::jsonb),
  ('VBH-DL-01', 'Mỗi định lí có hai phần: điều cho biết và điều phải suy ra. Nhầm hai phần sẽ làm chứng minh đi ngược.', 'Định lí dạng "Nếu … thì …": phần sau "Nếu" là giả thiết (GT), phần sau "thì" là kết luận (KL). Câu không có "Nếu … thì" có thể viết lại thành dạng đó.', '[{"de":"\"Hai góc đối đỉnh thì bằng nhau.\" Viết GT, KL.","giai":"Cách nghĩ sai: GT là hai góc bằng nhau. Cách đúng: viết lại \"Nếu hai góc đối đỉnh thì chúng bằng nhau\": GT hai góc đối đỉnh; KL hai góc bằng nhau."},{"de":"\"Đường thẳng vuông góc với một trong hai đường song song thì vuông góc với đường kia.\" Viết bằng kí hiệu.","giai":"GT: a // b, c ⊥ a. KL: c ⊥ b."}]'::jsonb, '[{"de":"Kết luận nằm sau từ nào?","dapAn":"\"thì\"","giaiThich":"Giả thiết nằm sau \"Nếu\"."},{"de":"\"Hai đường phân biệt cùng vuông góc với đường thứ ba thì song song.\" Kết luận?","dapAn":"Hai đường đó song song","giaiThich":"Phần sau \"thì\"."}]'::jsonb),
  ('VBH-DL-02', 'Đo trên một hình chỉ cho biết hình đó. Chứng minh phải đúng cho mọi hình.', 'Chứng minh định lí là dùng lập luận suy ra kết luận từ giả thiết và các điều đã biết (định nghĩa, tiên đề, định lí đã có). Đo đạc, thử ví dụ chỉ là kiểm tra. Mệnh đề đảo của một định lí chưa chắc đúng.', '[{"de":"Đo thấy hai góc đối đỉnh đều 40°, bạn nói đã chứng minh. Đúng không?","giai":"Cách nghĩ sai: đúng. Cách đúng: chưa; phải lập luận: O1 + O2 = 180°, O3 + O2 = 180° nên O1 = O3, đúng với mọi hình."},{"de":"\"Hai góc bằng nhau thì đối đỉnh\" có đúng không?","giai":"Sai: hai góc 30° ở hai hình khác nhau bằng nhau nhưng không đối đỉnh."}]'::jsonb, '[{"de":"Thử 3 hình đều đúng thì đã chứng minh xong chưa?","dapAn":"Chưa","giaiThich":"Phải lập luận cho mọi trường hợp."},{"de":"Đảo của \"Nếu a // b thì so le trong bằng nhau\" là gì, có đúng không?","dapAn":"\"Nếu so le trong bằng nhau thì a // b\" — đúng (dấu hiệu)","giaiThich":"Trường hợp này đảo đúng, nhưng không phải lúc nào cũng vậy."}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

-- ===========================================================================
-- CHƯƠNG IV — TAM GIÁC BẰNG NHAU
-- ===========================================================================
insert into knowledge_units (ku_id, lesson_id, ku_name, order_index, prerequisite_ku, co_video) values
  ('C4-B12-M1', 'Bài 12. Tổng các góc trong một tam giác', 'Mục 1. Tổng các góc trong một tam giác', 41, 'C3-B10-M2', true),
  ('C4-B13-M1', 'Bài 13. Hai tam giác bằng nhau. Trường hợp bằng nhau thứ nhất', 'Mục 1. Hai tam giác bằng nhau', 42, 'C4-B12-M1', true),
  ('C4-B13-M2', 'Bài 13. Hai tam giác bằng nhau. Trường hợp bằng nhau thứ nhất', 'Mục 2. Trường hợp bằng nhau cạnh – cạnh – cạnh (c.c.c)', 43, 'C4-B13-M1', true),
  ('C4-B14-M1', 'Bài 14. Trường hợp bằng nhau thứ hai và thứ ba của tam giác', 'Mục 1. Trường hợp bằng nhau cạnh – góc – cạnh (c.g.c)', 44, 'C4-B13-M2', true),
  ('C4-B14-M2', 'Bài 14. Trường hợp bằng nhau thứ hai và thứ ba của tam giác', 'Mục 2. Trường hợp bằng nhau góc – cạnh – góc (g.c.g)', 45, 'C4-B14-M1', true),
  ('C4-B15-M1', 'Bài 15. Các trường hợp bằng nhau của tam giác vuông', 'Mục 1. Hai cạnh góc vuông; cạnh góc vuông và góc nhọn kề', 46, 'C4-B14-M2', true),
