-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-TBG-01', 'C4-B12-M1', 'Cho rằng tổng ba góc phụ thuộc vào kích thước hoặc hình dạng tam giác, hoặc nhầm thành 360°. Ví dụ: Tam giác to hơn thì tổng ba góc lớn hơn; hoặc tính góc còn lại bằng 360° trừ hai góc', 'VBH-TBG-01'),
  ('E-TBG-02', 'C4-B12-M1', 'Cho rằng một tam giác có thể có hai góc vuông hoặc hai góc tù; không biết hai góc nhọn của tam giác vuông phụ nhau. Ví dụ: Vẽ tam giác có hai góc 100°; tính góc nhọn còn lại của tam giác vuông là 180° − 35°', 'VBH-TBG-02'),
  ('E-TBG-03', 'C4-B12-M1', 'Tính góc ngoài sai: cộng cả góc trong kề với nó, hoặc lấy bằng góc trong kề. Ví dụ: Tam giác có góc 50°, 60°, 70°; góc ngoài tại đỉnh góc 70° được tính là 70° hoặc 180°', 'VBH-TBG-03'),
  ('E-BN-01', 'C4-B13-M1', 'Viết kí hiệu hai tam giác bằng nhau không theo thứ tự các đỉnh tương ứng. Ví dụ: A ứng với D, B ứng với E, C ứng với F nhưng viết ΔABC = ΔDFE', 'VBH-BN-01'),
  ('E-BN-02', 'C4-B13-M1', 'Suy ra cạnh, góc tương ứng sai từ kí hiệu hai tam giác bằng nhau. Ví dụ: Từ ΔABC = ΔMNP suy ra AB = MP hoặc góc B = góc P', 'VBH-BN-02'),
  ('E-CCC-01', 'C4-B13-M2', 'Kết luận hai tam giác bằng nhau (c.c.c) khi mới có hai cặp cạnh bằng nhau. Ví dụ: AB = DE, AC = DF rồi kết luận ngay ΔABC = ΔDEF', 'VBH-CCC-01'),
  ('E-CC-01', 'C4-B13-M2', 'Không nhận ra cạnh chung, góc chung, góc đối đỉnh là yếu tố bằng nhau có sẵn. Ví dụ: Hai tam giác ABD và ACD có chung cạnh AD nhưng em cho là "thiếu một cặp cạnh"', 'VBH-CC-01'),
  ('E-CGC-01', 'C4-B14-M1', 'Dùng góc không xen giữa hai cạnh để kết luận theo trường hợp c.g.c. Ví dụ: AB = DE, AC = DF, góc B = góc E rồi kết luận ΔABC = ΔDEF (c.g.c)', 'VBH-CGC-01'),
  ('E-GCG-01', 'C4-B14-M2', 'Dùng cạnh không nằm giữa hai góc để kết luận theo trường hợp g.c.g. Ví dụ: Góc B = góc E, góc C = góc F, AB = DE rồi viết (g.c.g)', 'VBH-GCG-01'),
  ('E-GGG-01', 'C4-B14-M2', 'Cho rằng hai tam giác có ba cặp góc bằng nhau thì bằng nhau. Ví dụ: Hai tam giác đều cạnh 2 cm và 5 cm có ba góc bằng nhau nên "bằng nhau"', 'VBH-GGG-01'),
  ('E-TGV-01', 'C4-B15-M1', 'Nhầm cạnh huyền với cạnh góc vuông khi xét tam giác vuông. Ví dụ: Tam giác ABC vuông tại A nhưng gọi AB là cạnh huyền', 'VBH-TGV-01'),
  ('E-TGV-02', 'C4-B15-M1B', 'Cho rằng hai tam giác vuông có hai góc nhọn tương ứng bằng nhau thì bằng nhau. Ví dụ: Hai tam giác vuông cùng có góc 30° và 60° nên kết luận bằng nhau', 'VBH-TGV-02'),
  ('E-TGV-03', 'C4-B15-M2', 'Áp dụng "cạnh huyền – cạnh góc vuông" cho tam giác không vuông (hai cạnh và một góc không xen giữa). Ví dụ: Hai tam giác thường có AB = DE, BC = EF, góc A = góc D rồi viết (cạnh huyền – cạnh góc vuông)', 'VBH-TGV-03'),
  ('E-TGC-01', 'C4-B16-M1', 'Nhầm góc ở đỉnh với góc ở đáy, cạnh bên với cạnh đáy của tam giác cân. Ví dụ: Tam giác ABC cân tại A nhưng cho rằng góc A = góc B', 'VBH-TGC-01'),
  ('E-TGC-02', 'C4-B16-M1', 'Tính góc trong tam giác cân sai: quên chia đôi hoặc quên nhân đôi góc ở đáy. Ví dụ: Góc ở đỉnh 40° nên mỗi góc ở đáy là 180° − 40° = 140°', 'VBH-TGC-02'),
  ('E-TGC-03', 'C4-B16-M1B', 'Không nhận ra tam giác cân có một góc 60° là tam giác đều; cho rằng tam giác đều không phải tam giác cân. Ví dụ: Tam giác cân có góc ở đỉnh 60° nhưng em nói "chưa chắc là tam giác đều"', 'VBH-TGC-03'),
  ('E-TTR-01', 'C4-B16-M2', 'Cho rằng đường vuông góc với đoạn thẳng (không qua trung điểm) hoặc đường đi qua trung điểm (không vuông góc) là đường trung trực. Ví dụ: Đường thẳng đi qua trung điểm M của AB nhưng không vuông góc với AB vẫn được gọi là trung trực', 'VBH-TTR-01'),
  ('E-TTR-02', 'C4-B16-M2B', 'Không vận dụng được tính chất: điểm cách đều hai mút thì nằm trên trung trực và ngược lại. Ví dụ: Cho MA = MB nhưng em không suy ra được M nằm trên đường trung trực của AB', 'VBH-TTR-02')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

insert into questions (question_id, ku_id, level, stem, correct_option, expected_time_sec, hinh) values
  ('C4-B12-M1-Q01', 'C4-B12-M1', 1, 'Tam giác ABC có góc A = 60°, góc B = 70°. Số đo góc C là:', 'A', 45, null),
  ('C4-B12-M1-Q02', 'C4-B12-M1', 1, 'Tam giác MNP vuông tại M, góc N = 35°. Số đo góc P là:', 'A', 45, null),
  ('C4-B12-M1-Q03', 'C4-B12-M1', 2, 'Khẳng định nào ĐÚNG?', 'A', 60, null),
  ('C4-B12-M1-Q04', 'C4-B12-M1', 2, 'Tam giác ABC có góc A = 50°, góc B = 60°. Góc ngoài tại đỉnh C có số đo là:', 'A', 60, '{"loai":"hinh","moTa":"Tam giác ABC, kéo dài cạnh BC về phía C thành tia Cx; góc ACx là góc ngoài tại C."}'::jsonb),
  ('C4-B12-M1-Q05', 'C4-B12-M1', 3, 'Tam giác có ba góc tỉ lệ với 1; 2; 3. Tam giác đó là:', 'A', 90, null),
  ('C4-B12-M1-Q06', 'C4-B12-M1', 3, 'Tam giác ABC có góc A = 80°, góc B − góc C = 20°. Số đo góc B là:', 'A', 90, null),
  ('C4-B12-M1-Q07', 'C4-B12-M1', 4, 'Tam giác ABC vuông tại A. Tia phân giác của góc B cắt AC tại D, góc ADB = 70°. Số đo góc C là:', 'A', 120, '{"loai":"hinh","moTa":"Tam giác ABC vuông tại A; BD là tia phân giác góc B (D thuộc AC); góc ADB = 70°."}'::jsonb),
  ('C4-B12-M1-Q08', 'C4-B12-M1', 4, 'Tam giác ABC có góc ngoài tại A bằng 120° và góc B = 2 · góc C. Số đo góc B là:', 'A', 120, null),
  ('C4-B13-M1-Q01', 'C4-B13-M1', 1, 'Cho ΔABC = ΔMNP. Cạnh tương ứng với cạnh AB là:', 'A', 45, null),
  ('C4-B13-M1-Q02', 'C4-B13-M1', 1, 'Cho ΔDEF = ΔHIK. Góc tương ứng với góc E là:', 'A', 45, null),
  ('C4-B13-M1-Q03', 'C4-B13-M1', 2, 'Hai tam giác ABC và DEF có AB = EF, BC = FD, CA = DE và góc A = góc E, góc B = góc F, góc C = góc D. Kí hiệu ĐÚNG là:', 'A', 60, null),
  ('C4-B13-M1-Q04', 'C4-B13-M1', 2, 'Cho ΔABC = ΔMNP, AB = 4 cm, BC = 6 cm, góc C = 40°. Khẳng định nào ĐÚNG?', 'A', 60, null),
  ('C4-B13-M1-Q05', 'C4-B13-M1', 3, 'Cho ΔABC = ΔDEF có góc A = 50°, góc E = 70°. Số đo góc F là:', 'A', 90, null),
  ('C4-B13-M1-Q06', 'C4-B13-M1', 3, 'Cho ΔABC = ΔDEF, chu vi tam giác ABC là 15 cm, AB = 4 cm, EF = 5 cm. Độ dài DF là:', 'A', 90, null),
  ('C4-B13-M1-Q07', 'C4-B13-M1', 4, 'Biết ΔPQR = ΔXYZ. Cách viết nào sau đây cũng ĐÚNG?', 'A', 120, null),
  ('C4-B13-M1-Q08', 'C4-B13-M1', 4, 'Hai tam giác có ba cặp góc tương ứng bằng nhau nhưng một tam giác có cạnh 3 cm, tam giác kia có cạnh tương ứng 6 cm. Hai tam giác đó:', 'A', 120, null),
  ('C4-B13-M2-Q01', 'C4-B13-M2', 1, 'Hai tam giác ABC và DEF có AB = DE, BC = EF, CA = FD. Kết luận ĐÚNG là:', 'A', 45, null),
  ('C4-B13-M2-Q02', 'C4-B13-M2', 1, 'Hai tam giác ABC và MNP có AB = MN, AC = MP. Cần thêm điều kiện nào để chúng bằng nhau theo trường hợp c.c.c?', 'A', 45, null),
  ('C4-B13-M2-Q03', 'C4-B13-M2', 2, 'Theo hình vẽ, hai tam giác ABD và ACD có AB = AC, BD = CD. Kết luận nào ĐÚNG?', 'A', 60, '{"loai":"hinh","moTa":"Hai tam giác ABD và ACD có chung cạnh AD; B và C nằm khác phía đối với AD; AB = AC, BD = CD (đánh dấu bằng nhau)."}'::jsonb),
  ('C4-B13-M2-Q04', 'C4-B13-M2', 2, 'Theo hình ABD và ACD ở trên (AB = AC, BD = CD), từ ΔABD = ΔACD ta suy ra:', 'A', 60, '{"loai":"hinh","moTa":"Hai tam giác ABD và ACD có chung cạnh AD; B và C nằm khác phía đối với AD; AB = AC, BD = CD (đánh dấu bằng nhau)."}'::jsonb),
  ('C4-B13-M2-Q05', 'C4-B13-M2', 3, 'Tứ giác ABCD có AB = CD, BC = DA. Để chứng minh góc B = góc D, ta xét hai tam giác nào?', 'A', 90, '{"loai":"hinh","moTa":"Tứ giác ABCD có AB = CD, BC = DA; vẽ đường chéo AC."}'::jsonb),
  ('C4-B13-M2-Q06', 'C4-B13-M2', 3, 'Một bạn viết: "Xét ΔABC và ΔDEF có AB = DE, AC = DF. Vậy ΔABC = ΔDEF (c.c.c)". Lỗi của bạn là:', 'A', 90, null),
  ('C4-B13-M2-Q07', 'C4-B13-M2', 4, 'Cho góc xOy. Trên Ox lấy A, trên Oy lấy B sao cho OA = OB. Vẽ cung tròn tâm A và tâm B cùng bán kính, cắt nhau tại M nằm trong góc. Vì sao OM là tia phân giác của góc xOy?', 'A', 120, '{"loai":"hinh","moTa":"Góc xOy; A trên Ox, B trên Oy, OA = OB; M trong góc với AM = BM."}'::jsonb),
  ('C4-B13-M2-Q08', 'C4-B13-M2', 4, 'Theo hình, AC và BD cắt nhau tại O với OA = OC, OB = OD. Thêm AB = CD. Có thể kết luận ΔOAB = ΔOCD theo c.c.c không?', 'A', 120, '{"loai":"hinh","moTa":"Hai đoạn thẳng AC và BD cắt nhau tại O; OA = OC, OB = OD."}'::jsonb),
  ('C4-B14-M1-Q01', 'C4-B14-M1', 1, 'Trong tam giác ABC, góc xen giữa hai cạnh AB và AC là:', 'A', 45, null),
  ('C4-B14-M1-Q02', 'C4-B14-M1', 1, 'ΔABC và ΔDEF có AB = DE, góc B = góc E. Cần thêm điều kiện nào để hai tam giác bằng nhau theo c.g.c?', 'A', 45, null),
  ('C4-B14-M1-Q03', 'C4-B14-M1', 2, 'Theo hình, AC cắt BD tại O, OA = OC, OB = OD. Hai tam giác OAB và OCD bằng nhau theo trường hợp nào?', 'A', 60, '{"loai":"hinh","moTa":"Hai đoạn thẳng AC và BD cắt nhau tại O; OA = OC, OB = OD."}'::jsonb),
  ('C4-B14-M1-Q04', 'C4-B14-M1', 2, 'Một bạn viết: "ΔABC và ΔDEF có AB = DE, AC = DF, góc B = góc E nên ΔABC = ΔDEF (c.g.c)". Nhận xét nào ĐÚNG?', 'A', 60, null),
  ('C4-B14-M1-Q05', 'C4-B14-M1', 3, 'Cho góc xOy, trên Ox lấy A, C; trên Oy lấy B, D sao cho OA = OB, OC = OD. Hai tam giác OAD và OBC bằng nhau theo trường hợp:', 'A', 90, '{"loai":"hinh","moTa":"Góc xOy; A, C thuộc Ox (OA < OC); B, D thuộc Oy (OB < OD); OA = OB, OC = OD; nối AD và BC."}'::jsonb),
  ('C4-B14-M1-Q06', 'C4-B14-M1', 3, 'Tam giác ABC có AB = AC. Tia phân giác góc A cắt BC tại D. Để chứng minh DB = DC, ta dùng:', 'A', 90, '{"loai":"hinh","moTa":"Tam giác ABC có AB = AC; AD là tia phân giác góc A, D thuộc BC."}'::jsonb),
  ('C4-B14-M1-Q07', 'C4-B14-M1', 4, 'Cho tam giác ABC, M là trung điểm BC. Trên tia đối của tia MA lấy D sao cho MD = MA. Khẳng định nào ĐÚNG?', 'A', 120, '{"loai":"hinh","moTa":"Tam giác ABC; M là trung điểm BC; D thuộc tia đối của tia MA, MD = MA; nối CD."}'::jsonb),
  ('C4-B14-M1-Q08', 'C4-B14-M1', 4, 'Ở câu trên (MA = MD, MB = MC), để suy ra AB // CD, ta dùng cặp góc nào?', 'A', 120, '{"loai":"hinh","moTa":"Như câu trên: ΔMAB = ΔMDC."}'::jsonb),
  ('C4-B14-M2-Q01', 'C4-B14-M2', 1, 'Trong tam giác ABC, cạnh nằm giữa (kề) hai góc B và C là:', 'A', 45, null),
  ('C4-B14-M2-Q02', 'C4-B14-M2', 1, 'ΔABC và ΔDEF có góc B = góc E, BC = EF, góc C = góc F. Kết luận:', 'A', 45, null),
  ('C4-B14-M2-Q03', 'C4-B14-M2', 2, 'ΔABC và ΔMNP có góc A = góc M, góc B = góc N, góc C = góc P. Kết luận nào ĐÚNG?', 'A', 60, null),
  ('C4-B14-M2-Q04', 'C4-B14-M2', 2, 'ΔABC và ΔDEF có góc B = góc E, góc C = góc F, AB = DE. Nhận xét nào ĐÚNG?', 'A', 60, null),
  ('C4-B14-M2-Q05', 'C4-B14-M2', 3, 'Cho đoạn AB, O là trung điểm. Qua A và B kẻ hai đường thẳng song song; một đường thẳng qua O cắt chúng tại C và D. Để chứng minh OC = OD, ta dùng:', 'A', 90, '{"loai":"hinh","moTa":"Đoạn AB, O là trung điểm; Ax // By ở hai phía của AB; đường thẳng qua O cắt Ax tại C, By tại D."}'::jsonb),
  ('C4-B14-M2-Q06', 'C4-B14-M2', 3, 'Hai tam giác ABC và DEF có góc A = góc D = 50°, AB = DE = 4 cm, góc B = góc E = 60°. Độ dài cạnh nào chắc chắn bằng nhau ngoài AB và DE?', 'A', 90, null),
  ('C4-B14-M2-Q07', 'C4-B14-M2', 4, 'Hai tam giác đều, một tam giác cạnh 3 cm và một tam giác cạnh 5 cm. Bạn Nam nói: "Ba góc đều 60° nên hai tam giác bằng nhau". Nhận xét nào ĐÚNG?', 'A', 120, null),
  ('C4-B14-M2-Q08', 'C4-B14-M2', 4, 'Để đo khoảng cách AB qua một cái ao, người ta chọn O, kéo dài AO lấy C với OC = OA, kéo dài BO lấy D với OD = OB, rồi đo CD. Vì sao AB = CD?', 'A', 120, '{"loai":"hinh","moTa":"A, B ở hai bờ ao; O trên bờ; C thuộc tia đối của OA, OC = OA; D thuộc tia đối của OB, OD = OB."}'::jsonb),
  ('C4-B15-M1-Q01', 'C4-B15-M1', 1, 'Tam giác ABC vuông tại A. Cạnh huyền là:', 'A', 45, null),
  ('C4-B15-M1-Q02', 'C4-B15-M1', 1, 'ΔABC vuông tại A và ΔDEF vuông tại D có AB = DE, AC = DF. Kết luận:', 'A', 45, null),
  ('C4-B15-M1-Q03', 'C4-B15-M1B', 2, 'ΔABC vuông tại A và ΔMNP vuông tại M có BC = NP, góc B = góc N. Kết luận:', 'A', 60, null),
  ('C4-B15-M1-Q04', 'C4-B15-M1B', 2, 'Hai tam giác vuông có góc nhọn 30° và 60° tương ứng bằng nhau. Kết luận nào ĐÚNG?', 'A', 60, null),
  ('C4-B15-M1-Q05', 'C4-B15-M1', 3, 'ΔABC vuông tại A, ΔDEF vuông tại D có AB = DE, góc B = góc E. Hai tam giác bằng nhau theo trường hợp:', 'A', 90, null),
  ('C4-B15-M1-Q06', 'C4-B15-M1B', 3, 'Cho góc xOy, M nằm trên tia phân giác Oz. Kẻ MA ⊥ Ox, MB ⊥ Oy (A ∈ Ox, B ∈ Oy). Vì sao MA = MB?', 'A', 90, '{"loai":"hinh","moTa":"Góc xOy, Oz là tia phân giác; M thuộc Oz; MA ⊥ Ox tại A, MB ⊥ Oy tại B."}'::jsonb),
  ('C4-B15-M1-Q07', 'C4-B15-M1B', 4, 'Tam giác ABC có AB = AC, kẻ AH ⊥ BC (H ∈ BC). Bạn An viết: "ΔAHB = ΔAHC (cạnh huyền – góc nhọn) vì AB = AC". Nhận xét nào ĐÚNG?', 'A', 120, '{"loai":"hinh","moTa":"Tam giác ABC có AB = AC; AH vuông góc với BC tại H."}'::jsonb),
  ('C4-B15-M1-Q08', 'C4-B15-M1', 4, 'Hai cột đèn cao bằng nhau AH và A''H'' dựng thẳng đứng; bóng nắng cùng lúc tạo với mặt đất các góc bằng nhau. Vì sao hai bóng HB và H''B'' dài bằng nhau?', 'A', 120, '{"loai":"hinh","moTa":"Hai tam giác vuông AHB (vuông tại H) và A''H''B'' (vuông tại H''); AH = A''H''; góc B = góc B''."}'::jsonb),
  ('C4-B15-M2-Q01', 'C4-B15-M2', 1, 'ΔABC vuông tại A, ΔDEF vuông tại D có BC = EF, AB = DE. Kết luận:', 'A', 45, null),
  ('C4-B15-M2-Q02', 'C4-B15-M2', 1, 'Trường hợp "cạnh huyền – cạnh góc vuông" áp dụng cho:', 'A', 45, null),
  ('C4-B15-M2-Q03', 'C4-B15-M2', 2, 'Tam giác ABC có AB = AC, AH ⊥ BC. Ta có ΔAHB = ΔAHC theo trường hợp:', 'A', 60, '{"loai":"hinh","moTa":"Tam giác ABC có AB = AC; AH vuông góc với BC tại H."}'::jsonb),
  ('C4-B15-M2-Q04', 'C4-B15-M2', 2, 'Hai tam giác thường ABC và DEF có AB = DE, BC = EF, góc A = góc D (góc A không xen giữa AB, BC). Kết luận nào ĐÚNG?', 'A', 60, null),
  ('C4-B15-M2-Q05', 'C4-B15-M2', 3, 'ΔABC vuông tại A có BC = 10 cm, AB = 6 cm. ΔMNP vuông tại M có NP = 10 cm, MP = 6 cm. Khẳng định nào ĐÚNG?', 'A', 90, null),
  ('C4-B15-M2-Q06', 'C4-B15-M2', 3, 'Cho đường tròn tâm O; A, B là hai điểm trên đường tròn. Kẻ OH ⊥ AB (H ∈ AB). Để chứng minh HA = HB, ta dùng:', 'A', 90, '{"loai":"hinh","moTa":"Đường tròn tâm O; dây AB; OH vuông góc với AB tại H."}'::jsonb),
  ('C4-B15-M2-Q07', 'C4-B15-M2', 4, 'Hai thang dài bằng nhau dựa vào hai bức tường thẳng đứng, chân thang cách chân tường bằng nhau. Vì sao hai thang tạo với mặt đất các góc bằng nhau?', 'A', 120, '{"loai":"hinh","moTa":"Hai tam giác vuông (góc vuông ở chân tường): cạnh huyền là chiếc thang, một cạnh góc vuông là khoảng cách từ chân thang đến chân tường."}'::jsonb),
  ('C4-B15-M2-Q08', 'C4-B15-M2', 4, 'Tam giác ABC có các đường cao BD và CE bằng nhau (D ∈ AC, E ∈ AB). Chứng minh ΔBEC = ΔCDB rồi suy ra góc ABC = góc ACB. Trường hợp dùng là:', 'A', 120, '{"loai":"hinh","moTa":"Tam giác ABC nhọn; BD ⊥ AC tại D, CE ⊥ AB tại E; BD = CE."}'::jsonb),
