  ('C4-B16-M1-Q06', 'C4-B16-M1', 3, 'Tam giác cân có một góc bằng 100°. Mỗi góc còn lại bằng:', 'A', 90, null),
  ('C4-B16-M1-Q07', 'C4-B16-M1', 4, 'Tam giác ABC cân tại A. Trên cạnh AB, AC lấy D, E sao cho AD = AE. Khẳng định nào ĐÚNG?', 'A', 120, '{"loai":"hinh","moTa":"Tam giác ABC cân tại A; D trên AB, E trên AC, AD = AE; nối DE, BE, CD."}'::jsonb),
  ('C4-B16-M1-Q08', 'C4-B16-M1', 4, 'Mái nhà hình tam giác cân, góc ở đỉnh 110°. Góc tạo bởi mái nhà với xà ngang (góc ở đáy) bằng:', 'A', 120, null),
  ('C4-B16-M2-Q01', 'C4-B16-M2', 1, 'Đường trung trực của đoạn thẳng AB là đường thẳng:', 'A', 45, null),
  ('C4-B16-M2-Q02', 'C4-B16-M2B', 1, 'Điểm M nằm trên đường trung trực của đoạn AB, MA = 5 cm. Khi đó:', 'A', 45, null),
