  ('C4-B16-M2-Q04', 'C4-B16-M2', 2, 'Đường thẳng d vuông góc với đoạn AB tại H, HA = 2 cm, HB = 3 cm. d có phải đường trung trực của AB không?', 'A', 60, null),
  ('C4-B16-M2-Q05', 'C4-B16-M2B', 3, 'Hai điểm M và N cùng cách đều A và B (MA = MB, NA = NB, M ≠ N). Đường thẳng MN là:', 'A', 90, null),
  ('C4-B16-M2-Q06', 'C4-B16-M2', 3, 'Tam giác ABC cân tại A, M là trung điểm BC. Khẳng định nào ĐÚNG?', 'A', 90, null),
  ('C4-B16-M2-Q07', 'C4-B16-M2B', 4, 'Hai nhà A và B ở cùng một phía của con đường thẳng d. Cần đặt trạm nước M trên d sao cho MA = MB. Vị trí M là:', 'A', 120, '{"loai":"hinh","moTa":"Đường thẳng d; hai điểm A, B cùng phía với d, AB không vuông góc với d."}'::jsonb),
  ('C4-B16-M2-Q08', 'C4-B16-M2B', 4, 'Vẽ đường trung trực của đoạn AB bằng compa: vẽ hai cung tròn tâm A và tâm B cùng bán kính r, cắt nhau tại M và N. Điều kiện của r là:', 'A', 120, null),
  ('C4-B15-M1-Q09', 'C4-B15-M1', 2, 'ΔABC vuông tại A và ΔDEF vuông tại D có AC = DF, góc C = góc F. Kết luận:', 'A', 60, null),
  ('C4-B15-M1-Q10', 'C4-B15-M1', 2, 'ΔABC vuông tại A và ΔMNP vuông tại M có AB = MN. Cần thêm điều kiện nào để hai tam giác bằng nhau theo trường hợp hai cạnh góc vuông?', 'A', 60, null),
  ('C4-B15-M1-Q11', 'C4-B15-M1', 3, 'Cho đoạn thẳng AB có trung điểm M. Trên đường thẳng vuông góc với AB tại M lấy điểm C. Vì sao CA = CB?', 'A', 90, '{"loai":"hinh","moTa":"Đoạn AB, M là trung điểm; đường thẳng vuông góc với AB tại M; C thuộc đường thẳng đó."}'::jsonb),
  ('C4-B15-M1-Q12', 'C4-B15-M1', 4, 'Đo khoảng cách AB qua một cái ao: đứng ở B kẻ BC ⊥ AB, lấy D là trung điểm BC; từ C kẻ CE ⊥ BC (E và A khác phía đối với BC) sao cho A, D, E thẳng hàng. Vì sao AB = CE?', 'A', 120, '{"loai":"hinh","moTa":"Tam giác ABD vuông tại B và tam giác ECD vuông tại C; D là trung điểm BC; A, D, E thẳng hàng."}'::jsonb),
  ('C4-B15-M1B-Q01', 'C4-B15-M1B', 1, 'ΔABC vuông tại A và ΔDEF vuông tại D có BC = EF, góc C = góc F. Hai tam giác bằng nhau theo trường hợp:', 'A', 45, null),
  ('C4-B15-M1B-Q02', 'C4-B15-M1B', 1, 'Để dùng trường hợp cạnh huyền – góc nhọn cho hai tam giác vuông, cần biết:', 'A', 45, null),
  ('C4-B15-M1B-Q05', 'C4-B15-M1B', 3, 'ΔABC vuông tại A, ΔDEF vuông tại D có BC = EF = 10 cm, góc B = 35°, góc F = 55°. Khẳng định nào ĐÚNG?', 'A', 90, null),
  ('C4-B15-M1B-Q08', 'C4-B15-M1B', 4, 'Tam giác nhọn ABC có góc B = góc C. Kẻ BD ⊥ AC (D ∈ AC), CE ⊥ AB (E ∈ AB). Vì sao BD = CE?', 'A', 120, '{"loai":"hinh","moTa":"Tam giác nhọn ABC, góc B = góc C; BD ⊥ AC tại D, CE ⊥ AB tại E."}'::jsonb),
  ('C4-B16-M1-Q09', 'C4-B16-M1', 3, 'Tam giác ABC cân tại A có góc B gấp đôi góc A. Số đo góc A là:', 'A', 90, null),
