  ('C4-B16-M1B-Q04', 'C4-B16-M1B', 2, 'Vẽ tam giác ABC cân tại A có BC = 4 cm, AB = AC = 3 cm bằng thước và compa. Sau khi vẽ đoạn BC = 4 cm, bước tiếp theo là:', 'A', 60, null),
