  ('C4-B16-M1B-Q07', 'C4-B16-M1B', 4, 'Cho tam giác đều ABC. Trên các cạnh AB, BC, CA lần lượt lấy D, E, F sao cho AD = BE = CF. Tam giác DEF là:', 'A', 120, '{"loai":"hinh","moTa":"Tam giác đều ABC; D trên AB, E trên BC, F trên CA với AD = BE = CF."}'::jsonb),
