  ('C4-B16-M2-Q09', 'C4-B16-M2', 1, 'Đoạn thẳng AB = 6 cm. Đường trung trực của AB cắt AB tại H. Độ dài HA là:', 'A', 45, null),
  ('C4-B16-M2-Q10', 'C4-B16-M2', 2, 'Đường thẳng d đi qua trung điểm M của đoạn AB và tạo với AB một góc 80°. d có phải là đường trung trực của AB không?', 'A', 60, null),
  ('C4-B16-M2-Q11', 'C4-B16-M2', 3, 'Cho đoạn AB có trung điểm M, đường thẳng d vuông góc với AB tại M. Điểm C thuộc đoạn AB, C ≠ M. Đường thẳng đi qua C và vuông góc với AB:', 'A', 90, null),
  ('C4-B16-M2-Q12', 'C4-B16-M2', 4, 'Tam giác ABC có AB = AC, kẻ AH ⊥ BC tại H. Để kết luận AH là đường trung trực của BC, cần chỉ ra:', 'A', 120, '{"loai":"hinh","moTa":"Tam giác ABC có AB = AC; AH vuông góc với BC tại H."}'::jsonb),
