  ('C4-LTC-Q02', 'C4-LTC', 1, 'Cho ΔABC = ΔDEF, góc B = 70°, góc C = 50°. Số đo góc D là:', 'A', 45, null),
  ('C4-LTC-Q03', 'C4-LTC', 2, 'Cho góc xOy. Trên Ox lấy A, trên Oy lấy B sao cho OA = OB. Gọi M là trung điểm AB. Khẳng định nào ĐÚNG?', 'A', 60, '{"loai":"hinh","moTa":"Góc xOy; A thuộc Ox, B thuộc Oy, OA = OB; M là trung điểm của AB."}'::jsonb),
