  ('C4-LTC-Q07', 'C4-LTC', 4, 'Tam giác ABC cân tại A, kẻ BH ⊥ AC, CK ⊥ AB (H ∈ AC, K ∈ AB). Khẳng định nào ĐÚNG?', 'A', 120, '{"loai":"hinh","moTa":"Tam giác ABC cân tại A (góc A nhọn); BH ⊥ AC tại H; CK ⊥ AB tại K."}'::jsonb),
