  ('C4-LTC-Q06', 'B', 'E-BN-01'),
  ('C4-LTC-Q06', 'C', 'E-CCC-01'),
  ('C4-LTC-Q06', 'D', 'E-CC-01'),
  ('C4-LTC-Q07', 'B', 'E-TGV-01'),
  ('C4-LTC-Q07', 'C', 'E-BN-01'),
  ('C4-LTC-Q07', 'D', 'E-CC-01'),
  ('C4-LTC-Q08', 'B', 'E-TGC-01'),
  ('C4-LTC-Q08', 'C', 'E-TGC-03'),
  ('C4-LTC-Q08', 'D', 'E-TTR-01')
on conflict (question_id, option_key) do update set error_code = excluded.error_code;

insert into error_hints (error_code, tier, hint_text) values
  ('E-TBG-01', 1, 'Tổng ba góc của mọi tam giác bằng bao nhiêu độ, có phụ thuộc tam giác to hay nhỏ không?'),
  ('E-TBG-01', 2, 'Mọi tam giác đều có tổng ba góc bằng 180°, không phụ thuộc kích thước, hình dạng. 360° là tổng các góc của tứ giác.'),
  ('E-TBG-01', 3, 'Ví dụ: góc A = 60°, góc B = 70° thì góc C = 180° − 60° − 70° = 50°. Em lấy 180° trừ đi tổng hai góc đã biết.'),
  ('E-TBG-02', 1, 'Nếu tam giác có hai góc vuông thì góc thứ ba bằng bao nhiêu?'),
  ('E-TBG-02', 2, 'Một tam giác có nhiều nhất một góc vuông hoặc một góc tù. Trong tam giác vuông, hai góc nhọn có tổng 90° (phụ nhau).'),
  ('E-TBG-02', 3, 'Ví dụ: tam giác vuông tại M có góc N = 35° thì góc P = 90° − 35° = 55°. Em dùng 90°, không dùng 180°.'),
  ('E-TBG-03', 1, 'Góc ngoài tại một đỉnh kề bù với góc trong nào?'),
  ('E-TBG-03', 2, 'Góc ngoài tại một đỉnh bằng tổng hai góc trong không kề với nó (hai góc ở hai đỉnh còn lại).'),
  ('E-TBG-03', 3, 'Ví dụ: góc A = 50°, góc B = 60° thì góc ngoài tại C = 50° + 60° = 110° (cũng bằng 180° − góc C = 180° − 70°). Em kiểm tra bằng cả hai cách.'),
  ('E-BN-01', 1, 'Đỉnh A ứng với đỉnh nào của tam giác kia? B ứng với đỉnh nào?'),
  ('E-BN-01', 2, 'Khi viết ΔABC = ΔDEF, các đỉnh tương ứng phải viết cùng vị trí: A ứng với D, B ứng với E, C ứng với F.'),
  ('E-BN-01', 3, 'Ví dụ: góc A = góc E, góc B = góc F, góc C = góc D thì viết ΔABC = ΔEFD. Em ghép từng cặp đỉnh rồi mới viết.'),
  ('E-BN-02', 1, 'Trong kí hiệu, chữ cái thứ nhất ứng với chữ cái thứ nhất, thứ hai ứng với thứ hai…?'),
  ('E-BN-02', 2, 'Từ ΔABC = ΔMNP: cạnh tạo bởi chữ 1 và 2 (AB) ứng với MN; chữ 2 và 3 (BC) ứng với NP; chữ 1 và 3 (AC) ứng với MP. Góc B (chữ thứ hai) ứng với góc N.'),
  ('E-BN-02', 3, 'Em đặt hai kí hiệu thẳng hàng: A B C / M N P, rồi đọc theo cột.'),
  ('E-CCC-01', 1, 'Trường hợp c.c.c cần mấy cặp cạnh bằng nhau?'),
  ('E-CCC-01', 2, 'c.c.c cần đủ ba cặp cạnh tương ứng bằng nhau. Mới có hai cặp thì chưa kết luận được.'),
  ('E-CCC-01', 3, 'Ví dụ: có AB = DE, AC = DF thì phải chứng minh thêm BC = EF (hoặc tìm cạnh chung). Em đếm lại từng cặp.'),
  ('E-CC-01', 1, 'Hai tam giác có cạnh nào, góc nào dùng chung không? Có góc nào đối đỉnh không?'),
  ('E-CC-01', 2, 'Cạnh chung, góc chung, góc đối đỉnh là những cặp yếu tố bằng nhau có sẵn, không cần giả thiết cho.'),
  ('E-CC-01', 3, 'Ví dụ: ΔABD và ΔACD có AD là cạnh chung, nên với AB = AC, BD = CD là đủ ba cặp cạnh. Em tô màu phần chung trên hình.'),
  ('E-CGC-01', 1, 'Góc em dùng có nằm giữa hai cạnh đã cho không?'),
  ('E-CGC-01', 2, 'Trong c.g.c, góc phải xen giữa hai cạnh (tạo bởi chính hai cạnh đó). Góc A xen giữa AB và AC; góc B xen giữa BA và BC.'),
  ('E-CGC-01', 3, 'Ví dụ: AB = DE, AC = DF thì góc cần là góc A = góc D, không phải góc B = góc E. Em tìm đỉnh chung của hai cạnh.'),
  ('E-GCG-01', 1, 'Cạnh em dùng có nằm giữa hai góc đã cho không?'),
  ('E-GCG-01', 2, 'Trong g.c.g, cạnh phải kề cả hai góc: cạnh BC kề góc B và góc C. Nếu cạnh không kề, hãy dùng tổng ba góc để tìm góc còn lại rồi chọn đúng cặp góc kề.'),
  ('E-GCG-01', 3, 'Ví dụ: góc B = góc E, góc C = góc F, AB = DE: suy ra góc A = góc D, rồi dùng góc A, cạnh AB, góc B. Em kiểm tra hai đầu mút của cạnh.'),
  ('E-GGG-01', 1, 'Hai tam giác có ba góc bằng nhau nhưng một cái to, một cái nhỏ có bằng nhau không?'),
  ('E-GGG-01', 2, 'Ba cặp góc bằng nhau chưa đủ để hai tam giác bằng nhau. Mọi trường hợp bằng nhau đều cần ít nhất một cặp cạnh.'),
  ('E-GGG-01', 3, 'Ví dụ: tam giác đều cạnh 3 cm và cạnh 5 cm có cùng ba góc 60° nhưng không bằng nhau. Em tìm thêm một cặp cạnh.'),
  ('E-TGV-01', 1, 'Cạnh nào nằm đối diện với góc vuông?'),
  ('E-TGV-01', 2, 'Cạnh huyền là cạnh đối diện góc vuông và là cạnh dài nhất. Hai cạnh kề góc vuông là cạnh góc vuông.'),
  ('E-TGV-01', 3, 'Ví dụ: tam giác ABC vuông tại A thì cạnh huyền là BC, cạnh góc vuông là AB, AC. Em đánh dấu góc vuông rồi tìm cạnh đối diện.'),
  ('E-TGV-02', 1, 'Hai tam giác vuông có cùng góc nhưng một cái to, một cái nhỏ có bằng nhau không?'),
  ('E-TGV-02', 2, 'Hai tam giác vuông muốn bằng nhau cần ít nhất một cặp cạnh tương ứng bằng nhau (cùng với góc hoặc cạnh khác). Chỉ hai góc nhọn bằng nhau là chưa đủ.'),
  ('E-TGV-02', 3, 'Ví dụ: hai ê ke 30°–60° cỡ nhỏ và cỡ lớn có cùng góc nhưng không bằng nhau. Em tìm một cặp cạnh.'),
  ('E-TGV-03', 1, 'Hai tam giác em xét có phải tam giác vuông không?'),
  ('E-TGV-03', 2, 'Trường hợp cạnh huyền – cạnh góc vuông chỉ đúng cho tam giác vuông. Với tam giác thường, hai cạnh và một góc không xen giữa chưa đủ.'),
  ('E-TGV-03', 3, 'Em kiểm tra: có góc vuông không? Có cạnh huyền (đối diện góc vuông) không? Nếu không, phải dùng c.c.c, c.g.c hoặc g.c.g.'),
  ('E-TGC-01', 1, 'Tam giác cân tại A thì hai cạnh nào bằng nhau và hai góc nào bằng nhau?'),
  ('E-TGC-01', 2, 'Tam giác ABC cân tại A: AB = AC là hai cạnh bên, BC là cạnh đáy, góc A là góc ở đỉnh, góc B = góc C là hai góc ở đáy.'),
  ('E-TGC-01', 3, 'Em nhớ: "cân tại đâu thì đỉnh ở đó"; hai góc ở đáy nằm hai đầu cạnh đáy.'),
  ('E-TGC-02', 1, 'Tổng hai góc ở đáy bằng bao nhiêu? Mỗi góc bằng bao nhiêu?'),
  ('E-TGC-02', 2, 'Góc ở đáy = (180° − góc ở đỉnh) : 2. Góc ở đỉnh = 180° − 2 · góc ở đáy.'),
  ('E-TGC-02', 3, 'Ví dụ: góc ở đỉnh 40° thì mỗi góc ở đáy = (180° − 40°) : 2 = 70°. Em nhớ chia đôi.'),
  ('E-TGC-03', 1, 'Tam giác cân có một góc 60° thì hai góc còn lại bằng bao nhiêu?'),
  ('E-TGC-03', 2, 'Tam giác cân có một góc 60° là tam giác đều. Tam giác đều cũng là tam giác cân (cân tại cả ba đỉnh).'),
  ('E-TGC-03', 3, 'Ví dụ: cân tại A, góc A = 60° thì góc B = góc C = (180° − 60°) : 2 = 60°. Em tính hai góc còn lại để kiểm tra.'),
  ('E-TTR-01', 1, 'Đường trung trực cần thoả mãn mấy điều kiện?'),
  ('E-TTR-01', 2, 'Đường trung trực của AB phải đủ hai điều kiện: vuông góc với AB và đi qua trung điểm của AB.'),
  ('E-TTR-01', 3, 'Ví dụ: d ⊥ AB tại H với HA = 2 cm, HB = 3 cm thì d không phải trung trực. Em kiểm tra cả hai điều kiện.'),
  ('E-TTR-02', 1, 'Điểm cách đều A và B nằm ở đâu?'),
  ('E-TTR-02', 2, 'Điểm nằm trên đường trung trực của AB thì cách đều A và B; ngược lại, điểm cách đều A và B thì nằm trên đường trung trực của AB.'),
  ('E-TTR-02', 3, 'Ví dụ: NA = NB thì N thuộc trung trực của AB, dù N không thuộc đoạn AB. Em dùng tính chất hai chiều này.')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-TBG-01', 'Có bạn nghĩ tam giác càng to thì tổng ba góc càng lớn, hoặc nhớ nhầm sang 360°. Thật ra mọi tam giác đều giống nhau ở điểm này.', 'Tổng ba góc của mọi tam giác bằng 180°. Góc còn lại = 180° − (tổng hai góc đã biết). Tổng 360° là của tứ giác.', '[{"de":"Tam giác ABC có góc A = 60°, góc B = 70°. Tính góc C.","giai":"Cách nghĩ sai: 360° − 60° − 70° = 230°. Cách đúng: góc C = 180° − 60° − 70° = 50°."},{"de":"Tam giác ABC có góc A = 80°, góc B − góc C = 20°. Tính góc B.","giai":"Góc B + góc C = 100°, góc B − góc C = 20° nên góc B = (100° + 20°) : 2 = 60°."}]'::jsonb, '[{"de":"Tam giác có hai góc 45° và 65°. Góc thứ ba?","dapAn":"70°","giaiThich":"180° − 110° = 70°."},{"de":"Tam giác có ba góc tỉ lệ 1 : 2 : 3. Góc lớn nhất?","dapAn":"90°","giaiThich":"180° : 6 = 30°, góc lớn nhất 3 · 30° = 90°."}]'::jsonb),
  ('VBH-TBG-02', 'Nhiều bạn vẽ được "tam giác có hai góc tù" trên giấy nháp, hoặc tính góc nhọn của tam giác vuông bằng 180° trừ một góc. Cả hai đều quên tổng 180°.', 'Một tam giác có nhiều nhất một góc vuông hoặc một góc tù. Tam giác nhọn: ba góc nhọn; vuông: một góc vuông; tù: một góc tù. Trong tam giác vuông, hai góc nhọn có tổng 90°.', '[{"de":"Tam giác MNP vuông tại M, góc N = 35°. Tính góc P.","giai":"Cách nghĩ sai: 180° − 35° = 145°. Cách đúng: hai góc nhọn phụ nhau nên góc P = 90° − 35° = 55°."},{"de":"Có tam giác nào có hai góc 100° không?","giai":"Không, vì 100° + 100° = 200° > 180°."}]'::jsonb, '[{"de":"Tam giác vuông có một góc nhọn 62°. Góc nhọn còn lại?","dapAn":"28°","giaiThich":"90° − 62° = 28°."},{"de":"Tam giác có các góc 30°, 50°, 100° là tam giác gì?","dapAn":"Tam giác tù","giaiThich":"Có một góc tù 100°."}]'::jsonb),
  ('VBH-TBG-03', 'Góc ngoài nằm "bên ngoài" tam giác nên dễ bị tính nhầm. Có một cách nhớ rất gọn.', 'Góc ngoài tại một đỉnh kề bù với góc trong tại đỉnh đó và bằng tổng hai góc trong không kề với nó.', '[{"de":"Tam giác ABC có góc A = 50°, góc B = 60°. Tính góc ngoài tại C.","giai":"Cách nghĩ sai: bằng góc C = 70°, hoặc 50° + 60° + 70° = 180°. Cách đúng: góc ngoài tại C = 50° + 60° = 110° (kiểm tra: 180° − 70° = 110°)."},{"de":"Góc ngoài tại A bằng 120°, góc B = 2 · góc C. Tính góc B.","giai":"Góc B + góc C = 120°, góc B = 2 · góc C nên góc C = 40°, góc B = 80°."}]'::jsonb, '[{"de":"Tam giác có hai góc 35° và 75°. Góc ngoài tại đỉnh còn lại?","dapAn":"110°","giaiThich":"35° + 75° = 110°."},{"de":"Góc ngoài tại B là 130°, góc A = 60°. Góc C?","dapAn":"70°","giaiThich":"130° − 60° = 70°."}]'::jsonb),
  ('VBH-BN-01', 'Kí hiệu hai tam giác bằng nhau không chỉ là ghi tên: thứ tự các chữ cái cho biết đỉnh nào ứng với đỉnh nào.', 'Viết ΔABC = ΔDEF khi A ứng với D, B ứng với E, C ứng với F. Có thể đổi thứ tự cả hai bên cùng lúc: ΔBCA = ΔEFD.', '[{"de":"Góc A = góc E, góc B = góc F, góc C = góc D (các cạnh tương ứng cũng bằng nhau). Viết kí hiệu.","giai":"Cách nghĩ sai: ΔABC = ΔDEF theo thứ tự chữ cái. Cách đúng: A ↔ E, B ↔ F, C ↔ D nên ΔABC = ΔEFD."},{"de":"Biết ΔPQR = ΔXYZ, viết lại bắt đầu bằng đỉnh Q.","giai":"ΔQRP = ΔYZX (đổi đồng thời hai bên)."}]'::jsonb, '[{"de":"M ↔ C, N ↔ A, P ↔ B. Viết kí hiệu bắt đầu bằng ΔMNP.","dapAn":"ΔMNP = ΔCAB","giaiThich":"Giữ đúng cặp tương ứng."},{"de":"ΔABC = ΔDEF. Cách viết ΔBAC = ΔEDF đúng hay sai?","dapAn":"Đúng","giaiThich":"Đổi đồng thời cả hai bên."}]'::jsonb),
  ('VBH-BN-02', 'Từ kí hiệu đúng, nhiều bạn vẫn đọc nhầm cạnh, góc tương ứng. Hãy đọc theo vị trí chữ cái.', 'Với ΔABC = ΔMNP: AB = MN (chữ 1–2), BC = NP (chữ 2–3), AC = MP (chữ 1–3); góc A = góc M, góc B = góc N, góc C = góc P.', '[{"de":"ΔABC = ΔMNP. Cạnh nào bằng AB? Góc nào bằng góc B?","giai":"Cách nghĩ sai: AB = MP, góc B = góc P. Cách đúng: viết thẳng hàng A B C / M N P: AB = MN, góc B = góc N."},{"de":"ΔABC = ΔDEF, chu vi 15 cm, AB = 4 cm, EF = 5 cm. Tính DF.","giai":"BC = EF = 5 cm; AC = 15 − 4 − 5 = 6 cm; DF = AC = 6 cm."}]'::jsonb, '[{"de":"ΔDEF = ΔHIK. Góc nào bằng góc E?","dapAn":"Góc I","giaiThich":"E và I cùng ở vị trí thứ hai."},{"de":"ΔABC = ΔMNP, BC = 6 cm. Cạnh nào bằng 6 cm?","dapAn":"NP","giaiThich":"BC (chữ 2–3) ứng với NP."}]'::jsonb),
  ('VBH-CCC-01', 'Trường hợp c.c.c có ba chữ "c" là vì cần ba cặp cạnh. Thiếu một cặp là chưa đủ.', 'Nếu ba cạnh của tam giác này lần lượt bằng ba cạnh của tam giác kia thì hai tam giác bằng nhau (c.c.c). Trước khi kết luận, đếm đủ ba cặp, kể cả cạnh chung.', '[{"de":"ΔABC và ΔDEF có AB = DE, AC = DF. Kết luận được chưa?","giai":"Cách nghĩ sai: kết luận ngay ΔABC = ΔDEF (c.c.c). Cách đúng: mới có hai cặp; cần thêm BC = EF."},{"de":"Tứ giác ABCD có AB = CD, BC = DA. Chứng minh ΔABC = ΔCDA.","giai":"AB = CD, BC = DA, AC cạnh chung: đủ ba cặp nên ΔABC = ΔCDA (c.c.c)."}]'::jsonb, '[{"de":"AB = MN, BC = NP. Cần thêm gì để ΔABC = ΔMNP (c.c.c)?","dapAn":"AC = MP","giaiThich":"Cặp cạnh thứ ba."},{"de":"Có ba cặp cạnh bằng nhau thì có cần thêm góc không?","dapAn":"Không","giaiThich":"c.c.c đã đủ."}]'::jsonb),
  ('VBH-CC-01', 'Nhiều bài cho thiếu một cặp cạnh, góc trong giả thiết vì cặp đó "nằm sẵn trên hình". Em cần tập nhìn ra.', 'Ba loại yếu tố bằng nhau có sẵn: cạnh chung (hai tam giác dùng chung một cạnh), góc chung, góc đối đỉnh (hai đoạn thẳng cắt nhau).', '[{"de":"ΔABD và ΔACD có AB = AC, BD = CD. Có đủ c.c.c không?","giai":"Cách nghĩ sai: thiếu một cặp cạnh. Cách đúng: AD là cạnh chung nên đủ ba cặp."},{"de":"AC cắt BD tại O, OA = OC, OB = OD. Thêm cặp nào để có c.g.c?","giai":"Góc AOB = góc COD (đối đỉnh) xen giữa hai cặp cạnh."}]'::jsonb, '[{"de":"ΔOAD và ΔOBC cùng có góc O. Góc O là gì của hai tam giác?","dapAn":"Góc chung","giaiThich":"Cùng một góc xOy."},{"de":"Hai đường thẳng cắt nhau tạo ra cặp góc bằng nhau nào?","dapAn":"Hai góc đối đỉnh","giaiThich":"Góc đối đỉnh bằng nhau."}]'::jsonb),
  ('VBH-CGC-01', 'Trường hợp c.g.c đòi hỏi góc phải "kẹp" giữa hai cạnh. Lấy góc khác thì có thể dựng được hai tam giác khác nhau.', 'Hai cạnh và góc xen giữa của tam giác này bằng hai cạnh và góc xen giữa của tam giác kia thì hai tam giác bằng nhau. Góc xen giữa AB và AC là góc A (đỉnh chung của hai cạnh).', '[{"de":"AB = DE, AC = DF, góc B = góc E. Có kết luận c.g.c được không?","giai":"Cách nghĩ sai: được. Cách đúng: góc B không xen giữa AB và AC; góc cần là góc A = góc D."},{"de":"AB = AC, AD là phân giác góc A. Chứng minh ΔABD = ΔACD.","giai":"AB = AC, góc BAD = góc CAD (xen giữa), AD chung: ΔABD = ΔACD (c.g.c)."}]'::jsonb, '[{"de":"Góc xen giữa BA và BC là góc nào?","dapAn":"Góc B","giaiThich":"B là đỉnh chung."},{"de":"AB = DE, góc B = góc E. Cần thêm cạnh nào cho c.g.c?","dapAn":"BC = EF","giaiThich":"Góc B xen giữa BA và BC."}]'::jsonb),
  ('VBH-GCG-01', 'Ở g.c.g, cạnh phải nằm giữa hai góc. Nếu đề cho cạnh không kề, ta vẫn có cách xoay xở.', 'Một cạnh và hai góc kề cạnh đó bằng tương ứng thì hai tam giác bằng nhau (g.c.g). Cạnh BC kề góc B và góc C. Nếu cạnh không kề, dùng tổng ba góc tìm góc thứ ba rồi chọn cặp góc kề cạnh.', '[{"de":"Góc B = góc E, góc C = góc F, AB = DE. Viết (g.c.g) với góc B, góc C có đúng không?","giai":"Cách nghĩ sai: đúng. Cách đúng: AB không kề góc C. Suy ra góc A = góc D (tổng 180°), rồi dùng góc A, cạnh AB, góc B."},{"de":"O là trung điểm AB, Ax // By, đường qua O cắt Ax tại C, By tại D. Chứng minh OC = OD.","giai":"ΔOAC = ΔOBD (g.c.g): góc OAC = góc OBD (so le trong), OA = OB, góc AOC = góc BOD (đối đỉnh)."}]'::jsonb, '[{"de":"Cạnh nào kề góc A và góc C?","dapAn":"AC","giaiThich":"Hai đầu mút A, C."},{"de":"Có góc A = góc D, AB = DE. Cần thêm góc nào cho g.c.g?","dapAn":"Góc B = góc E","giaiThich":"AB kề góc A và góc B."}]'::jsonb),
  ('VBH-GGG-01', 'Ba góc bằng nhau làm hai tam giác "trông giống nhau", nhưng chúng có thể to nhỏ khác nhau.', 'Không có trường hợp g.g.g. Mọi trường hợp bằng nhau của tam giác cần ít nhất một cặp cạnh tương ứng bằng nhau.', '[{"de":"Hai tam giác đều cạnh 3 cm và 5 cm có bằng nhau không?","giai":"Cách nghĩ sai: có, vì ba góc đều 60°. Cách đúng: không, vì các cạnh khác nhau."},{"de":"Hai tam giác có ba cặp góc bằng nhau và AB = DE (cạnh tương ứng). Có bằng nhau không?","giai":"Có: dùng góc A, cạnh AB, góc B (g.c.g)."}]'::jsonb, '[{"de":"Hai ê ke 30°–60° khác cỡ có bằng nhau không?","dapAn":"Không","giaiThich":"Thiếu cặp cạnh bằng nhau."},{"de":"Cần tối thiểu bao nhiêu cặp cạnh trong mọi trường hợp bằng nhau?","dapAn":"Một cặp","giaiThich":"Như g.c.g."}]'::jsonb),
  ('VBH-TGV-01', 'Với tam giác vuông, nhầm cạnh huyền với cạnh góc vuông sẽ làm chọn sai trường hợp bằng nhau.', 'Cạnh huyền là cạnh đối diện góc vuông và dài nhất. Hai cạnh còn lại (kề góc vuông) là cạnh góc vuông.', '[{"de":"Tam giác ABC vuông tại A. Cạnh huyền là cạnh nào?","giai":"Cách nghĩ sai: AB vì là cạnh đầu tiên. Cách đúng: BC, đối diện góc vuông A."},{"de":"Tam giác AHB vuông tại H. Cạnh huyền?","giai":"AB, đối diện góc H."}]'::jsonb, '[{"de":"ΔMNP vuông tại N. Cạnh huyền?","dapAn":"MP","giaiThich":"Đối diện góc N."},{"de":"Trong tam giác vuông, cạnh nào dài nhất?","dapAn":"Cạnh huyền","giaiThich":"Đối diện góc lớn nhất (90°)."}]'::jsonb),
  ('VBH-TGV-02', 'Hai tam giác vuông có cùng góc nhọn chỉ "giống dáng", chưa chắc bằng nhau.', 'Ba trường hợp đầu của tam giác vuông: hai cạnh góc vuông; cạnh góc vuông và góc nhọn kề; cạnh huyền và góc nhọn. Trường hợp nào cũng có ít nhất một cặp cạnh.', '[{"de":"Hai tam giác vuông cùng có góc 30° và 60°. Có bằng nhau không?","giai":"Cách nghĩ sai: có. Cách đúng: chưa đủ; cần thêm một cặp cạnh (ví dụ cạnh huyền bằng nhau)."},{"de":"Hai cột đèn cao bằng nhau, bóng tạo góc bằng nhau. Vì sao bóng dài bằng nhau?","giai":"Hai tam giác vuông có cạnh góc vuông bằng nhau và góc nhọn tương ứng bằng nhau, suy ra góc nhọn kề cũng bằng nhau, nên bằng nhau."}]'::jsonb, '[{"de":"Cạnh huyền và một góc nhọn bằng nhau: hai tam giác vuông có bằng nhau không?","dapAn":"Có","giaiThich":"Cạnh huyền – góc nhọn."},{"de":"Chỉ có hai góc nhọn bằng nhau: đủ chưa?","dapAn":"Chưa","giaiThich":"Cần một cặp cạnh."}]'::jsonb),
  ('VBH-TGV-03', 'Trường hợp cạnh huyền – cạnh góc vuông rất tiện, nhưng chỉ dùng được khi có góc vuông.', 'Nếu cạnh huyền và một cạnh góc vuông của tam giác vuông này bằng cạnh huyền và một cạnh góc vuông của tam giác vuông kia thì hai tam giác vuông bằng nhau. Với tam giác thường, hai cạnh và một góc không xen giữa chưa đủ.', '[{"de":"Hai tam giác thường có AB = DE, BC = EF, góc A = góc D. Kết luận được không?","giai":"Cách nghĩ sai: được theo cạnh huyền – cạnh góc vuông. Cách đúng: không có góc vuông nên không dùng được; chưa đủ điều kiện."},{"de":"AB = AC, AH ⊥ BC. Chứng minh ΔAHB = ΔAHC.","giai":"Hai tam giác vuông tại H có cạnh huyền AB = AC, cạnh góc vuông AH chung nên bằng nhau."}]'::jsonb, '[{"de":"Trường hợp cạnh huyền – cạnh góc vuông dùng cho loại tam giác nào?","dapAn":"Tam giác vuông","giaiThich":"Phải có góc vuông."},{"de":"OA = OB (bán kính), OH ⊥ AB. Vì sao HA = HB?","dapAn":"ΔOHA = ΔOHB (cạnh huyền – cạnh góc vuông)","giaiThich":"OA = OB, OH chung."}]'::jsonb),
  ('VBH-TGC-01', 'Tam giác cân có tên gọi riêng cho từng cạnh, từng góc. Nhầm tên sẽ tính sai góc.', 'Tam giác ABC cân tại A: hai cạnh bên AB = AC, cạnh đáy BC, góc ở đỉnh là góc A, hai góc ở đáy là góc B và góc C, và góc B = góc C.', '[{"de":"Tam giác ABC cân tại A. Hai góc nào bằng nhau?","giai":"Cách nghĩ sai: góc A = góc B. Cách đúng: góc B = góc C (hai góc ở đáy)."},{"de":"Tam giác MNP cân tại N. Cạnh đáy?","giai":"MP (đối diện đỉnh N)."}]'::jsonb, '[{"de":"ΔDEF cân tại E. Hai cạnh bên?","dapAn":"ED và EF","giaiThich":"Cùng xuất phát từ đỉnh E."},{"de":"ΔABC cân tại B. Hai góc ở đáy?","dapAn":"Góc A và góc C","giaiThich":"Nằm ở hai đầu cạnh đáy AC."}]'::jsonb),
  ('VBH-TGC-02', 'Lỗi hay gặp nhất khi tính góc tam giác cân là quên chia đôi phần còn lại cho hai góc ở đáy.', 'Góc ở đáy = (180° − góc ở đỉnh) : 2. Góc ở đỉnh = 180° − 2 · góc ở đáy.', '[{"de":"Tam giác cân tại A, góc A = 40°. Tính góc B.","giai":"Cách nghĩ sai: 180° − 40° = 140°. Cách đúng: (180° − 40°) : 2 = 70°."},{"de":"Tam giác cân tại M, góc N = 65°. Tính góc M.","giai":"Góc M = 180° − 2 · 65° = 50°."}]'::jsonb, '[{"de":"Góc ở đỉnh 110°. Góc ở đáy?","dapAn":"35°","giaiThich":"(180° − 110°) : 2."},{"de":"Góc ở đáy 45°. Góc ở đỉnh?","dapAn":"90°","giaiThich":"180° − 90° = 90° (tam giác vuông cân)."}]'::jsonb),
  ('VBH-TGC-03', 'Tam giác đều là trường hợp đặc biệt của tam giác cân. Một góc 60° trong tam giác cân là đủ để biết nó đều.', 'Tam giác đều có ba cạnh bằng nhau, ba góc bằng 60°. Tam giác cân có một góc 60° là tam giác đều. Tam giác đều là tam giác cân tại cả ba đỉnh.', '[{"de":"Tam giác cân tại A có góc A = 60°. Tam giác đó có đều không?","giai":"Cách nghĩ sai: chưa chắc. Cách đúng: góc B = góc C = (180° − 60°) : 2 = 60°, ba góc bằng nhau nên tam giác đều."},{"de":"Tam giác cân có góc ở đáy 60°. Có đều không?","giai":"Có: góc ở đỉnh = 180° − 120° = 60°."}]'::jsonb, '[{"de":"Tam giác đều có phải tam giác cân không?","dapAn":"Có","giaiThich":"Có hai cạnh bằng nhau."},{"de":"Mỗi góc của tam giác đều bằng bao nhiêu?","dapAn":"60°","giaiThich":"180° : 3."}]'::jsonb),
  ('VBH-TTR-01', 'Đường trung trực cần đủ hai điều kiện. Thiếu một điều kiện thì chỉ là một đường thẳng bình thường.', 'Đường trung trực của đoạn AB là đường thẳng vuông góc với AB tại trung điểm của AB. Kiểm tra cả hai: vuông góc và đi qua trung điểm.', '[{"de":"d ⊥ AB tại H, HA = 2 cm, HB = 3 cm. d có phải trung trực không?","giai":"Cách nghĩ sai: có, vì vuông góc. Cách đúng: H không phải trung điểm nên d không phải trung trực."},{"de":"Đường thẳng qua trung điểm M của AB và tạo với AB góc 70°. Có phải trung trực không?","giai":"Không, vì không vuông góc."}]'::jsonb, '[{"de":"Hai điều kiện của đường trung trực?","dapAn":"Vuông góc và đi qua trung điểm","giaiThich":"Phải đủ cả hai."},{"de":"Đoạn AB có bao nhiêu đường trung trực?","dapAn":"Một","giaiThich":"Chỉ có một đường vuông góc tại trung điểm."}]'::jsonb),
  ('VBH-TTR-02', 'Tính chất cách đều hai mút dùng được theo cả hai chiều, rất hữu ích khi chứng minh.', 'Điểm nằm trên trung trực của AB thì cách đều A và B. Ngược lại, điểm cách đều A và B thì nằm trên trung trực của AB. Hai điểm phân biệt cách đều A, B xác định đường trung trực.', '[{"de":"NA = NB, N không thuộc đoạn AB. N nằm ở đâu?","giai":"Cách nghĩ sai: N không nằm trên trung trực vì không thuộc AB. Cách đúng: N cách đều A, B nên N thuộc trung trực của AB."},{"de":"Đặt trạm M trên đường d sao cho MA = MB. M ở đâu?","giai":"M là giao điểm của d với trung trực của AB."}]'::jsonb, '[{"de":"M trên trung trực của AB, MA = 5 cm. MB?","dapAn":"5 cm","giaiThich":"Cách đều hai mút."},{"de":"Vẽ trung trực bằng compa cần bán kính thế nào?","dapAn":"Lớn hơn AB/2","giaiThich":"Để hai cung cắt nhau tại hai điểm."}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

