-- Link video: chỉ điền khi ô còn trống — link giáo viên đã tự gắn ở /gv/noi-dung được giữ nguyên.
on conflict (content_id) do update set title = excluded.title, ku_id = excluded.ku_id,
  duration_sec = case when contents.url is null or contents.url = '' then excluded.duration_sec else contents.duration_sec end,
  nguon = case when contents.url is null or contents.url = '' then excluded.nguon else contents.nguon end,
  url = case when contents.url is null or contents.url = '' then excluded.url else contents.url end;

insert into error_dictionary (error_code, ku_id, misconception, remediation_id) values
  ('E-PL-01', 'C5-B17-M1', 'Coi dữ liệu xếp loại, mức độ (Tốt, Khá, Rất thích…) là số liệu vì có thể sắp thứ tự. Ví dụ: Cho rằng "Xếp loại học lực: Tốt, Khá, Đạt" là số liệu', 'VBH-PL-01'),
  ('E-PL-02', 'C5-B17-M1', 'Không phân biệt dữ liệu không là số có thể sắp thứ tự với dữ liệu không thể sắp thứ tự. Ví dụ: Cho rằng "màu sắc yêu thích" có thể sắp thứ tự, còn "mức độ hài lòng" thì không', 'VBH-PL-02'),
  ('E-PL-03', 'C5-B17-M1', 'Chọn sai cách thu thập dữ liệu: dùng phỏng vấn, tra Internet cho dữ liệu cần quan sát, đo đạc trực tiếp và ngược lại. Ví dụ: Muốn biết chiều cao của các bạn trong lớp thì tra cứu trên Internet', 'VBH-PL-03'),
  ('E-DD-01', 'C5-B17-M2', 'Chỉ khảo sát một nhóm đặc biệt (cùng sở thích, cùng câu lạc bộ, bạn thân) rồi kết luận cho cả tập thể. Ví dụ: Hỏi các bạn trong câu lạc bộ bóng đá rồi kết luận "học sinh cả trường đều thích bóng đá"', 'VBH-DD-01'),
  ('E-DD-02', 'C5-B17-M2', 'Rút ra kết luận chung từ một mẫu quá ít đối tượng. Ví dụ: Hỏi 3 bạn rồi kết luận về sở thích của 500 học sinh', 'VBH-DD-02'),
  ('E-DD-03', 'C5-B17-M2', 'Không kiểm tra tính hợp lí của dữ liệu: chấp nhận số liệu vô lí hoặc tỉ lệ có tổng vượt 100%. Ví dụ: Chấp nhận bảng ghi "chiều cao 1 600 cm" hoặc các tỉ lệ cộng lại thành 115%', 'VBH-DD-03'),
  ('E-HQ-01', 'C5-B18-M1', 'Không nắm cả hình tròn biểu diễn 100%: tính sai phần còn lại hoặc chấp nhận các phần có tổng khác 100%. Ví dụ: Biểu đồ có các phần 40%, 25%, 20% và một phần chưa ghi; em cho rằng phần đó là 25%', 'VBH-HQ-01'),
  ('E-HQ-02', 'C5-B18-M1', 'Đọc tỉ lệ phần trăm như số lượng đối tượng. Ví dụ: Thấy phần "Đọc sách" chiếm 25% liền nói "có 25 bạn thích đọc sách"', 'VBH-HQ-02'),
  ('E-BDQ-01', 'C5-B18-M2', 'Tính tỉ lệ phần trăm sai: chia cho số lớn nhất hoặc cho một nhóm thay vì chia cho tổng số. Ví dụ: Lớp có 40 HS, 10 HS thích bóng rổ, 16 HS thích bóng đá; tính tỉ lệ bóng rổ là 10 : 16 · 100%', 'VBH-BDQ-01'),
  ('E-BDQ-02', 'C5-B18-M2', 'Điền tỉ lệ vào hình quạt không tương xứng với độ lớn của phần. Ví dụ: Ghi 60% vào hình quạt nhỏ nhất và 15% vào hình quạt lớn nhất', 'VBH-BDQ-02'),
  ('E-BDQ-03', 'C5-B18-M2', 'Dùng biểu đồ hình quạt tròn cho dữ liệu không phải là các phần của cùng một tổng thể (dữ liệu thay đổi theo thời gian). Ví dụ: Dùng biểu đồ hình quạt tròn để biểu diễn nhiệt độ trung bình các tháng trong năm', 'VBH-BDQ-03'),
  ('E-PTQ-01', 'C5-B18-M3', 'Tính số lượng từ tỉ lệ phần trăm sai: quên chia 100 hoặc nhân với sai tổng số. Ví dụ: Trường có 800 HS, 15% đi xe đạp; tính được 800 · 15 = 12 000 bạn', 'VBH-PTQ-01'),
  ('E-PTQ-02', 'C5-B18-M3', 'So sánh số lượng giữa hai biểu đồ hình quạt của hai tổng thể khác nhau chỉ dựa vào tỉ lệ phần trăm. Ví dụ: Lớp A (30 HS) có 40% thích Toán, lớp B (50 HS) có 30% thích Toán; kết luận lớp A có nhiều bạn thích Toán hơn', 'VBH-PTQ-02'),
  ('E-DT-01', 'C5-B19-M1', 'Đọc sai giá trị: đọc trên trục ngang thay vì trục đứng, hoặc bỏ qua đơn vị ghi trên trục đứng. Ví dụ: Trục đứng ghi "đơn vị: triệu người", điểm ở mức 96 nhưng em đọc là 96 người', 'VBH-DT-01'),
  ('E-DT-02', 'C5-B19-M2', 'Nhận định xu thế theo độ cao của điểm thay vì theo chiều đi lên, đi xuống của đoạn thẳng. Ví dụ: Đoạn thẳng đi xuống từ 120 về 90 nhưng em nói "giai đoạn này tăng vì giá trị vẫn cao"', 'VBH-DT-02'),
  ('E-DT-03', 'C5-B19-M2', 'Xác định giai đoạn tăng (giảm) nhiều nhất sai: chọn giai đoạn có giá trị lớn nhất thay vì có hiệu lớn nhất. Ví dụ: Các năm 2016–2019 lần lượt 50, 70, 75, 78: em chọn 2018–2019 vì giá trị 78 lớn nhất', 'VBH-DT-03'),
  ('E-VDT-01', 'C5-B19-M3', 'Chia vạch trên trục không đều hoặc đặt các mốc thời gian không theo thứ tự. Ví dụ: Trên trục đứng, khoảng từ 0 đến 10 dài bằng khoảng từ 10 đến 50', 'VBH-VDT-01'),
  ('E-VDT-02', 'C5-B19-M3', 'Vẽ điểm sai vị trí hoặc nối các điểm không theo thứ tự thời gian. Ví dụ: Nối điểm của năm 2019 với năm 2017 rồi mới nối với năm 2018', 'VBH-VDT-02')
on conflict (error_code) do update set ku_id = excluded.ku_id, misconception = excluded.misconception,
  remediation_id = excluded.remediation_id;

insert into questions (question_id, ku_id, level, stem, correct_option, expected_time_sec, hinh) values
  ('C5-B17-M1-Q01', 'C5-B17-M1', 1, 'Dữ liệu nào sau đây là số liệu?', 'A', 45, null),
  ('C5-B17-M1-Q02', 'C5-B17-M1', 1, 'Dữ liệu "Màu áo yêu thích của các bạn lớp 7A: xanh, đỏ, trắng, vàng" thuộc loại nào?', 'A', 45, null),
  ('C5-B17-M1-Q03', 'C5-B17-M1', 2, 'Dữ liệu nào sau đây là dữ liệu không là số và CÓ THỂ sắp thứ tự?', 'A', 60, null),
  ('C5-B17-M1-Q04', 'C5-B17-M1', 2, 'Để biết chiều cao hiện nay của các bạn trong lớp 7A, cách thu thập dữ liệu phù hợp nhất là:', 'A', 60, null),
  ('C5-B17-M1-Q05', 'C5-B17-M1', 3, 'Một phiếu hỏi có 3 câu: (1) Em cao bao nhiêu cm? (2) Em thích môn thể thao nào? (3) Em đánh giá giờ ra chơi: Rất vui, Vui, Bình thường? Khẳng định nào ĐÚNG?', 'A', 90, null),
  ('C5-B17-M1-Q06', 'C5-B17-M1', 3, 'Muốn biết dân số Việt Nam qua các năm 1979, 1989, 1999, 2009, 2019, em nên thu thập dữ liệu bằng cách nào?', 'A', 90, null),
  ('C5-B17-M1-Q07', 'C5-B17-M1', 4, 'Bạn An nói: "Dữ liệu xếp loại học lực Tốt, Khá, Đạt, Chưa đạt sắp xếp được từ cao đến thấp, nên đó là số liệu". Nhận xét nào ĐÚNG?', 'A', 120, null),
  ('C5-B17-M1-Q08', 'C5-B17-M1', 4, 'Lớp trưởng muốn tìm hiểu thời gian (phút) các bạn đọc sách mỗi ngày và lí do các bạn không đọc sách. Phương án nào hợp lí nhất?', 'A', 120, null),
  ('C5-B17-M2-Q01', 'C5-B17-M2', 1, 'Để tìm hiểu món ăn sáng yêu thích của học sinh khối 7, cách chọn mẫu nào ĐẠI DIỆN hơn cả?', 'A', 45, null),
  ('C5-B17-M2-Q02', 'C5-B17-M2', 1, 'Bảng thống kê tỉ lệ học sinh chọn các môn thể thao ghi: Bóng đá 45%, Cầu lông 35%, Bơi lội 35%. Nhận xét nào ĐÚNG?', 'A', 45, null),
  ('C5-B17-M2-Q03', 'C5-B17-M2', 2, 'Để biết học sinh cả trường có thích môn Toán không, bạn Minh chỉ hỏi các bạn trong đội tuyển Toán. Kết luận từ cuộc khảo sát này:', 'A', 60, null),
  ('C5-B17-M2-Q04', 'C5-B17-M2', 2, 'Trường có 600 học sinh. Bạn Lan hỏi 4 bạn thì cả 4 bạn đều thích bơi, rồi kết luận "học sinh trường em đều thích bơi". Kết luận này:', 'A', 60, null),
  ('C5-B17-M2-Q05', 'C5-B17-M2', 3, 'Bảng ghi chiều cao (cm) của 5 bạn: 148; 152; 1 550; 147; 150. Em nhận xét gì?', 'A', 90, null),
  ('C5-B17-M2-Q06', 'C5-B17-M2', 3, 'Để tìm hiểu thời gian dùng Internet của học sinh trường, cách nào cho dữ liệu ĐẠI DIỆN nhất?', 'A', 90, null),
  ('C5-B17-M2-Q07', 'C5-B17-M2', 4, 'Một hãng sữa hỏi 20 khách hàng đang mua sữa của hãng tại cửa hàng và quảng cáo: "95% người dân thích sữa của chúng tôi". Lí do chính khiến quảng cáo KHÔNG đáng tin là gì?', 'A', 120, null),
  ('C5-B17-M2-Q08', 'C5-B17-M2', 4, 'Lớp 7B có 40 bạn (20 nam, 20 nữ). Để biết môn thể thao yêu thích của lớp, bạn Hùng hỏi 10 bạn nam ngồi bàn cuối. Cách sửa hợp lí nhất là:', 'A', 120, null),
  ('C5-B18-M1-Q01', 'C5-B18-M1', 1, 'Trong biểu đồ hình quạt tròn, cả hình tròn biểu diễn:', 'A', 45, null),
  ('C5-B18-M1-Q02', 'C5-B18-M1', 1, 'Theo biểu đồ, hoạt động nào được học sinh lớp 7A yêu thích nhiều nhất?', 'A', 45, '{"loai":"quat","tieuDe":"Hoạt động giải trí yêu thích của học sinh lớp 7A (40 HS)","duLieu":[["Thể thao",40],["Đọc sách",25],["Xem phim",20],["Chơi nhạc cụ",15]]}'::jsonb),
  ('C5-B18-M1-Q03', 'C5-B18-M1', 2, 'Một biểu đồ hình quạt tròn có bốn phần: 35%, 25%, 15% và một phần chưa ghi số. Phần chưa ghi số chiếm bao nhiêu phần trăm?', 'A', 60, null),
  ('C5-B18-M1-Q04', 'C5-B18-M1', 2, 'Biểu đồ cho biết hoạt động giải trí yêu thích của 40 học sinh lớp 7A. Câu nào ĐÚNG?', 'A', 60, '{"loai":"quat","tieuDe":"Hoạt động giải trí yêu thích của học sinh lớp 7A (40 HS)","duLieu":[["Thể thao",40],["Đọc sách",25],["Xem phim",20],["Chơi nhạc cụ",15]]}'::jsonb),
  ('C5-B18-M1-Q05', 'C5-B18-M1', 3, 'Lập bảng thống kê từ biểu đồ hình quạt tròn về phương tiện đến trường của 800 học sinh. Hàng tỉ lệ phần trăm ĐÚNG là:', 'A', 90, '{"loai":"quat","tieuDe":"Phương tiện đến trường của 800 học sinh","duLieu":[["Xe đạp",45],["Bố mẹ đưa đón",30],["Đi bộ",15],["Xe buýt",10]]}'::jsonb),
  ('C5-B18-M1-Q06', 'C5-B18-M1', 3, 'Bạn Nam vẽ biểu đồ hình quạt tròn với các phần ghi 50%, 30%, 25%. Nhận xét nào ĐÚNG?', 'A', 90, null),
  ('C5-B18-M1-Q07', 'C5-B18-M1', 4, 'Trong biểu đồ phương tiện đến trường, hai nhóm "Đi bộ" và "Xe buýt" cộng lại chiếm bao nhiêu phần so với nhóm "Xe đạp"?', 'A', 120, '{"loai":"quat","tieuDe":"Phương tiện đến trường của 800 học sinh","duLieu":[["Xe đạp",45],["Bố mẹ đưa đón",30],["Đi bộ",15],["Xe buýt",10]]}'::jsonb),
  ('C5-B18-M1-Q08', 'C5-B18-M1', 4, 'Một hình quạt chiếm đúng một nửa hình tròn, hình quạt khác chiếm một phần tư hình tròn, phần còn lại được chia đều cho hai nhóm. Mỗi nhóm đó chiếm:', 'A', 120, null),
  ('C5-B18-M2-Q01', 'C5-B18-M2', 1, 'Lớp 7A có 40 học sinh, trong đó 10 bạn thích bóng rổ. Tỉ lệ phần trăm số bạn thích bóng rổ là:', 'A', 45, null),
  ('C5-B18-M2-Q02', 'C5-B18-M2', 1, 'Biểu đồ hình quạt tròn thích hợp nhất để biểu diễn dữ liệu nào sau đây?', 'A', 45, null),
  ('C5-B18-M2-Q03', 'C5-B18-M2', 2, 'Một cửa hàng bán được 200 chiếc áo: 90 áo trắng, 60 áo xanh, 50 áo đen. Tỉ lệ phần trăm áo xanh là:', 'A', 60, null),
  ('C5-B18-M2-Q04', 'C5-B18-M2', 2, 'Biểu đồ hình quạt tròn cho sẵn có bốn hình quạt với kích thước từ lớn đến nhỏ. Cần điền các tỉ lệ 15%, 40%, 35%, 10%. Cách điền ĐÚNG là:', 'A', 60, null),
  ('C5-B18-M2-Q05', 'C5-B18-M2', 3, 'Đội tuyển lớp 7 có 25 bạn: 7A có 5 bạn, 7B có 8 bạn, 7C có 7 bạn, 7D có 5 bạn. Tỉ lệ phần trăm của các lớp lần lượt là:', 'A', 90, null),
  ('C5-B18-M2-Q06', 'C5-B18-M2', 3, 'Bạn Mai muốn biểu diễn số học sinh đạt điểm giỏi của lớp qua 5 lần kiểm tra để thấy sự thay đổi. Mai nên chọn:', 'A', 90, null),
  ('C5-B18-M2-Q07', 'C5-B18-M2', 4, 'Lớp 7C có 36 học sinh: 18 bạn đi xe đạp, 9 bạn đi bộ, còn lại được đưa đón. Khi điền vào biểu đồ hình quạt tròn, hình quạt "Được đưa đón" chiếm:', 'A', 120, null),
  ('C5-B18-M2-Q08', 'C5-B18-M2', 4, 'Khảo sát 50 bạn về loại quả yêu thích: Xoài 20 bạn, Cam 15 bạn, Chuối 10 bạn, còn lại thích Táo. Bộ tỉ lệ phần trăm điền vào biểu đồ ĐÚNG là:', 'A', 120, null),
  ('C5-B18-M3-Q01', 'C5-B18-M3', 1, 'Theo biểu đồ phương tiện đến trường của 800 học sinh, số học sinh đi xe buýt là:', 'A', 45, '{"loai":"quat","tieuDe":"Phương tiện đến trường của 800 học sinh","duLieu":[["Xe đạp",45],["Bố mẹ đưa đón",30],["Đi bộ",15],["Xe buýt",10]]}'::jsonb),
  ('C5-B18-M3-Q02', 'C5-B18-M3', 1, 'Lớp 7A có 40 học sinh, 20% thích xem phim. Số bạn thích xem phim là:', 'A', 45, null),
  ('C5-B18-M3-Q03', 'C5-B18-M3', 2, 'Theo biểu đồ phương tiện đến trường, số học sinh đi xe đạp nhiều hơn số học sinh đi bộ là bao nhiêu bạn?', 'A', 60, '{"loai":"quat","tieuDe":"Phương tiện đến trường của 800 học sinh","duLieu":[["Xe đạp",45],["Bố mẹ đưa đón",30],["Đi bộ",15],["Xe buýt",10]]}'::jsonb),
  ('C5-B18-M3-Q04', 'C5-B18-M3', 2, 'Lớp 7A có 30 học sinh, 40% thích Toán. Lớp 7B có 50 học sinh, 30% thích Toán. Lớp nào có nhiều bạn thích Toán hơn?', 'A', 60, null),
  ('C5-B18-M3-Q05', 'C5-B18-M3', 3, 'Một trường có 1 200 học sinh. Biểu đồ hình quạt tròn cho biết 35% học sinh tham gia câu lạc bộ thể thao, 25% tham gia câu lạc bộ nghệ thuật, còn lại không tham gia. Số học sinh không tham gia câu lạc bộ nào là:', 'A', 90, null),
  ('C5-B18-M3-Q06', 'C5-B18-M3', 3, 'Theo biểu đồ hoạt động giải trí của lớp 7A (40 HS), nhận xét nào ĐÚNG?', 'A', 90, '{"loai":"quat","tieuDe":"Hoạt động giải trí yêu thích của học sinh lớp 7A (40 HS)","duLieu":[["Thể thao",40],["Đọc sách",25],["Xem phim",20],["Chơi nhạc cụ",15]]}'::jsonb),
  ('C5-B18-M3-Q07', 'C5-B18-M3', 4, 'Năm ngoái trường có 600 học sinh, 30% đi xe đạp. Năm nay trường có 800 học sinh, 25% đi xe đạp. Bạn Hà nói "số bạn đi xe đạp năm nay giảm". Nhận xét nào ĐÚNG?', 'A', 120, null),
  ('C5-B18-M3-Q08', 'C5-B18-M3', 4, 'Biểu đồ hình quạt tròn cho biết 15% học sinh một trường đi bộ đến trường, tương ứng với 120 bạn. Trường có tất cả bao nhiêu học sinh?', 'A', 120, null),
  ('C5-B19-M1-Q01', 'C5-B19-M1', 1, 'Trong biểu đồ đoạn thẳng, trục nằm ngang thường biểu diễn:', 'A', 45, null),
  ('C5-B19-M1-Q02', 'C5-B19-M1', 1, 'Theo biểu đồ sản lượng lúa, năm 2020 xã thu hoạch được bao nhiêu?', 'A', 45, '{"loai":"doan-thang","tieuDe":"Sản lượng lúa của một xã (đơn vị: nghìn tấn)","trucX":"Năm","trucY":"Nghìn tấn","duLieu":[["2018",12],["2019",15],["2020",14],["2021",18],["2022",19]]}'::jsonb),
