  ('C5-B19-M1-Q04', 'C5-B19-M1', 2, 'Biểu đồ đoạn thẳng có trục đứng ghi "Dân số (triệu người)". Điểm ứng với năm 2019 nằm ở vạch 96,2. Dân số năm 2019 là:', 'A', 60, null),
  ('C5-B19-M1-Q05', 'C5-B19-M1', 3, 'Theo biểu đồ sản lượng lúa, năm nào xã có sản lượng cao nhất và bằng bao nhiêu?', 'A', 90, '{"loai":"doan-thang","tieuDe":"Sản lượng lúa của một xã (đơn vị: nghìn tấn)","trucX":"Năm","trucY":"Nghìn tấn","duLieu":[["2018",12],["2019",15],["2020",14],["2021",18],["2022",19]]}'::jsonb),
  ('C5-B19-M1-Q06', 'C5-B19-M1', 3, 'Một biểu đồ đoạn thẳng có các thành phần: hai trục, các điểm được nối bởi đoạn thẳng, tiêu đề. Mỗi điểm trên biểu đồ cho biết:', 'A', 90, null),
  ('C5-B19-M1-Q07', 'C5-B19-M1', 4, 'Lập bảng thống kê từ biểu đồ nhiệt độ ngày 15/7 tại Đà Nẵng. Bảng ĐÚNG là:', 'A', 120, '{"loai":"doan-thang","tieuDe":"Nhiệt độ ngày 15/7 tại Đà Nẵng (°C)","trucX":"Giờ","trucY":"°C","duLieu":[["7 giờ",27],["10 giờ",31],["13 giờ",35],["16 giờ",33],["19 giờ",29]]}'::jsonb),
  ('C5-B19-M1-Q08', 'C5-B19-M1', 4, 'Trục đứng của một biểu đồ đoạn thẳng ghi "đơn vị: nghìn lượt khách". Điểm của tháng 6 nằm giữa vạch 40 và vạch 50, đúng ở chính giữa. Số khách tháng 6 khoảng:', 'A', 120, null),
  ('C5-B19-M2-Q01', 'C5-B19-M2', 1, 'Theo biểu đồ sản lượng lúa, từ năm 2019 đến năm 2020 sản lượng:', 'A', 45, '{"loai":"doan-thang","tieuDe":"Sản lượng lúa của một xã (đơn vị: nghìn tấn)","trucX":"Năm","trucY":"Nghìn tấn","duLieu":[["2018",12],["2019",15],["2020",14],["2021",18],["2022",19]]}'::jsonb),
