  ('C5-B19-M2-Q03', 'C5-B19-M2', 2, 'Theo biểu đồ sản lượng lúa, sản lượng tăng nhiều nhất trong giai đoạn nào?', 'A', 60, '{"loai":"doan-thang","tieuDe":"Sản lượng lúa của một xã (đơn vị: nghìn tấn)","trucX":"Năm","trucY":"Nghìn tấn","duLieu":[["2018",12],["2019",15],["2020",14],["2021",18],["2022",19]]}'::jsonb),
