  ('C5-B19-M2-Q05', 'C5-B19-M2', 3, 'Số học sinh đeo kính của một trường qua các năm 2020, 2021, 2022, 2023 lần lượt là 80, 95, 120, 130. Giai đoạn tăng nhiều nhất là:', 'A', 90, null),
  ('C5-B19-M2-Q06', 'C5-B19-M2', 3, 'Biểu đồ có hai đường: máy tính để bàn và máy tính xách tay bán được trong 6 tháng. Đường máy tính xách tay luôn đi lên, đường máy tính để bàn luôn đi xuống, hai đường cắt nhau ở tháng 4. Nhận xét nào ĐÚNG?', 'A', 90, null),
