  ('C5-B19-M3-Q02', 'C5-B19-M3', 1, 'Trên trục đứng, bạn Nam ghi các vạch 0; 5; 10; 20; 40 cách đều nhau. Cách chia này:', 'A', 45, null),
  ('C5-B19-M3-Q03', 'C5-B19-M3', 2, 'Chiều cao cây đậu (cm) trong 5 ngày: ngày 1: 0,5; ngày 2: 0,75; ngày 3: 1; ngày 4: 1,4; ngày 5: 2,5. Khi vẽ điểm ngày 4, ta đặt điểm:', 'A', 60, null),
  ('C5-B19-M3-Q04', 'C5-B19-M3', 2, 'Sau khi vẽ xong các điểm của năm 2017, 2018, 2019, 2020, ta nối các điểm theo thứ tự:', 'A', 60, null),
  ('C5-B19-M3-Q05', 'C5-B19-M3', 3, 'Số trận thắng của một đội bóng các năm 2016–2020: 36, 42, 15, 23, 25. Để vẽ biểu đồ, cách chia trục đứng hợp lí nhất là:', 'A', 90, null),
  ('C5-B19-M3-Q06', 'C5-B19-M3', 3, 'Bạn Lan vẽ trục ngang ghi các năm theo thứ tự 2019; 2017; 2020; 2018 để "điểm đẹp hơn". Nhận xét nào ĐÚNG?', 'A', 90, null),
  ('C5-B19-M3-Q07', 'C5-B19-M3', 4, 'Thời gian chạy 1 500 m (phút) của bạn Hà trong 7 tuần: 8; 8; 8; 7; 6,5; 6,5; 6. Biểu đồ đoạn thẳng vẽ ĐÚNG sẽ có hình dạng:', 'A', 120, null),
  ('C5-B19-M3-Q08', 'C5-B19-M3', 4, 'Nhiệt độ ở Hà Nội một ngày: 8 giờ 23 °C; 10 giờ 25 °C; 12 giờ 34 °C; 14 giờ 32 °C; 16 giờ 26 °C. Một bạn chia trục ngang các vạch 8, 10, 12, 14, 16 cách đều nhau và trục đứng các vạch 0, 5, 10, …, 35 cách đều nhau. Cách vẽ này:', 'A', 120, null),
  ('C5-LTC-Q01', 'C5-LTC', 1, 'Để biểu diễn sự thay đổi số dân của một thành phố qua 10 năm, nên dùng:', 'A', 45, null),
  ('C5-LTC-Q02', 'C5-LTC', 1, 'Phiếu hỏi: "Em có yêu thích bóng đá không? A. Rất thích B. Thích C. Không thích". Dữ liệu thu được là:', 'A', 45, null),
  ('C5-LTC-Q03', 'C5-LTC', 2, '30 bạn trả lời phiếu: 60% Rất thích, 30% Thích, 10% Không thích bóng đá. Số bạn chọn "Thích" là:', 'A', 60, null),
  ('C5-LTC-Q04', 'C5-LTC', 2, 'Chỉ khảo sát 30 bạn trong câu lạc bộ bóng đá rồi kết luận "đa số học sinh trường em rất thích bóng đá". Kết luận này:', 'A', 60, null),
  ('C5-LTC-Q05', 'C5-LTC', 3, 'Tỉ lệ tăng dân số Việt Nam (%) các năm 1991, 1995, 1999, 2003, 2007 lần lượt là 1,86; 1,65; 1,51; 1,17; 1,09. Nhận xét nào ĐÚNG?', 'A', 90, null),
  ('C5-LTC-Q06', 'C5-LTC', 3, 'Một bạn vẽ biểu đồ hình quạt tròn biểu diễn nhiệt độ trung bình 4 quý trong năm: 20 °C, 28 °C, 30 °C, 22 °C. Nhận xét nào ĐÚNG?', 'A', 90, null),
  ('C5-LTC-Q07', 'C5-LTC', 4, 'GDP Việt Nam (nghìn tỉ đồng) năm 2016 là 205,3 và năm 2019 là 261. Trong năm 2019, khu vực dịch vụ chiếm 50% GDP. Giá trị khu vực dịch vụ năm 2019 khoảng:', 'A', 120, null),
  ('C5-LTC-Q08', 'C5-LTC', 4, 'Trong 4 tuần, số bạn lớp 7A (40 HS) nộp bài chuẩn bị đúng hạn là 22, 26, 33, 36. Tuần 4 tỉ lệ nộp đúng hạn là bao nhiêu và tuần nào tăng nhiều nhất?', 'A', 120, null)
