insert into error_hints (error_code, tier, hint_text) values
  ('E-PL-01', 1, 'Dữ liệu này được ghi bằng con số hay bằng chữ?'),
  ('E-PL-01', 2, 'Số liệu là dữ liệu được biểu diễn bằng con số (cân nặng, chiều cao, số anh chị em…). Dữ liệu ghi bằng chữ như Tốt, Khá, Rất thích là dữ liệu không là số, kể cả khi sắp được thứ tự.'),
  ('E-PL-01', 3, 'Ví dụ: "48 kg" là số liệu; "Khá" là dữ liệu không là số (có thể sắp thứ tự). Em xét lại từng dữ liệu xem có phải là con số không.'),
  ('E-PL-02', 1, 'Các giá trị của dữ liệu này có thể xếp từ thấp đến cao (hoặc từ ít đến nhiều) không?'),
  ('E-PL-02', 2, 'Dữ liệu không là số chia làm hai loại: có thể sắp thứ tự (mức độ, xếp loại) và không thể sắp thứ tự (màu sắc, tên, nơi sinh, môn học).'),
  ('E-PL-02', 3, 'Ví dụ: "Rất thích – Thích – Không thích" sắp được từ cao đến thấp; còn "đỏ, xanh, vàng" không có màu nào "cao hơn" màu nào. Em thử xếp thứ tự để kiểm tra.'),
  ('E-PL-03', 1, 'Dữ liệu em cần đã có sẵn ở đâu đó, hay em phải tự đo, tự hỏi mới biết?'),
  ('E-PL-03', 2, 'Dữ liệu về chính các bạn (chiều cao, sở thích) phải thu thập trực tiếp: đo, quan sát, phỏng vấn, phiếu hỏi. Dữ liệu chung của cả nước, các năm trước thì tra cứu sách báo, Internet.'),
  ('E-PL-03', 3, 'Ví dụ: chiều cao của lớp em → dùng thước đo; dân số Việt Nam năm 2019 → tra Tổng cục Thống kê. Em chọn lại cách thu thập phù hợp.'),
  ('E-DD-01', 1, 'Nhóm người được hỏi có giống với toàn bộ tập thể không, hay là một nhóm đặc biệt?'),
  ('E-DD-01', 2, 'Mẫu khảo sát đại diện phải gồm đủ các kiểu đối tượng của tập thể (nhiều lớp, cả nam và nữ…). Chỉ hỏi một nhóm cùng sở thích sẽ cho kết luận lệch.'),
  ('E-DD-01', 3, 'Ví dụ: hỏi CLB bóng đá về sở thích bóng đá thì gần như ai cũng thích. Em chọn mỗi lớp vài bạn ngẫu nhiên để kết quả đại diện hơn.'),
  ('E-DD-02', 1, 'Số người được hỏi có đủ nhiều so với tập thể cần kết luận không?'),
  ('E-DD-02', 2, 'Kết luận cho một tập thể lớn cần hỏi đủ nhiều đối tượng; hỏi quá ít thì kết quả có thể chỉ là ngẫu nhiên.'),
  ('E-DD-02', 3, 'Ví dụ: hỏi 4 bạn thấy cả 4 thích bơi chưa nói được gì về 600 bạn. Em đề xuất hỏi thêm nhiều bạn ở nhiều lớp.'),
  ('E-DD-03', 1, 'Các con số này có phù hợp với thực tế không? Các tỉ lệ cộng lại được bao nhiêu?'),
  ('E-DD-03', 2, 'Trước khi dùng dữ liệu cần kiểm tra tính hợp lí: giá trị phải phù hợp thực tế, các tỉ lệ của một tổng thể cộng lại phải bằng 100%.'),
  ('E-DD-03', 3, 'Ví dụ: chiều cao 1 550 cm là vô lí (có thể ghi nhầm 155 cm); 45% + 35% + 35% = 115% là sai. Em rà lại từng số.'),
  ('E-HQ-01', 1, 'Cả hình tròn ứng với bao nhiêu phần trăm?'),
  ('E-HQ-01', 2, 'Trong biểu đồ hình quạt tròn, cả hình tròn là 100%. Phần còn lại = 100% trừ tổng các phần đã biết.'),
  ('E-HQ-01', 3, 'Ví dụ: các phần đã biết 35% + 25% + 15% = 75%, nên phần còn lại là 100% − 75% = 25%. Em cộng lại để kiểm tra tổng bằng 100%.'),
  ('E-HQ-02', 1, 'Số ghi trên hình quạt là số người hay là phần trăm?'),
  ('E-HQ-02', 2, 'Tỉ lệ phần trăm cho biết phần đó chiếm bao nhiêu phần của tổng, không phải số lượng. Muốn biết số lượng phải nhân với tổng số.'),
  ('E-HQ-02', 3, 'Ví dụ: 25% của 40 bạn là 40 · 25 : 100 = 10 bạn, không phải 25 bạn. Em tìm tổng số rồi tính lại.'),
  ('E-BDQ-01', 1, 'Em đã chia cho tổng số đối tượng hay chia cho một nhóm?'),
  ('E-BDQ-01', 2, 'Tỉ lệ phần trăm của một nhóm = số đối tượng của nhóm : tổng số đối tượng · 100%.'),
  ('E-BDQ-01', 3, 'Ví dụ: 10 bạn trên tổng 40 bạn → 10 : 40 · 100% = 25%. Em kiểm tra: tổng các tỉ lệ phải bằng 100%.'),
  ('E-BDQ-02', 1, 'Tỉ lệ nào lớn nhất? Hình quạt nào lớn nhất?'),
  ('E-BDQ-02', 2, 'Hình quạt càng lớn thì tỉ lệ phần trăm càng lớn. Ghép tỉ lệ lớn nhất với hình quạt lớn nhất, nhỏ nhất với nhỏ nhất.'),
  ('E-BDQ-02', 3, 'Ví dụ: 50% là nửa hình tròn, 25% là một phần tư. Em sắp các tỉ lệ từ lớn đến nhỏ rồi điền theo kích thước hình quạt.'),
  ('E-BDQ-03', 1, 'Dữ liệu này là các phần của một tổng thể, hay là giá trị thay đổi theo thời gian?'),
  ('E-BDQ-03', 2, 'Biểu đồ hình quạt tròn dùng để so sánh các phần trong một tổng thể (cộng lại thành 100%). Dữ liệu thay đổi theo thời gian dùng biểu đồ đoạn thẳng.'),
  ('E-BDQ-03', 3, 'Ví dụ: tỉ lệ các loại sách trong thư viện → hình quạt; nhiệt độ các tháng → đoạn thẳng. Em hỏi: các giá trị có cộng lại thành "một tổng" có ý nghĩa không?'),
  ('E-PTQ-01', 1, 'Muốn tính a% của một số em làm thế nào?'),
  ('E-PTQ-01', 2, 'Số đối tượng = tổng số · tỉ lệ phần trăm : 100. Nhớ chia cho 100.'),
  ('E-PTQ-01', 3, 'Ví dụ: 15% của 800 học sinh = 800 · 15 : 100 = 120 học sinh. Em ước lượng lại: 10% của 800 là 80, nên 15% phải khoảng 120.'),
  ('E-PTQ-02', 1, 'Hai biểu đồ có cùng tổng số đối tượng không?'),
  ('E-PTQ-02', 2, 'Khi hai tổng thể có tổng số khác nhau, tỉ lệ phần trăm lớn hơn chưa chắc số lượng nhiều hơn. Phải đổi ra số lượng rồi mới so sánh.'),
  ('E-PTQ-02', 3, 'Ví dụ: 40% của 30 bạn = 12 bạn; 30% của 50 bạn = 15 bạn. Lớp có tỉ lệ nhỏ hơn lại có nhiều bạn hơn. Em tính số lượng cho từng lớp.'),
  ('E-DT-01', 1, 'Giá trị của đại lượng đọc trên trục nào? Trục đó ghi đơn vị gì?'),
  ('E-DT-01', 2, 'Trên biểu đồ đoạn thẳng, trục ngang là thời gian, trục đứng là giá trị. Đọc giá trị theo vạch ngang với điểm và nhớ ghi kèm đơn vị trên trục đứng (nghìn, triệu…).'),
  ('E-DT-01', 3, 'Ví dụ: trục đứng ghi "triệu người", điểm ở vạch 96,2 → 96,2 triệu người. Em đọc lại kèm đơn vị.'),
  ('E-DT-02', 1, 'Đoạn thẳng đi lên hay đi xuống khi đi từ trái sang phải?'),
  ('E-DT-02', 2, 'Đoạn thẳng đi lên là đại lượng tăng, đi xuống là giảm, nằm ngang là không đổi, dù giá trị đang cao hay thấp.'),
  ('E-DT-02', 3, 'Ví dụ: từ 15 xuống 14 là giảm, dù 14 vẫn lớn. Em so sánh giá trị sau với giá trị trước để kết luận.'),
  ('E-DT-03', 1, 'Tăng nhiều nhất là giai đoạn có giá trị cao nhất, hay có hiệu lớn nhất?'),
  ('E-DT-03', 2, 'Mức tăng của một giai đoạn = giá trị sau − giá trị trước. Giai đoạn tăng nhiều nhất là giai đoạn có hiệu lớn nhất (đoạn thẳng dốc nhất).'),
  ('E-DT-03', 3, 'Ví dụ: 50, 70, 75, 78 → các mức tăng 20, 5, 3, nên tăng nhiều nhất là giai đoạn đầu. Em tính hiệu từng giai đoạn.'),
  ('E-VDT-01', 1, 'Các vạch cách đều nhau có ứng với các giá trị cách đều nhau không?'),
  ('E-VDT-01', 2, 'Trên mỗi trục, các khoảng bằng nhau phải ứng với cùng một mức chênh lệch giá trị (0, 10, 20, 30…). Các mốc thời gian xếp theo thứ tự tăng dần.'),
  ('E-VDT-01', 3, 'Ví dụ: chia 0; 5; 10; 20; 40 cách đều là sai vì 5 − 0 ≠ 40 − 20. Em chọn một bước chia cố định rồi chia lại.'),
  ('E-VDT-02', 1, 'Mỗi điểm cần đặt thẳng trên mốc thời gian nào và ngang vạch giá trị nào?'),
  ('E-VDT-02', 2, 'Mỗi điểm nằm thẳng trên mốc thời gian và ngang với giá trị của đại lượng. Nối các điểm liên tiếp theo thứ tự thời gian từ trái sang phải.'),
  ('E-VDT-02', 3, 'Ví dụ: ngày 4 cây cao 1,4 cm → điểm ở trên mốc "ngày 4", ngang vạch 1,4. Em kiểm tra từng điểm rồi nối lần lượt.')
on conflict (error_code, tier) do update set hint_text = excluded.hint_text;

insert into micro_lessons (content_id, dan, quy_tac, vi_du, tu_lam) values
  ('VBH-PL-01', 'Nhiều bạn nghĩ cứ dữ liệu nào xếp được từ cao đến thấp (Tốt, Khá, Đạt) là số liệu. Thật ra số liệu chỉ là những dữ liệu được ghi bằng con số.', 'Số liệu là dữ liệu biểu diễn bằng số (cân nặng, chiều cao, số người…). Dữ liệu ghi bằng chữ là dữ liệu không là số; trong đó có loại sắp được thứ tự (xếp loại, mức độ) và loại không sắp được thứ tự (màu, tên, nơi sinh).', '[{"de":"Dữ liệu \"Xếp loại học lực: Tốt, Khá, Đạt, Chưa đạt\" thuộc loại nào?","giai":"Cách nghĩ sai: xếp được từ cao đến thấp nên là số liệu. Cách đúng: các giá trị ghi bằng chữ, không phải con số, nên là dữ liệu không là số, có thể sắp thứ tự."},{"de":"Dữ liệu \"Số giờ ngủ mỗi đêm: 7; 8; 6,5; 9\" thuộc loại nào?","giai":"Các giá trị là con số nên đây là số liệu."}]'::jsonb, '[{"de":"\"Điểm kiểm tra Toán: 8; 9; 7\" là số liệu hay dữ liệu không là số?","dapAn":"Số liệu","giaiThich":"Các giá trị được ghi bằng số."},{"de":"\"Mức độ hài lòng: Rất hài lòng, Hài lòng, Không hài lòng\" là loại dữ liệu nào?","dapAn":"Dữ liệu không là số, có thể sắp thứ tự","giaiThich":"Ghi bằng chữ nhưng sắp được từ cao đến thấp."}]'::jsonb),
  ('VBH-PL-02', 'Với dữ liệu ghi bằng chữ, nhiều bạn chưa phân biệt được loại nào sắp xếp được, loại nào không. Mẹo nhỏ: thử xếp chúng "từ thấp đến cao".', 'Dữ liệu không là số có thể sắp thứ tự khi các giá trị có mức độ hơn kém (Rất thích > Thích > Không thích; Tốt > Khá > Đạt). Không thể sắp thứ tự khi các giá trị chỉ là tên gọi (màu sắc, môn học, quê quán).', '[{"de":"\"Màu áo yêu thích: xanh, đỏ, trắng\" có sắp thứ tự được không?","giai":"Cách nghĩ sai: xếp theo bảng chữ cái là sắp được. Cách đúng: không có màu nào \"hơn\" màu nào về mức độ, nên đây là dữ liệu không thể sắp thứ tự."},{"de":"\"Mức độ tham gia: Thường xuyên, Thỉnh thoảng, Không bao giờ\" có sắp thứ tự được không?","giai":"Có. Các giá trị chỉ mức độ từ nhiều đến ít."}]'::jsonb, '[{"de":"\"Môn thể thao yêu thích\" là loại dữ liệu nào?","dapAn":"Không là số, không thể sắp thứ tự","giaiThich":"Tên các môn không có mức hơn kém."},{"de":"\"Kích cỡ áo: S, M, L, XL\" là loại dữ liệu nào?","dapAn":"Không là số, có thể sắp thứ tự","giaiThich":"Các cỡ xếp được từ nhỏ đến lớn."}]'::jsonb),
  ('VBH-PL-03', 'Mỗi loại dữ liệu có cách thu thập phù hợp. Chọn sai cách thì dữ liệu không đúng hoặc không lấy được.', 'Dữ liệu về những người, vật ở quanh em (chiều cao, sở thích của lớp) thu thập trực tiếp: đo, quan sát, phỏng vấn, phiếu hỏi. Dữ liệu đã được công bố (dân số, sản lượng các năm) thu thập gián tiếp: sách báo, Internet, cơ quan thống kê.', '[{"de":"Muốn biết chiều cao các bạn trong lớp, nên thu thập thế nào?","giai":"Cách nghĩ sai: tra trên Internet. Cách đúng: Internet không có chiều cao của lớp em; phải dùng thước đo từng bạn."},{"de":"Muốn biết dân số Việt Nam năm 2019, nên thu thập thế nào?","giai":"Tra cứu số liệu của Tổng cục Thống kê (Internet, sách báo). Em không thể tự đếm dân số cả nước."}]'::jsonb, '[{"de":"Muốn biết các bạn trong lớp thích ăn sáng món gì, nên dùng cách nào?","dapAn":"Phỏng vấn hoặc phiếu hỏi","giaiThich":"Đây là ý kiến của từng bạn nên phải hỏi trực tiếp."},{"de":"Muốn biết số xe đi qua cổng trường từ 6 giờ 30 đến 7 giờ, nên dùng cách nào?","dapAn":"Quan sát và đếm","giaiThich":"Dữ liệu chỉ có được khi trực tiếp quan sát tại chỗ."}]'::jsonb),
  ('VBH-DD-01', 'Khi chỉ hỏi những bạn cùng sở thích, câu trả lời sẽ giống nhau và không phản ánh đúng cả tập thể.', 'Dữ liệu đại diện khi những người được hỏi gồm đủ các kiểu đối tượng trong tập thể cần kết luận (nhiều lớp, cả nam và nữ…). Nên chọn ngẫu nhiên ở mỗi nhóm.', '[{"de":"Hỏi các bạn trong đội tuyển Toán xem học sinh cả trường có thích Toán không. Kết quả có đại diện không?","giai":"Cách nghĩ sai: đội tuyển học giỏi nên kết quả đáng tin. Cách đúng: đội tuyển là nhóm đặc biệt thích Toán, kết quả sẽ cao hơn thực tế; không đại diện cho cả trường."},{"de":"Muốn biết món ăn sáng yêu thích của khối 7, chọn mẫu thế nào?","giai":"Mỗi lớp khối 7 chọn ngẫu nhiên vài bạn, có cả nam và nữ."}]'::jsonb, '[{"de":"Hỏi các bạn ở thư viện về thói quen đọc sách của cả lớp có đại diện không?","dapAn":"Không","giaiThich":"Bạn ở thư viện thường thích đọc sách hơn mức chung."},{"de":"Để biết thời gian ngủ của học sinh trường, nên chọn ai để hỏi?","dapAn":"Chọn ngẫu nhiên học sinh ở tất cả các lớp","giaiThich":"Như vậy mẫu có đủ các khối, các lớp."}]'::jsonb),
  ('VBH-DD-02', 'Hỏi vài người rồi kết luận cho cả trăm người là rất dễ sai, vì kết quả có thể chỉ là tình cờ.', 'Muốn kết luận cho một tập thể lớn, cần hỏi đủ nhiều người. Số người được hỏi càng ít thì kết luận càng kém tin cậy.', '[{"de":"Hỏi 4 bạn đều thích bơi, kết luận \"học sinh cả trường (600 bạn) đều thích bơi\". Đúng không?","giai":"Cách nghĩ sai: 100% số bạn được hỏi thích bơi nên đúng. Cách đúng: 4 bạn quá ít so với 600 bạn; cần hỏi nhiều bạn hơn ở nhiều lớp mới kết luận được."},{"de":"Hỏi 20 khách hàng của một hãng rồi nói \"95% người dân thích sản phẩm\". Có tin được không?","giai":"Không. Mẫu vừa ít vừa chỉ gồm khách hàng của hãng."}]'::jsonb, '[{"de":"Muốn kết luận về sở thích của 40 bạn trong lớp, hỏi 2 bạn có đủ không?","dapAn":"Không đủ","giaiThich":"2 bạn quá ít; nên hỏi cả lớp."},{"de":"Muốn biết ý kiến của lớp 40 bạn, cách nào tốt nhất?","dapAn":"Hỏi cả 40 bạn","giaiThich":"Lớp ít người nên hỏi hết là chính xác nhất."}]'::jsonb),
  ('VBH-DD-03', 'Dữ liệu có thể bị ghi nhầm. Trước khi dùng, em cần xem các con số có hợp lí với thực tế không.', 'Kiểm tra tính hợp lí: giá trị phải phù hợp thực tế (chiều cao học sinh khoảng 130–180 cm…); các tỉ lệ phần trăm của các phần trong một tổng thể phải cộng lại bằng 100%.', '[{"de":"Bảng chiều cao: 148; 152; 1 550; 147 (cm). Dữ liệu có hợp lí không?","giai":"Cách nghĩ sai: bạn thứ ba rất cao. Cách đúng: không học sinh nào cao 1 550 cm (15,5 m); có thể ghi nhầm 155 cm, cần hỏi lại."},{"de":"Tỉ lệ: Bóng đá 45%, Cầu lông 35%, Bơi 35%. Có hợp lí không?","giai":"Không: 45 + 35 + 35 = 115% > 100%."}]'::jsonb, '[{"de":"Bảng ghi tuổi của học sinh lớp 7: 12; 13; 13; 31. Số nào vô lí?","dapAn":"31","giaiThich":"Học sinh lớp 7 khoảng 12–13 tuổi; 31 có thể là ghi ngược 13."},{"de":"Các tỉ lệ 50%, 30%, 20% có hợp lí cho một biểu đồ hình quạt không?","dapAn":"Hợp lí","giaiThich":"Tổng là 100%."}]'::jsonb),
  ('VBH-HQ-01', 'Biểu đồ hình quạt tròn chia một hình tròn thành các phần. Nhiều bạn quên rằng cả hình tròn chính là 100%.', 'Cả hình tròn biểu diễn 100% dữ liệu. Tổng tỉ lệ các phần bằng 100%. Phần chưa biết = 100% − tổng các phần đã biết. Nửa hình tròn là 50%, một phần tư là 25%.', '[{"de":"Biểu đồ có các phần 35%, 25%, 15% và một phần chưa ghi. Phần đó bao nhiêu phần trăm?","giai":"Cách nghĩ sai: đoán bằng một phần đã có (25% hay 15%). Cách đúng: 100% − (35% + 25% + 15%) = 100% − 75% = 25%."},{"de":"Một biểu đồ ghi 50%, 30%, 25%. Có đúng không?","giai":"Không, vì tổng là 105%."}]'::jsonb, '[{"de":"Biểu đồ có ba phần 60%, 25% và phần còn lại. Phần còn lại là bao nhiêu?","dapAn":"15%","giaiThich":"100% − 85% = 15%."},{"de":"Hình quạt bằng một phần tư hình tròn ứng với bao nhiêu phần trăm?","dapAn":"25%","giaiThich":"100% : 4 = 25%."}]'::jsonb),
  ('VBH-HQ-02', 'Con số trên biểu đồ hình quạt tròn là phần trăm, không phải số người. Đọc nhầm sẽ làm sai mọi câu tính sau đó.', 'Tỉ lệ phần trăm cho biết một phần chiếm bao nhiêu so với tổng. Muốn có số lượng: số lượng = tổng số · tỉ lệ : 100.', '[{"de":"Lớp 40 bạn, phần \"Đọc sách\" chiếm 25%. Có bao nhiêu bạn thích đọc sách?","giai":"Cách nghĩ sai: 25 bạn. Cách đúng: 40 · 25 : 100 = 10 bạn."},{"de":"Phần \"Thể thao\" 40% và phần \"Xem phim\" 20% của cùng lớp. So sánh số bạn?","giai":"Số bạn thích thể thao gấp đôi số bạn thích xem phim (vì 40% = 2 · 20%), cụ thể 16 bạn và 8 bạn."}]'::jsonb, '[{"de":"Lớp 30 bạn, 10% thích cờ vua. Có bao nhiêu bạn?","dapAn":"3 bạn","giaiThich":"30 · 10 : 100 = 3."},{"de":"\"Có 20% học sinh đi bộ\" có nghĩa là có 20 học sinh đi bộ không?","dapAn":"Không","giaiThich":"Số học sinh còn phụ thuộc vào tổng số."}]'::jsonb),
  ('VBH-BDQ-01', 'Khi tính tỉ lệ phần trăm, nhiều bạn chia cho một nhóm khác hoặc cho số lớn nhất. Tỉ lệ phải luôn so với tổng.', 'Tỉ lệ phần trăm của một nhóm = (số đối tượng của nhóm : tổng số đối tượng) · 100%. Kiểm tra: tổng các tỉ lệ bằng 100%.', '[{"de":"Lớp 40 bạn: 10 bạn thích bóng rổ, 16 bạn thích bóng đá. Tỉ lệ bạn thích bóng rổ?","giai":"Cách nghĩ sai: 10 : 16 · 100% = 62,5%. Cách đúng: 10 : 40 · 100% = 25%."},{"de":"Cửa hàng bán 200 áo, 60 áo xanh. Tỉ lệ áo xanh?","giai":"60 : 200 · 100% = 30%."}]'::jsonb, '[{"de":"Đội 25 bạn, lớp 7B có 8 bạn. Tỉ lệ của lớp 7B?","dapAn":"32%","giaiThich":"8 : 25 · 100% = 32%."},{"de":"50 bạn, 20 bạn thích xoài. Tỉ lệ?","dapAn":"40%","giaiThich":"20 : 50 · 100% = 40%."}]'::jsonb),
  ('VBH-BDQ-02', 'Khi điền số vào biểu đồ hình quạt cho sẵn, có bạn điền theo thứ tự đề bài mà không nhìn kích thước hình quạt.', 'Hình quạt càng lớn thì tỉ lệ càng lớn. Sắp các tỉ lệ từ lớn đến nhỏ, rồi điền lần lượt vào các hình quạt từ lớn đến nhỏ. Mốc dễ nhớ: nửa hình tròn 50%, một phần tư 25%.', '[{"de":"Điền 15%, 40%, 35%, 10% vào bốn hình quạt có kích thước giảm dần.","giai":"Cách nghĩ sai: điền theo thứ tự đề 15% – 40% – 35% – 10%. Cách đúng: sắp lại 40% > 35% > 15% > 10% rồi điền theo kích thước giảm dần."},{"de":"Hình quạt gần bằng nửa hình tròn nên ghi 45% hay 10%?","giai":"Ghi 45%, vì nửa hình tròn là 50%."}]'::jsonb, '[{"de":"Hình quạt nhỏ nhất ứng với tỉ lệ nào trong 30%, 50%, 20%?","dapAn":"20%","giaiThich":"Tỉ lệ nhỏ nhất ứng với hình quạt nhỏ nhất."},{"de":"Hình quạt đúng bằng một phần tư hình tròn ghi tỉ lệ nào?","dapAn":"25%","giaiThich":"Một phần tư của 100% là 25%."}]'::jsonb),
  ('VBH-BDQ-03', 'Biểu đồ hình quạt tròn không dùng được cho mọi loại dữ liệu. Dùng sai loại biểu đồ sẽ khiến người đọc hiểu sai.', 'Dùng biểu đồ hình quạt tròn khi muốn so sánh các phần trong một tổng thể (các phần cộng lại thành 100%). Dùng biểu đồ đoạn thẳng khi muốn thấy một đại lượng thay đổi theo thời gian.', '[{"de":"Biểu diễn nhiệt độ trung bình 4 quý trong năm nên dùng biểu đồ nào?","giai":"Cách nghĩ sai: có 4 phần nên dùng hình quạt. Cách đúng: nhiệt độ các quý không cộng lại thành một tổng có ý nghĩa và thay đổi theo thời gian, nên dùng biểu đồ đoạn thẳng."},{"de":"Biểu diễn tỉ lệ các loại sách trong thư viện nên dùng biểu đồ nào?","giai":"Biểu đồ hình quạt tròn, vì các loại sách là các phần của toàn bộ thư viện."}]'::jsonb, '[{"de":"Dân số thành phố qua 10 năm nên dùng biểu đồ nào?","dapAn":"Biểu đồ đoạn thẳng","giaiThich":"Dữ liệu thay đổi theo thời gian."},{"de":"Tỉ lệ học sinh theo phương tiện đến trường nên dùng biểu đồ nào?","dapAn":"Biểu đồ hình quạt tròn","giaiThich":"Các nhóm là các phần của toàn trường."}]'::jsonb),
  ('VBH-PTQ-01', 'Khi tính số lượng từ phần trăm, lỗi hay gặp nhất là quên chia cho 100, ra kết quả lớn hơn cả tổng số.', 'a% của N bằng N · a : 100. Kiểm tra nhanh: kết quả phải nhỏ hơn N khi a < 100; dùng mốc 10% của N = N : 10 để ước lượng.', '[{"de":"Trường có 800 học sinh, 15% đi bộ. Có bao nhiêu bạn đi bộ?","giai":"Cách nghĩ sai: 800 · 15 = 12 000 bạn (nhiều hơn cả trường!). Cách đúng: 800 · 15 : 100 = 120 bạn. Ước lượng: 10% là 80 nên 15% khoảng 120."},{"de":"15% số học sinh là 120 bạn. Trường có bao nhiêu học sinh?","giai":"Tổng số = 120 : 15 · 100 = 800 học sinh."}]'::jsonb, '[{"de":"1 200 học sinh, 40% không tham gia câu lạc bộ. Có bao nhiêu bạn?","dapAn":"480 bạn","giaiThich":"1 200 · 40 : 100 = 480."},{"de":"25% số bạn là 10 bạn. Lớp có bao nhiêu bạn?","dapAn":"40 bạn","giaiThich":"10 : 25 · 100 = 40."}]'::jsonb),
  ('VBH-PTQ-02', 'Hai biểu đồ hình quạt của hai tập thể khác sĩ số thì không so sánh số lượng bằng cách nhìn phần trăm được.', 'Khi hai tổng thể có tổng số khác nhau: đổi mỗi tỉ lệ ra số lượng (tổng số · tỉ lệ : 100) rồi mới so sánh số lượng.', '[{"de":"Lớp A (30 bạn) 40% thích Toán; lớp B (50 bạn) 30% thích Toán. Lớp nào nhiều bạn thích Toán hơn?","giai":"Cách nghĩ sai: lớp A vì 40% > 30%. Cách đúng: lớp A có 12 bạn, lớp B có 15 bạn, nên lớp B nhiều hơn."},{"de":"Năm ngoái 600 bạn, 30% đi xe đạp; năm nay 800 bạn, 25% đi xe đạp. Số bạn đi xe đạp tăng hay giảm?","giai":"Năm ngoái 180 bạn, năm nay 200 bạn: tăng 20 bạn, dù tỉ lệ giảm."}]'::jsonb, '[{"de":"Trường X (500 HS) có 20% đeo kính, trường Y (300 HS) có 30% đeo kính. Trường nào có nhiều HS đeo kính hơn?","dapAn":"Trường X","giaiThich":"100 bạn so với 90 bạn."},{"de":"Muốn so sánh số lượng ở hai biểu đồ quạt khác tổng số, bước đầu tiên là gì?","dapAn":"Đổi tỉ lệ ra số lượng","giaiThich":"Tỉ lệ chỉ so sánh được khi cùng tổng số."}]'::jsonb),
  ('VBH-DT-01', 'Biểu đồ đoạn thẳng có hai trục với vai trò khác nhau. Đọc nhầm trục hoặc quên đơn vị sẽ ra con số sai hoàn toàn.', 'Trục ngang: thời gian (năm, tháng, giờ…). Trục đứng: giá trị của đại lượng, có ghi đơn vị (nghìn tấn, triệu người, °C…). Đọc giá trị: từ mốc thời gian đi thẳng lên đến điểm, rồi đi ngang sang trục đứng, đọc kèm đơn vị.', '[{"de":"Trục đứng ghi \"triệu người\", điểm năm 2019 ở vạch 96,2. Dân số năm 2019?","giai":"Cách nghĩ sai: 96,2 người. Cách đúng: 96,2 triệu người, vì phải đọc kèm đơn vị trên trục đứng."},{"de":"Điểm nằm chính giữa vạch 40 và 50, đơn vị nghìn lượt khách. Đọc giá trị?","giai":"Khoảng 45 nghìn lượt khách."}]'::jsonb, '[{"de":"Trục ngang của biểu đồ nhiệt độ trong ngày biểu diễn gì?","dapAn":"Thời gian (giờ)","giaiThich":"Trục ngang luôn là thời gian."},{"de":"Trục đứng ghi \"nghìn tấn\", điểm ở vạch 14. Sản lượng?","dapAn":"14 nghìn tấn","giaiThich":"Đọc kèm đơn vị."}]'::jsonb),
  ('VBH-DT-02', 'Có bạn thấy điểm nằm cao thì cho là "đang tăng". Thật ra tăng hay giảm phụ thuộc vào chiều của đoạn thẳng.', 'Đi từ trái sang phải: đoạn thẳng đi lên là tăng, đi xuống là giảm, nằm ngang là không đổi. So sánh giá trị sau với giá trị trước.', '[{"de":"Sản lượng năm 2019 là 15, năm 2020 là 14 (nghìn tấn). Tăng hay giảm?","giai":"Cách nghĩ sai: tăng vì vẫn trên 10 nghìn tấn. Cách đúng: 14 < 15, đoạn thẳng đi xuống, nên giảm 1 nghìn tấn."},{"de":"Kỉ lục chạy 100 m giảm từ 9,95 giây xuống 9,58 giây. Kỉ lục nhanh hơn hay chậm hơn?","giai":"Đường đi xuống nghĩa là thời gian giảm, tức là chạy nhanh hơn."}]'::jsonb, '[{"de":"Nhiệt độ 13 giờ là 35 °C, 16 giờ là 33 °C. Tăng hay giảm?","dapAn":"Giảm 2 °C","giaiThich":"33 < 35."},{"de":"Đoạn thẳng nằm ngang cho biết điều gì?","dapAn":"Đại lượng không đổi","giaiThich":"Hai giá trị bằng nhau."}]'::jsonb),
  ('VBH-DT-03', 'Khi tìm giai đoạn tăng nhiều nhất, nhiều bạn chọn giai đoạn có giá trị cao nhất. Nhưng mức tăng là hiệu giữa hai mốc.', 'Mức tăng (giảm) của một giai đoạn = giá trị sau − giá trị trước. Tính hiệu cho từng giai đoạn rồi so sánh. Trên biểu đồ, đoạn dốc nhất là đoạn tăng (giảm) nhiều nhất.', '[{"de":"Các năm 2018–2022: 12; 15; 14; 18; 19. Giai đoạn tăng nhiều nhất?","giai":"Cách nghĩ sai: 2021–2022 vì năm 2022 cao nhất. Cách đúng: các mức thay đổi +3; −1; +4; +1, nên 2020–2021 tăng nhiều nhất (+4)."},{"de":"Số học sinh đeo kính: 80; 95; 120; 130. Tăng nhiều nhất khi nào?","giai":"Mức tăng +15; +25; +10, nên giai đoạn thứ hai (+25)."}]'::jsonb, '[{"de":"Các giá trị 50; 70; 75; 78. Giai đoạn tăng nhiều nhất là giai đoạn mấy?","dapAn":"Giai đoạn đầu (+20)","giaiThich":"Các mức tăng là 20; 5; 3."},{"de":"Lượng mưa 150; 320; 610; 380 mm. Tăng nhiều nhất giữa hai mốc nào?","dapAn":"320 và 610 (+290 mm)","giaiThich":"Mức tăng lần lượt 170; 290."}]'::jsonb),
  ('VBH-VDT-01', 'Biểu đồ chỉ đúng khi hai trục được chia đều. Chia vạch tuỳ ý sẽ làm biểu đồ "nói dối".', 'Chọn một bước chia cố định (ví dụ 10) và chia đều trục đứng: 0; 10; 20; 30… Các mốc thời gian trên trục ngang xếp theo thứ tự tăng dần, cách đều nhau.', '[{"de":"Chia trục đứng 0; 5; 10; 20; 40 với các vạch cách đều. Có đúng không?","giai":"Cách nghĩ sai: vạch cách đều là đúng. Cách đúng: khoảng 0–5 và 20–40 dài bằng nhau nhưng chênh lệch khác nhau (5 và 20), nên sai. Phải chia 0; 10; 20; 30; 40."},{"de":"Số trận thắng 15 đến 42, nên chia trục đứng thế nào?","giai":"Chia 0; 10; 20; 30; 40; 50 cách đều."}]'::jsonb, '[{"de":"Dữ liệu từ 23 đến 34 °C, bước chia hợp lí cho trục đứng?","dapAn":"5 °C (0; 5; 10; …; 35)","giaiThich":"Bước đều, phủ được giá trị lớn nhất."},{"de":"Trục ngang ghi 2019; 2017; 2020; 2018 có đúng không?","dapAn":"Không","giaiThich":"Phải xếp tăng dần 2017; 2018; 2019; 2020."}]'::jsonb),
  ('VBH-VDT-02', 'Sau khi chia trục, bước vẽ điểm và nối điểm dễ bị nhầm vị trí hoặc nhầm thứ tự.', 'Mỗi điểm: thẳng trên mốc thời gian, ngang với giá trị trên trục đứng. Nối các điểm liên tiếp theo thứ tự thời gian từ trái sang phải. Cuối cùng ghi tiêu đề và đơn vị.', '[{"de":"Ngày 4 cây đậu cao 1,4 cm. Đặt điểm ở đâu?","giai":"Cách nghĩ sai: ngang vạch 4 cm vì là ngày 4. Cách đúng: thẳng trên mốc \"ngày 4\", ngang vạch 1,4 cm."},{"de":"Đã có điểm các năm 2017–2020. Nối thế nào?","giai":"Nối 2017 → 2018 → 2019 → 2020, không nối theo giá trị thấp lên cao."}]'::jsonb, '[{"de":"Lúc 10 giờ nhiệt độ 25 °C. Điểm nằm ở đâu?","dapAn":"Trên mốc 10 giờ, ngang vạch 25 °C","giaiThich":"Thời gian ở trục ngang, giá trị ở trục đứng."},{"de":"Bước cuối cùng khi vẽ biểu đồ đoạn thẳng là gì?","dapAn":"Ghi tiêu đề (và chú thích nếu có)","giaiThich":"Theo 4 bước SGK."}]'::jsonb)
on conflict (content_id) do update set dan = excluded.dan, quy_tac = excluded.quy_tac,
  vi_du = excluded.vi_du, tu_lam = excluded.tu_lam, updated_at = now();

-- ===========================================================================
-- NGÂN HÀNG HOẠT ĐỘNG CHƯƠNG II–V (bản nháp; giữ nguyên nếu giáo viên đã sửa)
-- ===========================================================================
insert into mm_activities
  (activity_id, ten, error_codes, nhom, hinh_thuc, muc_nhan_thuc, phut_min, phut_max, mo_ta, hoc_lieu, trang_thai, nguon)
values
  ('HD-VHT-01', 'Máy tính kể chuyện chia mãi', array['E-VHT-01', 'E-VHT-02', 'E-VHT-03']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 8, 10, 'Nhóm chia tay 1/3, 5/6, 7/12, 3/8 rồi khoanh nhóm chữ số lặp lại, viết dạng chu kì. Phân loại mẫu số theo ước nguyên tố (chỉ có 2, 5 hay có số khác) để dự đoán trước khi chia.', 'Phiếu chia 4 phân số, bảng phân loại mẫu số', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TRON-01', 'Làm tròn trên trục số phóng to', array['E-TRON-01', 'E-TRON-02', 'E-TRON-03']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Mỗi nhóm có đoạn trục số phóng to (ví dụ từ 4,7 đến 4,8 chia 10 vạch), đặt số cần làm tròn rồi xem gần mốc nào hơn. Đổi độ chính xác d (0,5; 0,05) ra hàng làm tròn; thử với số âm và so sánh làm tròn một bước với nhiều bước.', 'Băng trục số phóng to, thẻ số', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-VOTI-01', 'Đo chu vi chiếc nắp tìm số pi', array['E-VOTI-01', 'E-VOTI-03']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Nhóm đo chu vi và đường kính 3 vật tròn, tính tỉ số; so với 3,14 và 22/7; đọc đoạn giới thiệu về pi để thấy 3,14 chỉ là giá trị gần đúng, pi là số thập phân vô hạn không tuần hoàn.', 'Vật tròn, thước dây, máy tính cầm tay', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TAPR-01', 'Sơ đồ Ven các tập số', array['E-VOTI-02', 'E-TAPR-01', 'E-TAPR-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Nhóm dán 15 thẻ số (−3; 0,(3); √2; π; 5/7; 0,1010010001…; √9…) vào sơ đồ Ven N ⊂ Z ⊂ Q ⊂ R và vùng số vô tỉ. Viết quan hệ bao hàm theo chiều từ trong ra ngoài.', 'Sơ đồ Ven khổ A3, 15 thẻ số', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-CANB-01', 'Hình vuông và căn bậc hai', array['E-CANB-01', 'E-CANB-02', 'E-CANB-04']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Căn bậc hai số học của a là cạnh của hình vuông có diện tích a. Nhóm tìm cạnh các hình vuông diện tích 9, 16, 25 trên giấy kẻ ô, so với "chia đôi"; thảo luận vì sao cạnh không âm và không có hình vuông diện tích âm.', 'Giấy kẻ ô', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-CANB-02', 'Thử bằng số: căn của tổng', array['E-CANB-03', 'E-SSTR-02']::text[], array['loi']::text[], 'ca-nhan', 2, 5, 8, 'Học sinh tính √(9 + 16) và √9 + √16; so √0,25 với 0,25 và √4 với 4. Mỗi em viết một câu "phản ví dụ" cho mỗi niềm tin sai.', 'Phiếu 6 phép tính, máy tính cầm tay', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-SSTR-01', 'Xếp hàng trên trục số thực', array['E-SSTR-01', 'E-SSTR-02']::text[], array['loi']::text[], 'ca-lop', 2, 7, 10, '7 học sinh cầm thẻ −√5; −2; −1,5; 0; √2; 1,5; √3 đứng xếp theo thứ tự trên trục số kẻ dưới sàn. Cả lớp phát hiện chỗ đứng sai và giải thích bằng quy tắc so sánh số âm.', 'Trục số dán sàn, 7 thẻ số', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-GTTD-01', 'Khoảng cách đến 0', array['E-GTTD-01', 'E-GTTD-02', 'E-GTTD-03']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Trên trục số, nhóm đánh dấu các điểm cách 0 đúng 3 đơn vị (được hai điểm), đo khoảng cách từ −7 đến 0. Từ đó viết quy tắc |x| = x khi x ≥ 0, |x| = −x khi x < 0 và giải |x| = 2,5.', 'Trục số, compa', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C2-MR', 'Đường chéo hình vuông và số vô tỉ', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 10, 15, 'Nhóm đã làm chủ dựng đoạn thẳng dài √2 và √5 trên giấy kẻ ô (đường chéo hình chữ nhật), đặt lên trục số và ước lượng giá trị; trình bày 2 phút.', 'Giấy kẻ ô, compa', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-KB-01', 'Gấp giấy tìm kề bù và đối đỉnh', array['E-KB-01', 'E-KB-02', 'E-DDI-01']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 8, 10, 'Gấp tờ giấy theo hai nếp cắt nhau, mở ra được bốn góc. Nhóm tô cùng màu các cặp đối đỉnh, ghi tổng các cặp kề bù, đo để thấy đối đỉnh bằng nhau và kề bù có tổng 180°. Sau đó phân loại 6 thẻ hình: kề bù / đối đỉnh / không phải.', 'Giấy A4, thước đo góc, 6 thẻ hình', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-PG-01', 'Gấp góc tìm tia phân giác', array['E-PG-01', 'E-PG-02']::text[], array['loi']::text[], 'ca-nhan', 1, 6, 8, 'Cắt một góc bằng giấy, gấp cho hai cạnh trùng nhau: nếp gấp là tia phân giác. Đo hai góc tạo thành, viết quan hệ "một nửa – gấp đôi". So sánh với một tia nằm giữa nhưng không phải phân giác.', 'Giấy màu, thước đo góc', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-SLT-01', 'Chữ Z, chữ F, chữ C', array['E-SLT-01', 'E-TCSS-01']::text[], array['loi']::text[], 'ca-lop', 2, 7, 10, 'Giáo viên giới thiệu mẹo hình chữ: so le trong nằm trong chữ Z, đồng vị nằm trong chữ F, trong cùng phía nằm trong chữ C. Cả lớp giơ thẻ Z/F/C cho từng cặp góc trên hình chiếu.', 'Thẻ Z, F, C; hình cát tuyến', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-SLT-02', 'Đo thử khi không song song', array['E-SLT-02', 'E-DHSS-01']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Dùng GeoGebra (hoặc hình in) xoay đường b quanh B: quan sát cặp so le trong chỉ bằng nhau khi a // b. Nhóm viết lại câu dấu hiệu và câu tính chất, chỉ ra chiều suy luận của mỗi câu.', 'GeoGebra hoặc hai hình in (song song / không song song)', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DHSS-01', 'Vẽ song song bằng ê ke', array['E-DHSS-01', 'E-DHSS-02', 'E-EUC-01']::text[], array['loi']::text[], 'ca-nhan', 2, 8, 10, 'Học sinh vẽ đường thẳng qua M song song với a bằng cách trượt ê ke dọc thước và bằng hai lần vẽ vuông góc. Giải thích mỗi cách dựa vào dấu hiệu nào; thử vẽ đường song song thứ hai qua M để thấy trùng.', 'Ê ke, thước', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TCSS-01', 'Kẻ thêm đường song song', array['E-TCSS-01', 'E-TCSS-02']::text[], array['loi', 'on-dinh']::text[], 'nhom-dong-chat', 3, 10, 12, 'Nhóm giải bài "góc gãy" giữa hai đường song song bằng cách kẻ thêm đường song song qua đỉnh góc; trình bày từng bước có căn cứ (so le trong, đồng vị, trong cùng phía bù nhau).', 'Phiếu 3 bài tính góc', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DL-01', 'Tách Nếu – thì và tìm phản ví dụ', array['E-DL-01', 'E-DL-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Nhóm nhận 6 thẻ câu phát biểu, viết lại dạng "Nếu … thì …", gạch chân GT và KL, viết bằng kí hiệu. Với mỗi câu đảo, nhóm tìm một phản ví dụ hoặc giải thích vì sao đúng.', '6 thẻ định lí', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C3-MR', 'Thiết kế hình có nhiều đường song song', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm đã làm chủ thiết kế một bài tính góc (có ít nhất hai đường song song và một tia phân giác) kèm lời giải, đổi cho nhóm khác giải.', 'Giấy A4, thước, thước đo góc', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TBG-01', 'Xé ba góc ghép thành góc bẹt', array['E-TBG-01', 'E-TBG-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 7, 10, 'Mỗi em cắt một tam giác giấy khác nhau (to, nhỏ, nhọn, tù), xé ba góc ghép sát nhau thành góc bẹt. Cả nhóm so sánh và rút ra tổng ba góc luôn 180°; thử vẽ tam giác có hai góc vuông để thấy không vẽ được.', 'Giấy màu, kéo', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TBG-02', 'Góc ngoài bằng hai cách', array['E-TBG-03']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 7, 10, 'Nhóm tính góc ngoài tại một đỉnh bằng hai cách (180° − góc trong kề; tổng hai góc trong không kề), so hai kết quả. Đo lại bằng thước đo góc trên hình in sẵn.', 'Phiếu 4 tam giác, thước đo góc', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-BN-01', 'Ghép đỉnh bằng tam giác giấy chồng khít', array['E-BN-01', 'E-BN-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 8, 10, 'Hai tam giác giấy bằng nhau, ghi tên đỉnh khác nhau. Học sinh xoay, lật cho chồng khít, nối các đỉnh trùng nhau bằng mũi tên rồi mới viết kí hiệu. Đổi vai: một em đọc kí hiệu, em kia chỉ cạnh, góc tương ứng.', 'Cặp tam giác giấy bằng nhau', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-CC-01', 'Tô màu yếu tố bằng nhau', array['E-CC-01', 'E-CCC-01']::text[], array['loi']::text[], 'ca-nhan', 2, 6, 8, 'Trên 4 hình in sẵn, học sinh tô cùng màu các cặp cạnh (góc) bằng nhau: theo giả thiết, cạnh chung, góc chung, góc đối đỉnh. Đếm đủ ba cặp mới được ghi tên trường hợp.', 'Phiếu 4 hình, bút màu', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-CGC-01', 'Thử dựng tam giác từ hai cạnh và một góc', array['E-CGC-01', 'E-TGV-03']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 10, 12, 'Nhóm dựng tam giác với AB = 4 cm, AC = 3 cm và góc B = 40° (góc không xen giữa) bằng GeoGebra hoặc thước compa: thấy có hai tam giác khác nhau. Sau đó dựng lại với góc A xen giữa: chỉ một tam giác.', 'GeoGebra hoặc thước, compa', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-GCG-01', 'Ba góc bằng nhau nhưng to nhỏ khác nhau', array['E-GGG-01', 'E-GCG-01', 'E-TGV-02']::text[], array['loi']::text[], 'ca-lop', 2, 6, 8, 'Giáo viên giơ hai ê ke 30°–60° cỡ nhỏ và cỡ lớn, hỏi "có bằng nhau không?". Học sinh chỉ ra cần thêm một cặp cạnh, rồi chọn đúng cạnh kề hai góc cho trường hợp g.c.g.', 'Hai ê ke khác cỡ', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TGV-01', 'Bảng chọn trường hợp tam giác vuông', array['E-TGV-01', 'E-TGV-02', 'E-TGV-03']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Mỗi nhóm nhận 8 thẻ tình huống hai tam giác vuông (cho biết cạnh, góc). Nhóm đánh dấu cạnh huyền bằng màu đỏ, rồi xếp thẻ vào 5 ô: hai cạnh góc vuông · cạnh góc vuông – góc nhọn kề · cạnh huyền – góc nhọn · cạnh huyền – cạnh góc vuông · chưa đủ.', '8 thẻ tình huống, bảng 5 ô', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TGC-01', 'Gấp tam giác cân', array['E-TGC-01', 'E-TGC-02', 'E-TGC-03']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 8, 10, 'Học sinh gấp đôi tờ giấy, cắt ra tam giác cân, gấp theo trục để thấy hai góc ở đáy trùng nhau. Ghi tên đỉnh, cạnh bên, cạnh đáy; tính góc ở đáy khi biết góc ở đỉnh và ngược lại; thử góc ở đỉnh 60°.', 'Giấy A4, kéo, thước đo góc', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-TTR-01', 'Gấp giấy tìm trung trực', array['E-TTR-01', 'E-TTR-02']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 10, 'Đánh dấu A, B trên giấy, gấp cho A trùng B: nếp gấp là trung trực. Lấy vài điểm trên nếp gấp đo MA, MB; lấy điểm ngoài nếp gấp để thấy không cách đều. Sau đó vẽ trung trực bằng compa.', 'Giấy A4, thước, compa', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C4-MR', 'Đo khoảng cách qua ao', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm đã làm chủ thiết kế cách đo khoảng cách giữa hai điểm không đến được (qua ao, qua tường) bằng tam giác bằng nhau, vẽ sơ đồ và viết chứng minh, trình bày 2 phút.', 'Giấy A3, thước dây (nếu đo ngoài sân)', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-PL-01', 'Phân loại thẻ dữ liệu ba ngăn', array['E-PL-01', 'E-PL-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 8, 10, 'Mỗi nhóm nhận 12 thẻ dữ liệu (48 kg; Khá; màu xanh; Rất thích; 3 anh chị em; Đà Nẵng…), xếp vào ba ngăn: Số liệu · Không là số, sắp được thứ tự · Không là số, không sắp được thứ tự. Nhóm giải thích một thẻ khó nhất trước lớp.', 'Bộ 12 thẻ dữ liệu, bảng ba ngăn', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-PL-02', 'Chọn công cụ thu thập', array['E-PL-03']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 7, 10, 'Giáo viên đưa 6 câu hỏi cần trả lời (chiều cao lớp, dân số tỉnh, món ăn yêu thích…). Nhóm ghép mỗi câu với một cách thu thập: đo, quan sát, phỏng vấn, phiếu hỏi, tra cứu, rồi nêu lí do.', 'Phiếu ghép 6 câu hỏi – 5 cách thu thập', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DD-01', 'Ai được hỏi? Thí nghiệm mẫu lệch', array['E-DD-01', 'E-DD-02']::text[], array['loi']::text[], 'ca-lop', 2, 8, 12, 'Cả lớp giơ tay trả lời một câu hỏi sở thích. Giáo viên ghi kết quả của "chỉ bàn cuối", "chỉ tổ 1", "3 bạn bất kì" và "cả lớp" lên bảng. Học sinh so sánh và tự rút ra điều kiện để mẫu đại diện.', 'Bảng ghi kết quả 4 cách chọn mẫu', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DD-02', 'Thám tử dữ liệu', array['E-DD-03', 'E-HQ-01']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 7, 10, 'Mỗi nhóm nhận 4 bảng dữ liệu, mỗi bảng giấu một chỗ vô lí (chiều cao 1 550 cm, tổng tỉ lệ 115%…). Nhóm khoanh chỗ sai và đề xuất cách sửa.', '4 bảng dữ liệu có lỗi', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-HQ-01', 'Gấp hình tròn giấy', array['E-HQ-01', 'E-BDQ-02']::text[], array['loi']::text[], 'nhom-dong-chat', 1, 8, 10, 'Học sinh gấp hình tròn giấy thành 2, 4, 8 phần bằng nhau, ghi 50%, 25%, 12,5% lên từng phần. Sau đó tô màu biểu đồ 40% – 35% – 15% – 10% cho sẵn và kiểm tra tổng bằng 100%.', 'Hình tròn giấy, biểu đồ quạt chia sẵn', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-HQ-02', 'Đổi phần trăm ra người thật', array['E-HQ-02', 'E-PTQ-01', 'E-BDQ-01']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 10, 12, 'Dùng chính số liệu của lớp: mỗi nhóm đếm số bạn theo từng lựa chọn, tính tỉ lệ phần trăm (chia cho sĩ số), rồi làm ngược lại từ phần trăm ra số bạn. Hai chiều tính phải khớp nhau.', 'Phiếu hai chiều: số bạn ⇄ phần trăm', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-PTQ-01', 'Hai lớp, hai biểu đồ', array['E-PTQ-02']::text[], array['loi', 'san-sang']::text[], 'nhom-dong-chat', 3, 8, 12, 'Nhóm nhận hai biểu đồ quạt của hai lớp có sĩ số khác nhau. Trước khi tính, mỗi em dự đoán lớp nào có nhiều bạn thích Toán hơn; sau đó đổi ra số bạn và so sánh với dự đoán.', 'Hai biểu đồ quạt, sĩ số hai lớp', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-BDQ-01', 'Quạt hay đoạn thẳng?', array['E-BDQ-03']::text[], array['loi']::text[], 'ca-lop', 2, 5, 8, 'Giáo viên chiếu 8 bộ dữ liệu, cả lớp giơ thẻ "Quạt" hoặc "Đoạn thẳng". Sau mỗi lượt, một em giải thích bằng câu hỏi: "Các giá trị có cộng lại thành một tổng không? Có thay đổi theo thời gian không?"', 'Thẻ hai mặt Quạt / Đoạn thẳng, 8 bộ dữ liệu', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DT-01', 'Đọc biểu đồ bằng ngón tay', array['E-DT-01']::text[], array['loi']::text[], 'ca-nhan', 1, 5, 8, 'Học sinh đặt ngón tay lên mốc thời gian, đi thẳng lên tới điểm rồi đi ngang sang trục đứng, đọc to giá trị kèm đơn vị. Bạn cùng bàn kiểm tra đơn vị đọc có đúng không.', 'Biểu đồ đoạn thẳng in khổ lớn', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-DT-02', 'Mũi tên lên – xuống và thước đo độ tăng', array['E-DT-02', 'E-DT-03']::text[], array['loi']::text[], 'nhom-dong-chat', 2, 8, 12, 'Nhóm vẽ mũi tên ↗ ↘ → lên từng đoạn của biểu đồ, rồi ghi mức tăng (giảm) = giá trị sau − giá trị trước dưới mỗi đoạn. Khoanh đoạn có hiệu lớn nhất và so với đoạn có giá trị cao nhất.', 'Biểu đồ in sẵn, bút màu', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-VDT-01', 'Vẽ biểu đồ dữ liệu của lớp mình', array['E-VDT-01', 'E-VDT-02']::text[], array['loi', 'on-dinh']::text[], 'nhom-dong-chat', 3, 12, 15, 'Mỗi nhóm vẽ biểu đồ đoạn thẳng số bạn nộp bài chuẩn bị đúng hạn của lớp trong 4–5 tuần, theo 4 bước SGK. Các nhóm đổi biểu đồ cho nhau và chấm theo bảng kiểm: trục chia đều, mốc theo thứ tự, điểm đúng, có tiêu đề.', 'Giấy kẻ ô, bảng kiểm 4 tiêu chí, số liệu của lớp', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng'),
  ('HD-C5-MR', 'Điều tra mini và báo cáo bằng biểu đồ', array[]::text[], array['san-sang']::text[], 'nhom-dong-chat', 4, 12, 15, 'Nhóm đã làm chủ tự đặt một câu hỏi khảo sát, thu thập dữ liệu của lớp, chọn loại biểu đồ phù hợp, vẽ và nêu một nhận xét. Trình bày 2 phút cuối tiết.', 'Phiếu kế hoạch điều tra, giấy A3', 'nhap', 'Bản nháp do trợ lý AI soạn theo từ điển mã lỗi — giáo viên cần duyệt, sửa trước khi dùng')
on conflict (activity_id) do nothing;

-- ------------------------------------------------ KIỂM TRA SAU KHI CHẠY
select left(ku_id, 2) as chuong, count(*) as so_cau, count(hinh) as co_hinh
from questions where ku_id like 'C3-%' or ku_id like 'C4-%' or ku_id like 'C5-%' group by 1 order by 1;
